import{t as e}from"./flagUrl-Do2cQcqz.js";var t=t=>e(t),n={CA:[{fromYear:1965,toYear:null,flagUrl:`/Global/flags/ca.svg`,label:`The Maple Leaf Flag`,note:`Adopted February 15, 1965 after a passionate national debate. The single red maple leaf on a white field was chosen over dozens of competing designs after months of parliamentary argument known as the "Great Canadian Flag Debate."`},{fromYear:1957,toYear:1965,flagUrl:t(`Canadian_Red_Ensign_%281957-1965%29.svg`),label:`Canadian Red Ensign (1957–1965)`,note:`A Red Ensign defaced with the updated 1957 Canadian coat of arms. This flag was flown on federal buildings and represented Canada internationally in the years immediately before the Maple Leaf was adopted.`},{fromYear:1921,toYear:1957,flagUrl:t(`Canadian_Red_Ensign_%281921-1957%29.svg`),label:`Canadian Red Ensign (1921–1957)`,note:`The Red Ensign bearing the 1921 Canadian coat of arms, which added the fleurs-de-lis of France and the English lions. This version was used after Canada formally received its own coat of arms from the Crown.`},{fromYear:1868,toYear:1921,flagUrl:t(`Canadian_Red_Ensign_1868-1921.svg`),label:`Canadian Red Ensign (1868–1921)`,note:`The earliest Canadian Red Ensign, defaced with the shield of the original four provinces at Confederation: Ontario, Quebec, Nova Scotia, and New Brunswick. Used informally as Canada expanded westward.`},{fromYear:1837,toYear:1838,flagUrl:t(`Flag_of_the_Patriote_movement_(Lower_Canada).svg`),label:`Patriote Movement (Lower Canada)`,note:`During the 1837–38 rebellions, French-Canadian Patriotes in Lower Canada (Quebec) flew a green-white-red horizontal tricolor against British colonial rule. The uprising was crushed, but the flag endures as a Québécois nationalist symbol.`},{fromYear:1534,toYear:1763,flagUrl:t(`Pavillon_royal_de_la_France.svg`),label:`New France`,note:`For over two centuries before British rule, the St Lawrence valley and a vast arc of the continent from Acadia to Louisiana were New France — the French colonial empire of fur traders, missionaries and habitants, flying the royal banner of the French crown (gold fleurs-de-lis on blue). France ceded it to Britain in 1763 after the Seven Years' War, but its language, faith and place names endure across Quebec and beyond.`}],US:[{fromYear:1960,toYear:null,flagUrl:`/Global/flags/us.svg`,label:`50-Star Flag`,note:`Adopted July 4, 1960, the day after Hawaii became the 50th state. Designed by 17-year-old Robert Heft as a school project — his teacher gave him a B minus but later raised the grade when the design was officially selected.`},{fromYear:1912,toYear:1959,flagUrl:t(`US_flag_48_stars.svg`),label:`48-Star Flag`,note:`The longest-serving version of the US flag at 47 years, used from the admission of New Mexico and Arizona in 1912 until Alaska joined in 1959. This was the flag flown through both World Wars.`},{fromYear:1877,toYear:1912,flagUrl:t(`US_flag_38_stars.svg`),label:`38-Star Flag (Centennial Era)`,note:`Flown during the American centennial celebrations of 1876 and used through the Gilded Age. Colorado joined in 1876 to bring the count to 38. By 1912 five more states had joined, each adding a star on the following July 4th.`},{fromYear:1818,toYear:1877,flagUrl:t(`US_flag_20_stars.svg`),label:`Westward Expansion (20–37 Stars)`,note:`The Act of 1818 froze the stripes at 13 — one per original colony — and added one new star per state admitted, effective each July 4th. Across this era the count rose from 20 to 37 as America expanded across the continent through the Civil War and Reconstruction.`,parallelCaption:`Breakaway republics of the era`,parallel:[{fromYear:1836,toYear:1839,flagUrl:t(`Flag_of_the_Republic_of_Texas_(1836–1839).svg`),label:`Republic of Texas (Burnet Flag)`,note:`After winning independence from Mexico in 1836, the Republic of Texas first flew the Burnet Flag — a single gold star on azure — before adopting the Lone Star flag in 1839. Texas was an independent nation for nearly a decade before joining the US in 1845.`},{fromYear:1861,toYear:1861,flagUrl:t(`Flag_of_Mississippi_Variant_(1861).svg`),label:`Republic of Mississippi (Magnolia Flag)`,note:`When Mississippi seceded in January 1861 it briefly flew the "Magnolia Flag" — a magnolia tree on white with a lone-star canton — before joining the Confederacy. Mississippi revived the magnolia on its state flag in 2020.`}]},{fromYear:1795,toYear:1818,flagUrl:t(`US_flag_15_stars.svg`),label:`15-Star, 15-Stripe Flag`,note:`After Vermont (1791) and Kentucky (1792) joined, both the stars and stripes were bumped to 15. This is the flag that flew over Fort McHenry during the British bombardment in 1814 — the sight that inspired Francis Scott Key to write what became "The Star-Spangled Banner."`,parallelCaption:`Breakaway republic of the era`,parallel:[{fromYear:1810,toYear:1810,flagUrl:t(`Bonnie_Blue_flag.svg`),label:`Republic of West Florida`,note:`For 90 days in 1810, English-speaking settlers in Spanish West Florida revolted and flew the "Bonnie Blue" — a single white star on blue. The US annexed the territory the same year, but the lone-star motif lived on in Texas and Confederate symbolism.`}]},{fromYear:1777,toYear:1795,flagUrl:t(`US_flag_13_stars_%E2%80%93_Betsy_Ross.svg`),label:`Betsy Ross Flag (13 Stars)`,note:`One of the earliest Stars and Stripes, with 13 stars in a circle representing the original colonies. Commonly attributed to Philadelphia seamstress Betsy Ross, though the historical evidence for this attribution is limited.`}],GB:[{fromYear:1801,toYear:null,flagUrl:`/Global/flags/gb.svg`,label:`Union Jack (Current)`,note:`Created in 1801 when Ireland joined Great Britain. Combines St George's Cross (England), St Andrew's Cross (Scotland), and St Patrick's Cross (Ireland). The red diagonal is deliberately offset so the Scottish white saltire is not obscured.`},{fromYear:1707,toYear:1800,flagUrl:t(`Flag_of_Great_Britain_%281707%E2%80%931800%29.svg`),label:`Flag of Great Britain (1707–1800)`,note:`Created by the Acts of Union 1707 joining England and Scotland. Combined only St George's Cross and St Andrew's Cross. Ireland had not yet joined, so there is no red diagonal of St Patrick.`},{fromYear:1606,toYear:1707,flagUrl:t(`Union_flag_1606_(Kings_Colors).svg`),label:`King's Colours (Union of the Crowns)`,note:`When James VI of Scotland also became James I of England in 1603, the two crowns were united under one king though the kingdoms stayed separate. In 1606 he ordered this first Union Flag — St George over St Andrew — flown at sea. It served as a royal and maritime banner for a century before the 1707 union made it the flag of the new Kingdom of Great Britain.`}],RU:[{fromYear:1993,toYear:null,flagUrl:`/Global/flags/ru.svg`,label:`Russian Federation`,note:`The white-blue-red tricolor was restored after the fall of the Soviet Union and fixed in its current 2:3 proportions by decree in 1993, then confirmed by federal law in 2000. The colors trace back to Peter the Great.`},{fromYear:1991,toYear:1993,flagUrl:t(`Flag_of_Russia_(1991-1993).svg`),label:`Russian Federation (1991 transitional)`,note:`When Russia re-adopted the historic tricolor in 1991 the first version used a slightly lighter shade and longer 1:2 proportions, before the design was standardized two years later.`},{fromYear:1922,toYear:1991,flagUrl:t(`Flag_of_the_Soviet_Union.svg`),label:`Soviet Union`,note:`The red banner with a gold hammer, sickle, and star symbolized the union of workers and peasants. It flew over the USSR for nearly seven decades until the country dissolved in December 1991.`,parallelCaption:`Russian SFSR within the USSR`,parallel:[{fromYear:1954,toYear:1991,flagUrl:t(`Flag_of_the_Russian_Soviet_Federative_Socialist_Republic_(1954–1991).svg`),label:`Russian SFSR`,note:`Russia itself was one republic inside the union. From 1954 it flew the Soviet flag with a light-blue band at the hoist to distinguish it from the all-union banner.`}]},{fromYear:1920,toYear:1922,flagUrl:t(`Flag_of_Far_Eastern_Republic.svg`),label:`Far Eastern Republic`,note:`A nominally independent buffer state created by Soviet Russia in 1920 to avoid direct war with Japan, which occupied parts of the Russian Far East during the Civil War. Its red flag bore a blue canton lettered "DVR." Once Japanese forces withdrew in 1922, the republic dissolved itself into Soviet Russia.`},{fromYear:1858,toYear:1896,flagUrl:t(`Flag_of_the_Russian_Empire_(black-yellow-white).svg`),label:`Russian Empire (imperial colors)`,note:`Decreed by Alexander II in 1858, the black-yellow-white flag drew on the heraldic colors of the imperial coat of arms. It served as the official state flag for nearly four decades before the tricolor was restored.`},{fromYear:1696,toYear:1858,flagUrl:t(`Flag_of_Russia.svg`),label:`Tsardom of Russia (Petrine tricolor)`,note:`Peter the Great introduced the white-blue-red tricolor in the 1690s for the merchant fleet, modeled on the Dutch flag. Restored again in 1896, it is the direct ancestor of the modern Russian flag.`},{fromYear:1921,toYear:1944,flagUrl:t(`Flag_of_the_Tuvan_People's_Republic_(1943-1944).svg`),label:`Tuvan People's Republic`,note:`A nominally independent Soviet-aligned state in southern Siberia that was quietly annexed into the USSR in 1944.`},{fromYear:1917,toYear:1922,flagUrl:t(`Flag_of_the_Confederated_Republic_of_Altai.svg`),label:`Confederated Republic of Altai`,note:`A short-lived attempt at an autonomous Altai state in the Russian Civil War's Siberian chaos.`},{fromYear:1914,toYear:1921,flagUrl:t(`Tannu_Uriankhai_Recreated_Banner.png`),label:`Uryankhay Krai`,note:`The Russian protectorate over Tuva, between Mongolia and Siberia, before the Tuvan People's Republic.`}],CN:[{fromYear:1949,toYear:null,flagUrl:`/Global/flags/cn.svg`,label:`People's Republic of China`,note:`Designed by Zeng Liansong and adopted in 1949, the large gold star represents the Communist Party while the four smaller stars represent the united classes of the Chinese people. The design was chosen from nearly 3,000 public submissions.`},{fromYear:1928,toYear:1949,flagUrl:t(`Flag_of_the_Republic_of_China.svg`),label:`Republic of China`,note:`The "Blue Sky with a White Sun" canton — its twelve rays marking the twelve two-hour periods of the day — was adopted nationally in 1928 after the Kuomintang unified China. It remains the flag of Taiwan today.`},{fromYear:1912,toYear:1928,flagUrl:t(`Flag_of_the_Republic_of_China_1912-1928.svg`),label:`Republic of China (Five-Colored Flag)`,note:`The five stripes — red, yellow, blue, white, and black — stood for "Five Races Under One Union": the Han, Manchu, Mongol, Hui, and Tibetan peoples. It served the Beiyang government until the Northern Expedition.`},{fromYear:1889,toYear:1912,flagUrl:t(`Flag_of_the_Qing_dynasty_(1889-1912).svg`),label:`Qing Dynasty (Yellow Dragon)`,note:`The Azure Dragon chasing a red flaming pearl on a yellow field — yellow being the imperial color of the ruling house. An earlier triangular version dated to 1862 before the rectangular flag was standardized.`},{fromYear:1938,toYear:1940,flagUrl:t(`Flag_of_China_(1912–1928).svg`),label:`Reformed Government of the Republic of China`,note:`A Japanese-sponsored collaborationist government in occupied central China.`},{fromYear:1935,toYear:1938,flagUrl:t(`Flag_of_the_East_Hebei_Autonomous_Government.svg`),label:`East Hebei Autonomous Government`,note:`A Japanese puppet regime in northern China, a stepping stone to the wider invasion.`},{fromYear:1932,toYear:1945,flagUrl:t(`Flag_of_Manchukuo.svg`),label:`Manchukuo`,note:`The Japanese puppet empire in Manchuria, fronted by Puyi, China's last emperor — dissolved when the USSR invaded in 1945.`},{fromYear:1931,toYear:1934,flagUrl:t(`Chinese_soviet_flag.svg`),label:`Jiangxi–Fujian Soviet`,note:`The Chinese Soviet Republic, Mao Zedong's first base area, abandoned at the start of the Long March.`},{fromYear:1895,toYear:1895,flagUrl:t(`Flag_of_the_Republic_of_Formosa_(1895).svg`),label:`Republic of Formosa`,note:`A short-lived republic declared on Taiwan to resist the island's cession to Japan; it lasted only months.`},{fromYear:1642,toYear:1717,flagUrl:t(`Standard_of_Gushri_khan.png`),label:`Khoshut Khanate`,note:`A Mongol khanate that ruled Tibet and installed the Fifth Dalai Lama's government before the Qing took control.`},{fromYear:1661,toYear:1683,flagUrl:t(`Flag_of_Ming_Cheng.svg`),label:`Kingdom of Tungning`,note:`The Ming-loyalist kingdom founded on Taiwan by the warlord Koxinga, who expelled the Dutch — the first Han Chinese state to rule the island, until the Qing took it.`}],JP:[{fromYear:1870,toYear:null,flagUrl:`/Global/flags/jp.svg`,label:`Japan (Hinomaru)`,note:`The white field with a central red disc — the Nisshōki, or "sun-mark flag" — was designated the national merchant ensign in 1870. Though used for centuries before, it was only formally legislated as the national flag in 1999.`},{fromYear:1870,toYear:1945,flagUrl:t(`War_flag_of_the_Imperial_Japanese_Army.svg`),label:`Rising Sun (Imperial military)`,note:`A military banner, not the national flag: the Imperial Japanese Army adopted this 16-ray Rising Sun design in 1870. It became closely associated with Japan's wartime expansion until 1945.`,parallelCaption:`Imperial Japanese Navy ensign`,parallel:[{fromYear:1889,toYear:null,flagUrl:t(`Naval_Ensign_of_Japan.svg`),label:`Naval ensign`,note:`The Navy's version offsets the sun toward the hoist. Controversially, the modern Japan Maritime Self-Defense Force readopted it in 1954, so it still flies at sea today.`}]},{fromYear:1603,toYear:1868,flagUrl:t(`Flag_of_the_Tokugawa_Shogunate.svg`),label:`Tokugawa shogunate`,note:`The Edo-period military government of the Tokugawa shoguns that unified Japan and sealed it off from the world for over two centuries.`},{fromYear:1429,toYear:1879,flagUrl:t(`Merchant_flag_of_the_Ryukyu_Kingdom.svg`),label:`Ryukyu Kingdom`,note:`An independent island kingdom that traded across East Asia and paid tribute to China, annexed by Japan as Okinawa Prefecture.`}],AU:[{fromYear:1908,toYear:null,flagUrl:`/Global/flags/au.svg`,label:`Australian National Flag`,note:`In 1908 a seventh point was added to the large Commonwealth Star to represent the territories. The blue ensign was confirmed as the sole national flag by the Flags Act 1953, effective 1954.`,parallelCaption:`Red Ensign — flown on land before 1954`,parallel:[{fromYear:1908,toYear:null,flagUrl:t(`Civil_Ensign_of_Australia.svg`),label:`Australian Red Ensign`,note:`For decades most Australians actually flew the red version on land; only in 1954 did the blue ensign officially take precedence. It remains the flag of Australian-registered merchant ships.`}]},{fromYear:1903,toYear:1908,flagUrl:t(`Flag_of_Australia_(1903–1908).svg`),label:`Blue Ensign (six-pointed star)`,note:`In 1903 the Southern Cross stars were standardized, but the large Commonwealth Star still had only six points — one for each federating colony.`},{fromYear:1901,toYear:1903,flagUrl:t(`Flag_of_Australia_(1901–1903).svg`),label:`1901 Federation Design`,note:`The winning entry from the 1901 Federal Flag Design Competition, chosen from 32,823 submissions. The original Southern Cross stars had varying point counts (from five to nine points).`},{fromYear:1801,toYear:1901,flagUrl:t(`Flag_of_the_United_Kingdom.svg`),label:`Union Jack (pre-Federation)`,note:`Before the colonies federated into the Commonwealth of Australia in 1901, the Union Jack was the primary flag flown across the Australian colonies.`}],NZ:[{fromYear:1902,toYear:null,flagUrl:`/Global/flags/nz.svg`,label:`Flag of New Zealand`,note:`The Southern Cross blue ensign — four red, white-bordered stars — became the national flag on land and sea under the Ensign Act 1901. The design itself dates to 1869; New Zealanders voted to keep it in two referendums in 2015–16.`},{fromYear:1867,toYear:1869,flagUrl:t(`Flag_of_New_Zealand_Government_Ships_1867.svg`),label:`Colonial Blue Ensign ('NZ')`,note:`An 1867 warrant required colonial government vessels to fly the Blue Ensign defaced with the red letters "NZ" — the first distinctly New Zealand ensign, before the Southern Cross replaced the lettering in 1869.`},{fromYear:1840,toYear:1867,flagUrl:t(`Flag_of_the_United_Kingdom.svg`),label:`Union Jack (Crown Colony)`,note:`After the Treaty of Waitangi in 1840 made New Zealand a British colony, the Union Jack served as its flag for use on land.`},{fromYear:1834,toYear:1840,flagUrl:t(`Flag_of_the_United_Tribes_of_New_Zealand.svg`),label:`United Tribes of New Zealand`,note:`The very first flag of New Zealand, chosen by a vote of Māori chiefs at James Busby's residence on 20 March 1834. A St George's Cross with a blue canton bearing four white eight-pointed stars.`}],FR:[{fromYear:1830,toYear:null,flagUrl:`/Global/flags/fr.svg`,label:`France (tricolore)`,note:`Louis-Philippe, the "citizen-king", restored the blue-white-red tricolore in 1830, and it has flown through every French republic and regime since. A slightly darker navy shade was quietly reintroduced in 2020.`},{fromYear:1814,toYear:1830,flagUrl:t(`Flag_of_France_(1814–1830).svg`),label:`Bourbon Restoration`,note:`When the Bourbons returned after Napoleon's fall, the tricolore and its revolutionary associations were dropped for the plain white royalist flag. The July Revolution of 1830 swept it away for good.`},{fromYear:1794,toYear:1814,flagUrl:t(`Flag_of_France.svg`),label:`First Republic & Napoleon`,note:`In 1794 the tricolore was fixed as three equal vertical bands of blue, white, and red — the exact design still used today. It flew over the First Republic and Napoleon's First Empire.`},{fromYear:1790,toYear:1794,flagUrl:t(`Flag_of_France_(1790–1794).svg`),label:`Revolution (early tricolore)`,note:`The first revolutionary flag placed blue at the hoist and red at the fly — the reverse of the modern order — before the bands were swapped to their familiar arrangement in 1794.`},{fromYear:1589,toYear:1790,flagUrl:t(`Royal_Standard_of_the_King_of_France.svg`),label:`Kingdom of France (Bourbon)`,note:`The white royal standard strewn with golden fleurs-de-lis was the emblem of the Ancien Régime monarchy. White was the dynastic color of the House of Bourbon until the Revolution.`},{fromYear:1794,toYear:1796,flagUrl:t(`Flag_of_the_Anglo-Corsican_Kingdom.svg`),label:`Anglo-Corsican Kingdom`,note:`A brief Corsican kingdom under British protection during the French Revolutionary Wars.`},{fromYear:1755,toYear:1769,flagUrl:t(`Flag_of_Corsica.svg`),label:`Corsican Republic`,note:`Pasquale Paoli's enlightened Corsican republic — with one of the first democratic constitutions — before France bought and conquered the island.`},{fromYear:959,toYear:1766,flagUrl:t(`Flag_of_Lorraine.svg`),label:`Duchy of Lorraine`,note:`A long-independent duchy between France and the German lands, passed to France only in 1766.`},{fromYear:939,toYear:1547,flagUrl:t(`Drapeau_de_la_province_de_Bretagne_(1532).svg`),label:`Duchy of Brittany`,note:`An independent Celtic duchy with its own language and parliament, joined to the French crown by royal marriage in the 16th century.`},{fromYear:1736,toYear:1736,flagUrl:t(`Flag_of_Corsica_(before_1755).svg`),label:`Kingdom of Corsica`,note:`The improbable few-month kingdom of Theodor von Neuhoff, a German adventurer crowned king by Corsican rebels against Genoa.`},{fromYear:1050,toYear:1620,flagUrl:t(`Flag_of_Béarn.svg`),label:`Viscounty of Béarn`,note:`An independent Pyrenean state — the homeland of King Henry IV — that kept its own laws and parliament until merged into France.`}],DE:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/de.svg`,label:`Germany (reunified)`,note:`On reunification in 1990 the West German black-red-gold tricolour became the flag of the whole country, with no change to the design. The colors are tied to the liberal revolutions of 1848.`},{fromYear:1949,toYear:1990,flagUrl:t(`Flag_of_Germany.svg`),label:`West Germany (Federal Republic)`,note:`The Federal Republic readopted the Weimar black-red-gold tricolour in 1949. This plain flag won out as the flag of the reunified nation in 1990 and is still used today.`,parallelCaption:`Germany divided — East & West (1949–1990)`,parallel:[{fromYear:1959,toYear:1990,flagUrl:t(`Flag_of_East_Germany.svg`),label:`East Germany (GDR)`,note:`The communist East used the same tricolour as the West until 1959, when it added the socialist emblem of hammer, compass and rye wreath. The flag vanished with reunification in 1990.`}]},{fromYear:1935,toYear:1945,flagUrl:t(`Flag_of_the_German_Reich_(1935–1945).svg`),label:`Nazi Germany`,note:`The 1935 Reich Flag Law made the swastika banner the sole national flag of Nazi Germany, the regime that started the Second World War in Europe and carried out the Holocaust. The Allies abolished it after the regime's defeat in 1945, and its public display is banned in Germany today outside education, art and research.`},{fromYear:1933,toYear:1935,flagUrl:t(`Flag_of_Germany_(1933–1935).svg`),label:`Nazi Germany (transitional)`,note:`After Hitler took power in 1933 the black-red-gold flag was banned, and for two years the old imperial black-white-red tricolour flew alongside the Nazi Party swastika as co-equal national flags.`},{fromYear:1919,toYear:1933,flagUrl:t(`Flag_of_Germany_(3-2_aspect_ratio).svg`),label:`Weimar Republic`,note:`The Weimar Constitution of 1919 adopted the black-red-gold tricolour, colors of the 1848 democratic movement. The choice was bitterly fought by conservatives who favored the old imperial colors.`},{fromYear:1867,toYear:1918,flagUrl:t(`Flag_of_Germany_(1867–1918).svg`),label:`German Empire`,note:`The black-white-red tricolour served the North German Confederation from 1867 and then the unified German Empire from 1871, until the monarchy collapsed at the end of World War I.`},{fromYear:1863,toYear:1918,flagUrl:t(`Flag_of_Anhalt_Duchies.svg`),label:`Duchy of Anhalt`,note:`The Duchy of Anhalt was a sovereign German state — ancestral home of the House of Ascania, from which Catherine the Great of Russia descended. Its green-white-red tricolor flew until the German monarchies fell in 1918. Anhalt is today part of Saxony-Anhalt.`},{fromYear:1816,toYear:1866,flagUrl:t(`Flag_of_the_Free_City_of_Frankfurt.svg`),label:`Free City of Frankfurt`,note:`Before unification, Frankfurt was a sovereign city-state and seat of the German Confederation's parliament, flying a white-and-red civic flag until Prussia annexed it in 1866 for siding with Austria. It was one of the historic Free Cities, alongside Hamburg and Bremen.`},{fromYear:1814,toYear:1866,flagUrl:t(`Flag_of_Hanover_(1692).svg`),label:`Kingdom of Hanover`,note:`A north German kingdom in personal union with the British crown until 1837, annexed by Prussia after backing the losing side in 1866.`},{fromYear:1807,toYear:1813,flagUrl:t(`Flag_of_Kingdom_of_Westphalia.svg`),label:`Kingdom of Westphalia`,note:`A short-lived Napoleonic client kingdom in western Germany, ruled by Napoleon's brother Jérôme Bonaparte as a 'model state'.`},{fromYear:1806,toYear:1918,flagUrl:t(`Flag_of_Bavaria_(striped).svg`),label:`Kingdom of Bavaria`,note:`The second-largest kingdom of the German Empire, ruled from Munich by the Wittelsbachs, whose white-and-blue lozenges are still Bavaria's emblem.`},{fromYear:1805,toYear:1918,flagUrl:t(`Wurttflag.png`),label:`Kingdom of Württemberg`,note:`A south-western German kingdom centred on Stuttgart, a constituent state of the German Empire until the 1918 revolution.`}],AT:[{fromYear:1945,toYear:null,flagUrl:`/Global/flags/at.svg`,label:`Austria (Second Republic)`,note:`With independence restored in 1945, Austria reinstated the red-white-red triband. Legend ties it to a medieval Babenberg duke whose white tunic was left red but for the band under his belt — one of the oldest flag designs still in use.`},{fromYear:1938,toYear:1945,flagUrl:t(`Flag_of_the_German_Reich_(1935–1945).svg`),label:`Anschluss (annexed by Nazi Germany)`,note:`Following the Anschluss of March 1938, Austria ceased to exist as an independent state and the Nazi German flag flew over its territory until liberation in 1945.`},{fromYear:1934,toYear:1938,flagUrl:t(`State_flag_of_Austria_(1934–1938).svg`),label:`Federal State (Ständestaat)`,note:`The authoritarian Austrofascist Federal State kept the red-white-red bands but added a state emblem with a double-headed eagle and the crutch-cross. It ended with the Nazi annexation.`},{fromYear:1918,toYear:1934,flagUrl:t(`Flag_of_Austria.svg`),label:`First Austrian Republic`,note:`After the empire collapsed, the new republic adopted the red-white-red triband that is essentially the modern Austrian flag.`},{fromYear:1869,toYear:1918,flagUrl:t(`Civil_ensign_of_Austria-Hungary_(1869-1918).svg`),label:`Austria-Hungary`,note:`The Dual Monarchy used a combined civil ensign joining the Austrian red-white-red with the Hungarian colors, while the black-gold Habsburg flag remained in dynastic use until 1918.`,parallelCaption:`Habsburg dynastic flag`,parallel:[{fromYear:1804,toYear:1867,flagUrl:t(`Flag_of_the_Habsburg_Monarchy.svg`),label:`Austrian Empire (Habsburg)`,note:`The black-gold horizontal bicolour was the dynastic flag of the House of Habsburg, derived from their long reign as Holy Roman Emperors.`}]}],IT:[{fromYear:1946,toYear:null,flagUrl:`/Global/flags/it.svg`,label:`Italian Republic`,note:`After the 1946 referendum abolished the monarchy, the Savoy royal arms were removed, leaving the plain green-white-red tricolore enshrined in the 1948 Constitution. It remains Italy's flag today.`},{fromYear:1861,toYear:1946,flagUrl:t(`Flag_of_Italy_(1861–1946).svg`),label:`Kingdom of Italy`,note:`On unification in 1861 the tricolore carried the coat of arms of the House of Savoy at its centre. This flag flew for 85 years through both World Wars until the monarchy was abolished.`},{fromYear:1848,toYear:1849,flagUrl:t(`Flag_of_the_Republic_of_San_Marco.svg`),label:`Republic of San Marco (Venice)`,note:`During the 1848 revolutions, Venice rose against Austrian rule and proclaimed the Republic of San Marco under Daniele Manin, placing the gold Winged Lion of Saint Mark on the Italian tricolor. Austria besieged and retook the city in 1849 after seventeen months — one of the last holdouts of the revolutionary wave.`},{fromYear:1802,toYear:1814,flagUrl:t(`Flag_of_the_Italian_Republic_(1802).svg`),label:`Napoleonic Kingdom of Italy`,note:`A striking design of a red field bearing a white lozenge enclosing a green square. Adopted by Napoleon's Italian Republic in 1802, it carried over when he made himself King of Italy in 1805.`},{fromYear:1797,toYear:1802,flagUrl:t(`Flag_of_the_Cispadane_Republic.svg`),label:`Cispadane Republic (first tricolore)`,note:`On 7 January 1797 in Reggio Emilia, the Cispadane Republic adopted a green-white-red tricolour — the very first official use of the Italian tricolore as a national flag.`},{fromYear:839,toYear:1131,flagUrl:t(`Flag_of_the_Republic_of_Amalfi.svg`),label:`Duchy of Amalfi`,note:`Amalfi was one of the first Italian maritime republics, a Mediterranean trading power from the 9th to 12th centuries that rivalled Venice, Pisa, and Genoa. Its banner bore a white cross on blue — later associated with the Order of Malta. Norman conquest in 1131 ended its independence.`},{fromYear:1816,toYear:1861,flagUrl:t(`Flag_of_the_Kingdom_of_the_Two_Sicilies_(1816).svg`),label:`Kingdom of the Two Sicilies`,note:`The largest of the pre-unification Italian states — Naples and Sicily under the Bourbons — conquered by Garibaldi's Redshirts and folded into a united Italy.`}],ES:[{fromYear:1981,toYear:null,flagUrl:`/Global/flags/es.svg`,label:`Kingdom of Spain`,note:`The current flag, fixed in 1981, bears the constitutional coat of arms with the Pillars of Hercules and the quartered arms of Castile, León, Aragón, and Navarre. The red-yellow-red scheme dates to 1785.`},{fromYear:1977,toYear:1981,flagUrl:t(`Flag_of_Spain_(1977–1981).svg`),label:`Spain (Transition)`,note:`After Franco's death the eagle of the dictatorship's flag was widened and the design softened, a transitional step while the new democratic constitution of 1978 took shape.`},{fromYear:1945,toYear:1977,flagUrl:t(`Flag_of_Spain_(1945–1977).svg`),label:`Francoist Spain`,note:`Franco's flag restored the red-yellow-red bands and added the Eagle of Saint John bearing the medieval royal arms with the yoke-and-arrows of the Catholic Monarchs. It flew for most of his dictatorship.`},{fromYear:1931,toYear:1939,flagUrl:t(`Flag_of_the_Second_Spanish_Republic.svg`),label:`Second Spanish Republic`,note:`The Republic replaced the red-yellow-red with a tricolour of red, yellow, and murrey (purple), the purple honouring the Castilian Comuneros. It was abolished by Franco's victory in the Civil War.`},{fromYear:1785,toYear:1931,flagUrl:t(`Flag_of_Spain_(1785–1873,_1875–1931).svg`),label:`Kingdom of Spain (Bourbon)`,note:`In 1785 Charles III chose the now-iconic red-yellow-red design as a high-visibility naval ensign, later extended to land. This basic scheme persisted through the monarchy and Bourbon Restoration.`},{fromYear:1506,toYear:1785,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Cross of Burgundy`,note:`A red knotted saltire on a white field served as the de facto flag of the Spanish Empire under the Habsburgs and early Bourbons, flying over its global possessions and armies for nearly three centuries.`}],ZA:[{fromYear:1994,toYear:null,flagUrl:`/Global/flags/za.svg`,label:`Rainbow flag`,note:`Designed by Frederick Brownell and first flown on 27 April 1994 at the dawn of democracy, it is the only national flag with six colors. The Y-shape is widely read as the convergence of a diverse society onto a single path forward.`},{fromYear:1928,toYear:1994,flagUrl:t(`Flag_of_South_Africa_(1928–1994).svg`),label:`Oranje-Blanje-Blou`,note:`Based on the orange-white-blue Dutch Prinsenvlag, with three tiny flags centered on the white band — the Union Jack and the flags of the old Orange Free State and Transvaal republics. It became internationally synonymous with the apartheid era.`},{fromYear:1910,toYear:1928,flagUrl:t(`Red_Ensign_of_South_Africa_(1912–1928,_with_coat_of_arms).svg`),label:`South African Red Ensign`,note:`After the Union of South Africa formed in 1910, the British Red Ensign defaced with the Union coat of arms served as the de facto flag, while the Union Jack remained the only flag with full official status.`},{fromYear:1857,toYear:1902,flagUrl:t(`Flag_of_Transvaal.svg`),label:`South African Republic (Transvaal)`,note:`In the interior, Dutch-descended Boer settlers fleeing British rule founded their own republics — the South African Republic (Transvaal), whose green-banded "Vierkleur" flew over the gold-rich Witwatersrand. The discovery of that gold drew the British in, and the two sides fought the bitter Second Boer War (1899–1902); the republic's defeat paved the way for the Union of South Africa.`},{fromYear:1854,toYear:1902,flagUrl:t(`Flag_of_the_Orange_Free_State.svg`),label:`Orange Free State`,note:`The other main Boer republic, the Orange Free State, flew an orange-and-white flag with the Dutch tricolour in the canton. Like the Transvaal it was independent for half a century before being annexed by Britain in the Boer War — both republics' flags were later miniaturised onto the apartheid-era national flag.`},{fromYear:1981,toYear:1994,flagUrl:t(`Flag_of_Ciskei.svg`),label:`Ciskei`,note:`A small apartheid-era Bantustan for Xhosa people in the Eastern Cape, dissolved into democratic South Africa in 1994.`},{fromYear:1977,toYear:1994,flagUrl:t(`Flag_of_Bophuthatswana_(1972–1994).svg`),label:`Bophuthatswana`,note:`A fragmented apartheid-era Bantustan for Tswana people, reabsorbed into South Africa at the end of apartheid.`},{fromYear:1976,toYear:1994,flagUrl:t(`Flag_of_Transkei.svg`),label:`Transkei`,note:`The first of apartheid South Africa's nominally independent Black 'homelands' (Bantustans), recognised by no other country.`},{fromYear:1886,toYear:1891,flagUrl:t(`Flag_of_Klein_Vrystaat_-_2.svg`),label:`Klein Vrystaat`,note:`A minuscule Boer 'Little Free State' that voluntarily joined the South African Republic after a few years.`},{fromYear:1884,toYear:1888,flagUrl:t(`Flag_of_Nieuwe_Republiek.svg`),label:`Nieuwe Republiek`,note:`A Boer 'New Republic' carved out of Zululand around Vryheid, later joined to the Transvaal.`},{fromYear:1882,toYear:1883,flagUrl:t(`Flag_of_the_Republic_of_Goshen.svg`),label:`State of Goshen`,note:`A tiny Boer freebooter republic on the Transvaal border, later folded into British Bechuanaland.`},{fromYear:1882,toYear:1885,flagUrl:t(`First_flag_of_Stellaland.svg`),label:`Republic of Stellaland`,note:`A small Boer republic proclaimed by frontier farmers, named for a comet, annexed into British Bechuanaland.`},{fromYear:1870,toYear:1880,flagUrl:t(`FlagGriekwalandEast.svg`),label:`Griqualand West`,note:`A Griqua state on the Cape frontier annexed by Britain after diamonds were found at Kimberley.`},{fromYear:1861,toYear:1879,flagUrl:t(`FlagGriekwalandEast.svg`),label:`Griqualand East`,note:`A Griqua state in the eastern Cape settled after a great trek over the Drakensberg, later annexed by the Cape Colony.`},{fromYear:1839,toYear:1843,flagUrl:t(`Flag_of_Natalia_Republic.svg`),label:`Natalia Republic`,note:`A short-lived Boer republic in Natal, founded by Voortrekkers after the defeat of the Zulu, soon annexed by Britain.`},{fromYear:1835,toYear:1864,flagUrl:t(`South_African_Burgers_Flag.svg`),label:`Republic of Zoutpansberg`,note:`An isolated Boer republic in the far north of the Transvaal, eventually absorbed into the South African Republic.`}],PT:[{fromYear:1911,toYear:null,flagUrl:`/Global/flags/pt.svg`,label:`Republican flag`,note:`Adopted in 1911 after the Republic was proclaimed, replacing royal blue-and-white with green and red. The arms sit on an armillary sphere recalling the Age of Discoveries, placed over the boundary of the two colors.`},{fromYear:1830,toYear:1910,flagUrl:t(`Flag_of_Portugal_(1830–1910).svg`),label:`Constitutional Monarchy`,note:`A field split blue at the hoist and white at the fly, with the crowned royal arms over an armillary sphere on the dividing line. It flew until the revolution of 5 October 1910 overthrew the monarchy.`},{fromYear:1707,toYear:1816,flagUrl:t(`Flag_of_Portugal_(1707).svg`),label:`White flag with royal arms`,note:`A plain white field bearing the Portuguese royal coat of arms, used through the reigns of John V, Joseph I and Maria I. The white field carried no meaning of its own until colors were added in the 19th century.`}],NL:[{fromYear:1796,toYear:null,flagUrl:`/Global/flags/nl.svg`,label:`Red-white-blue tricolour`,note:`The modern red-white-blue continued through the Batavian Republic, Kingdom, and present day; its bright vermilion red was officially fixed by royal decree in 1937. Orange survives in the pennant flown above the flag on royal occasions.`},{fromYear:1660,toYear:1795,flagUrl:t(`Statenvlag.svg`),label:`Statenvlag (States Flag)`,note:`Orange was gradually swapped for red between roughly 1630 and 1660 — partly because red was more visible at sea, partly to signal the Republic's growing distance from the House of Orange. A 1664 resolution formally named the red-white-blue the "Statenvlag".`},{fromYear:1572,toYear:1660,flagUrl:t(`Prinsenvlag.svg`),label:`Prinsenvlag (Prince's Flag)`,note:`An orange-white-blue tricolour tied to William of Orange and the Dutch Revolt against Spain. It is the direct ancestor of today's flag and remains an emblem of the House of Orange.`}],GR:[{fromYear:1978,toYear:null,flagUrl:`/Global/flags/gr.svg`,label:`Nine-stripe flag`,note:`Adopted as the sole national flag in 1978, with nine alternating blue and white stripes and a white cross in the canton. Tradition links the nine stripes to the syllables of "Eleftheria i Thanatos" — "Freedom or Death".`},{fromYear:1970,toYear:1975,flagUrl:t(`Flag_of_Greece_(1970–1975).svg`),label:`Junta cross flag`,note:`During the military junta the plain cross land flag was rendered in a very dark navy blue and made the sole national flag in 1970. It was abolished after the restoration of democracy.`},{fromYear:1822,toYear:1978,flagUrl:t(`Flag_of_Greece_(1822-1978).svg`),label:`Blue land flag with white cross`,note:`Standardized by the Provisional Government in 1822 as the "land flag" — a plain blue field with a centered white cross. It served on and off as the national land flag for over 150 years.`},{fromYear:1769,toYear:1822,flagUrl:t(`Greek_Revolution_flag.svg`),label:`Revolution cross flag`,note:`A blue flag with a white cross used by Greek revolutionaries, first appearing in the 1769 Orlov Revolt and becoming the most widespread banner of the 1821 War of Independence. The cross symbolized the Orthodox faith that unified the fighters.`}],IE:[{fromYear:1922,toYear:null,flagUrl:`/Global/flags/ie.svg`,label:`Green-white-orange tricolour`,note:`First flown by Thomas Francis Meagher in 1848 and raised over the GPO during the 1916 Rising, the tricolour was used by the Irish Free State from 1922 and given constitutional status in 1937. Green represents Catholics, orange Protestants, and the white the hoped-for peace between them.`},{fromYear:1642,toYear:1916,flagUrl:t(`Green_harp_flag_of_Ireland.svg`),label:`Green flag with gold harp`,note:`A green field bearing a golden harp was recognized as the flag of Ireland from the mid-1600s and remained the dominant nationalist emblem right up to the 1916 Easter Rising. The same design survives today as the flag of Leinster.`,parallelCaption:`Saint Patrick's Saltire`,parallel:[{fromYear:1783,toYear:null,flagUrl:t(`Saint_Patrick's_Saltire.svg`),label:`St Patrick's Saltire`,note:`A red X-shaped cross on white, adopted by the Order of Saint Patrick in 1783 and folded into the Union Flag in 1801. Its status as a genuinely Irish symbol is disputed — it was largely an Anglo-Irish heraldic device.`}]}],PL:[{fromYear:1919,toYear:null,flagUrl:`/Global/flags/pl.svg`,label:`White-and-red bicolour`,note:`The Sejm officially adopted the horizontal white-over-red bicolour in 1919, and its basic design has been unchanged since — retained even throughout the communist People's Republic.`,parallelCaption:`State flag with eagle (used abroad & at sea)`,parallel:[{fromYear:1990,toYear:null,flagUrl:t(`Flag_of_Poland_(with_coat_of_arms).svg`),label:`State flag (crowned eagle)`,note:`The civil and state ensign adds the crowned white eagle in the white stripe. By law it is reserved for official use abroad, at sea, and at airports rather than general display.`}]},{fromYear:1980,toYear:1990,flagUrl:t(`Flag_of_Poland_(with_coat_of_arms,_1980-1990).svg`),label:`People's Republic state flag`,note:`The communist-era state ensign bore a white eagle stripped of its crown. The crown was restored to the eagle at the end of 1989 as communism fell.`},{fromYear:1919,toYear:1928,flagUrl:t(`Flag_of_Poland_(with_coat_of_arms,_1919-1928).svg`),label:`Second Republic state flag`,note:`The interwar state ensign charged with the crowned white eagle of the reborn Polish Republic, before the coat of arms was redesigned in 1927–28.`},{fromYear:1295,toYear:1795,flagUrl:t(`Flag_of_the_Kingdom_of_Poland.svg`),label:`Kingdom of Poland (royal banner)`,note:`Long before the modern white-and-red bicolor, the Kingdom of Poland — and the vast Polish-Lithuanian Commonwealth it formed in 1569 — was represented by the royal banner: the crowned white eagle on a red field, in use since the late 13th century. The white-and-red of the national colours is drawn directly from this eagle. The Commonwealth, once one of Europe's largest states, was carved up and erased by Russia, Prussia and Austria in the partitions ending in 1795.`}],IN:[{fromYear:1947,toYear:null,flagUrl:`/Global/flags/in.svg`,label:`Tricolour with Ashoka Chakra`,note:`Adopted on 22 July 1947, weeks before independence, it replaced the spinning wheel with the 24-spoke navy Ashoka Chakra. The wheel is taken from the Lion Capital of Ashoka at Sarnath.`},{fromYear:1931,toYear:1947,flagUrl:t(`1931_Flag_of_India.svg`),label:`Swaraj flag (1931)`,note:`Adopted by the Indian National Congress at its 1931 Karachi session, this tricolour put saffron on top and a navy spinning wheel (charkha) at the centre, dropping the earlier reading of the colors as communal.`},{fromYear:1921,toYear:1931,flagUrl:t(`1921_India_flag.svg`),label:`Swaraj flag (1921)`,note:`Designed by Pingali Venkayya and presented to Gandhi, it carried red and green bands with a charkha. Gandhi added the white band so that all of India's religious communities would be represented.`},{fromYear:1880,toYear:1947,flagUrl:t(`British_Raj_Red_Ensign.svg`),label:`Star of India (British Raj)`,note:`A red ensign with the Union Jack and the "Star of India" emblem, used unofficially for British India. The Union Jack itself remained the official flag of the Raj.`,parallelCaption:`Princely state of the Raj era`,parallel:[{fromYear:1936,toYear:1952,flagUrl:t(`Flag_of_Jammu_and_Kashmir_(1936-1953).svg`),label:`Princely State of Jammu and Kashmir`,note:`The princely state of Jammu and Kashmir was ruled by the Hindu Dogra dynasty over a Muslim-majority population under British paramountcy. Its disputed accession to India in 1947 triggered the first India-Pakistan war and a conflict that continues today. The state kept its own flag under special autonomy until that status was revoked in 2019.`}]},{fromYear:1799,toYear:1849,flagUrl:t(`Flag_of_the_Sikh_Empire.png`),label:`Sikh Empire`,note:`Ranjit Singh forged a powerful Sikh Empire across Punjab and the northwest (1799–1849), flying the saffron Nishan Sahib of the Khalsa. The last major Indian power to fall to the British, it was annexed only after two hard-fought Anglo-Sikh Wars — the same conquest that delivered the Koh-i-Noor diamond to the British crown.`},{fromYear:1674,toYear:1818,flagUrl:t(`Flag_of_the_Maratha_Empire.svg`),label:`Maratha Empire`,note:`Founded by Chhatrapati Shivaji in 1674, the Maratha Empire grew to dominate most of the subcontinent in the 18th century, flying the saffron Bhagwa Dhwaj. It was the principal Indian power the British East India Company had to defeat — in three Anglo-Maratha Wars — to win control of India.`},{fromYear:1526,toYear:1857,flagUrl:t(`Flag_of_the_Mughal_Empire_(triangular).svg`),label:`Mughal Empire`,note:`For over three centuries the Mughal Empire ruled much of India — the age of the Taj Mahal, of emperors Akbar and Aurangzeb — under the green Alam bearing a lion and rising sun. Its slow decline left the vacuum that regional powers and the British filled; the last emperor was deposed after the 1857 rebellion, formally ending Mughal rule.`},{fromYear:1399,toYear:1799,flagUrl:t(`Flag_of_Kingdom_of_Mysore.svg`),label:`Kingdom of Mysore`,note:`The Kingdom of Mysore, and especially the rule of Hyder Ali and his son Tipu Sultan, mounted the fiercest southern Indian resistance to the British. Tipu — the "Tiger of Mysore" — flew flags rich with tiger-stripe (bubri) motifs and even deployed some of the world's first iron-cased war rockets against the Company before his death in 1799.`},{fromYear:1729,toYear:1949,flagUrl:t(`Flag_of_Kingdom_of_Travancore.svg`),label:`Travancore`,note:`A princely state in Kerala famed for high literacy and the gold-laden Padmanabhaswamy Temple, joined to India at independence.`},{fromYear:1724,toYear:1948,flagUrl:t(`Asafia_flag_of_Hyderabad_State.svg`),label:`Hyderabad State`,note:`The largest and richest of British India's princely states, ruled by the Nizam, forcibly integrated into India in 1948.`},{fromYear:1518,toYear:1687,flagUrl:t(`Qutbshahi_Flag.svg`),label:`Sultanate of Golconda`,note:`A Deccan sultanate whose mines produced the world's most famous diamonds (the Koh-i-Noor and Hope) before Aurangzeb annexed it.`},{fromYear:1102,toYear:1949,flagUrl:t(`Cochin_flag.svg`),label:`Kingdom of Cochin`,note:`A princely state on the Kerala coast, an early partner of the Portuguese and Dutch in the spice trade.`},{fromYear:823,toYear:1949,flagUrl:t(`Flag_of_the_Princely_State_of_Tehri_Garhwal.svg`),label:`Garhwal Kingdom`,note:`An ancient Himalayan kingdom in Uttarakhand, home to the sources of the Ganges, that acceded to India at independence.`},{fromYear:1642,toYear:1975,flagUrl:t(`Flag_of_Sikkim_(1967-1975).svg`),label:`Kingdom of Sikkim`,note:`A Himalayan Buddhist kingdom ruled by the Namgyal dynasty for over 300 years, which became the 22nd state of India in 1975.`}],BR:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/br.svg`,label:`Flag of Brazil (27 stars)`,note:`Updated in 1992 to 27 stars after several territories became states, each star representing a state or the Federal District. It is one of the few national flags that maps an actual astronomical sky.`},{fromYear:1968,toYear:1992,flagUrl:t(`Flag_of_Brazil_(1968–1992).svg`),label:`Republic flag (1968)`,note:`The constellation was rearranged and a star added for the new state of Acre. The layout still encoded the night sky over Rio de Janeiro on the morning the republic was proclaimed.`},{fromYear:1889,toYear:1960,flagUrl:t(`Flag_of_Brazil_(1889–1960).svg`),label:`Republic flag (21 stars)`,note:`The classic green-and-yellow design with a blue celestial globe, the motto "Ordem e Progresso," and 21 stars. The sky depicts the constellations as seen over Rio on the morning of 15 November 1889.`},{fromYear:1889,toYear:1889,flagUrl:t(`Flag_of_Brazil_(November_1889).svg`),label:`Provisional Republic flag`,note:`A short-lived flag inspired by the United States, with green-and-yellow stripes and a blue canton, flown for only days after the monarchy fell before the starry design replaced it.`},{fromYear:1822,toYear:1889,flagUrl:t(`Flag_of_Brazil_(1870–1889).svg`),label:`Empire of Brazil`,note:`A green field with a yellow rhombus framing the imperial arms. Green stood for the House of Braganza and yellow for the Habsburgs — the houses of Emperor Pedro I and Empress Maria Leopoldina.`,parallelCaption:`Separatist republic of the era`,parallel:[{fromYear:1836,toYear:1845,flagUrl:t(`Flag_of_Piratini_Republic.svg`),label:`Riograndense Republic (Piratini)`,note:`The "Ragamuffin War" saw Brazil's southernmost province secede as the Riograndense Republic from 1836 to 1845 — the longest civil war in Brazilian history. Giuseppe Garibaldi fought on the rebel side before his later Italian campaigns.`}]}],MX:[{fromYear:1968,toYear:null,flagUrl:`/Global/flags/mx.svg`,label:`Flag of Mexico`,note:`Standardized in 1968 ahead of the Mexico City Olympics, it fixed the eagle, serpent, and cactus emblem in its current detailed form. The arms recall the Aztec founding legend of Tenochtitlan.`},{fromYear:1934,toYear:1968,flagUrl:t(`Flag_of_Mexico_(1934-1968).svg`),label:`1934 eagle redesign`,note:`The eagle and wreath were restyled with a more uniform, darker emblem under President Abelardo Rodríguez, tightening the proportions and colors toward the present look.`},{fromYear:1916,toYear:1934,flagUrl:t(`Flag_of_Mexico_(1916–1934).svg`),label:`Carranza redesign`,note:`President Venustiano Carranza decreed a naturalistic eagle shown in left profile — the basis for the modern emblem and a deliberate break from the earlier heraldic style.`},{fromYear:1893,toYear:1916,flagUrl:t(`Flag_of_Mexico_(1893-1916).svg`),label:`Porfiriato flag`,note:`Used during the Porfirio Díaz era, it showed the eagle facing forward with wings spread heraldically. It flew through the early years of the Mexican Revolution.`},{fromYear:1823,toYear:1864,flagUrl:t(`Flag_of_Mexico_(1823-1864,_1867-1893).svg`),label:`Early Republic`,note:`The republican redesign placed an uncrowned eagle on a cactus gripping a snake, ringed by oak and laurel. The same design returned from 1867 to 1893.`,parallelCaption:`Secessionist & breakaway states of the era`,parallel:[{fromYear:1840,toYear:1840,flagUrl:t(`Flag_of_the_Republic_of_the_Rio_Grande.svg`),label:`Republic of the Rio Grande`,note:`A short-lived 1840 republic of northern Mexican states resisting centralist rule from Mexico City; its flag bore three stars for its claimed territories. It was reabsorbed by Mexico within the year.`},{fromYear:1841,toYear:1848,flagUrl:t(`Flag_of_the_Republic_of_Yucatan.svg`),label:`Republic of Yucatán`,note:`Yucatán declared independence from Mexico twice (1841 and 1846) over disputes about federalism, flying five green stars beside red-white-red stripes. The peninsula rejoined Mexico in 1848 amid the Caste War.`},{fromYear:1854,toYear:1854,flagUrl:t(`Flag_of_the_Republic_of_Sonora.svg`),label:`Republic of Sonora (Walker)`,note:`American filibuster William Walker proclaimed a "Republic of Sonora" in 1854 during a failed private invasion of northwestern Mexico. The venture collapsed within months and Walker was tried in the US for violating neutrality laws.`}]},{fromYear:1821,toYear:1823,flagUrl:t(`Flag_of_Mexico_(1821-1823).svg`),label:`First Mexican Empire`,note:`The first flag after independence, with a crowned eagle reflecting the short-lived empire of Agustín de Iturbide. The crown was removed once Mexico became a republic.`}],TR:[{fromYear:1923,toYear:null,flagUrl:`/Global/flags/tr.svg`,label:`Flag of Turkey`,note:`When Atatürk proclaimed the Republic in 1923, Turkey kept the Ottoman red star-and-crescent almost unchanged, signaling continuity rather than rupture. Its exact proportions were only codified by the 1936 Turkish Flag Law.`,parallelCaption:`Transient republic that joined Turkey`,parallel:[{fromYear:1938,toYear:1939,flagUrl:t(`Flag_of_Hatay.svg`),label:`State of Hatay`,note:`Carved from French-mandate Syria, the Republic of Hatay existed for one year (1938–39) before voting to join Turkey. Its flag is near-identical to Turkey's but with a hollow (outlined) star. The annexation is still disputed by Syria.`}]},{fromYear:1844,toYear:1922,flagUrl:t(`Flag_of_the_Ottoman_Empire.svg`),label:`Ottoman flag (1844)`,note:`The Tanzimat reforms of 1844 fixed the modern five-pointed star on the red field, creating essentially today's design. This is the direct template the Republic inherited nearly 80 years later.`},{fromYear:1517,toYear:1793,flagUrl:t(`Flag_of_Ottoman_Empire_(1517-1793).svg`),label:`Early Ottoman red flag`,note:`For centuries the Ottomans flew plain red banners and crescent flags with no fixed design; the star-and-crescent was not yet standardized before the 1793 naval decree.`},{fromYear:1927,toYear:1930,flagUrl:t(`Kurdish_flag_(Khoiboun).svg`),label:`Republic of Ararat`,note:`A self-declared Kurdish republic in the mountains of eastern Turkey, crushed by the Turkish army.`},{fromYear:1918,toYear:1919,flagUrl:t(`Flag_of_the_South_West_Caucasian_Republic.svg`),label:`Kars Republic`,note:`A short-lived Muslim provisional government around Kars after the Russian collapse, suppressed by the British and Armenians.`},{fromYear:1915,toYear:1915,flagUrl:t(`Flag_of_Administration_of_Western_Armenia.svg`),label:`Republic of Van`,note:`A short-lived Armenian self-defence administration during WWI, amid the genocide, in eastern Anatolia.`},{fromYear:1204,toYear:1461,flagUrl:t(`Banner_of_the_Empire_of_Trebizond.svg`),label:`Empire of Trebizond`,note:`A Byzantine Greek successor empire on the Black Sea coast, the last fragment of the Roman world to fall to the Ottomans.`}],EG:[{fromYear:1984,toYear:null,flagUrl:`/Global/flags/eg.svg`,label:`Flag of Egypt`,note:`In 1984 the golden hawk was replaced by the gold Eagle of Saladin, Egypt's national emblem, centered in the red-white-black tricolour. The colors signify the struggle against occupation, a bright future, and the end of oppression.`},{fromYear:1972,toYear:1984,flagUrl:t(`Flag_of_Egypt_(1972–1984).svg`),label:`Federation of Arab Republics`,note:`For the federation of Egypt, Libya, and Syria, the two stars were replaced by a golden Hawk of Quraish on the white band. Egypt kept this hawk flag even after the federation lapsed.`},{fromYear:1958,toYear:1972,flagUrl:t(`Flag_of_the_United_Arab_Republic_(1958–1971),_Flag_of_Syria_(1980–2024).svg`),label:`United Arab Republic`,note:`The 1958 union of Egypt and Syria replaced the central eagle with two green stars, one for each member state. Syria left in 1961, but Egypt kept the name and this two-star flag for another decade.`},{fromYear:1953,toYear:1958,flagUrl:t(`Flag_of_Egypt_(1952–1958).svg`),label:`Liberation flag (1952 Revolution)`,note:`After the 1952 Free Officers' coup, the red-white-black "Arab Liberation" tricolour with the Eagle of Saladin became the national flag once the monarchy was abolished in 1953.`},{fromYear:1922,toYear:1953,flagUrl:t(`Flag_of_Egypt_(1922-1958).svg`),label:`Kingdom of Egypt`,note:`When Britain recognized Egyptian independence in 1922, King Fuad I adopted a green field with a white crescent enclosing three white stars — usually said to represent Egypt, Nubia, and Sudan.`},{fromYear:1844,toYear:1922,flagUrl:t(`Flag_of_Muhammad_Ali.svg`),label:`Khedivate of Egypt`,note:`Founded by Muhammad Ali Pasha — the Albanian commander regarded as the father of modern Egypt — the ruling dynasty governed a nominally Ottoman but effectively independent Egypt, flying a red flag with white crescents and stars. As the Khedivate it built the Suez Canal, then sank into debt and fell under British occupation in 1882, ruling on as a British puppet until the 1922 kingdom.`}],SE:[{fromYear:1906,toYear:null,flagUrl:`/Global/flags/se.svg`,label:`Swedish Flag (colours standardised)`,note:`In 1906 a royal decree fixed the exact shades of blue and yellow, ending a century of variation. The Nordic cross design itself stretches back to at least the early 16th century — one of the oldest unchanged national symbols in Europe.`},{fromYear:1844,toYear:1905,flagUrl:t(`Flag_of_Sweden_(pre-1906).svg`),label:`Swedish Flag with Union Mark`,note:`During the personal union with Norway (1814–1905), a combined canton showing both national crosses appeared in the upper hoist corner. Sweden and Norway shared a king but remained separate kingdoms; the union mark was a constant reminder of that political arrangement.`,parallel:[{fromYear:1844,toYear:1899,flagUrl:t(`Norge-Unionsflagg-1844.svg`),label:`Norwegian counterpart`,note:`Norway's flag carried the same union mark in the same position — the two mirrors of a political arrangement that ended peacefully in 1905 when Norway voted for independence.`}],parallelCaption:`Norwegian counterpart during the union`},{fromYear:1521,toYear:1844,flagUrl:t(`Flag_of_Sweden.svg`),label:`Classic Swedish Flag`,note:`The golden Nordic cross on blue is virtually unchanged from the earliest recorded use under Gustav Vasa in the 1520s. Sweden is one of the very few countries whose flag design has remained stable for five centuries.`}],NO:[{fromYear:1821,toYear:null,flagUrl:`/Global/flags/no.svg`,label:`Norwegian Flag (Meltzer design)`,note:`Designed by merchant and politician Fredrik Meltzer, this flag cleverly incorporated the three colours of the French Tricolore (associated with liberty) into a Nordic cross — blue within white within red. The design was adopted by the Norwegian Storting in 1821, though Norway was in union with Sweden and the flag was slow to gain official recognition abroad.`},{fromYear:1814,toYear:1821,flagUrl:t(`Flag_of_Norway_(1814-1821).svg`),label:`First Norwegian Flag (Eidsvoll)`,note:`When Norway's constitution was signed at Eidsvoll in May 1814, the country briefly gained independence before entering a union with Sweden. This first flag — a red field with a simple white cross — was used during that brief window and inspired the later, more distinctive design.`},{fromYear:1524,toYear:1814,flagUrl:`/Global/flags/dk.svg`,label:`Denmark–Norway`,note:`For nearly three centuries Norway was the junior partner in the kingdom of Denmark–Norway, ruled from Copenhagen and flying the Danish Dannebrog. When Denmark backed Napoleon and lost, Norway was handed to Sweden in 1814 — but not before Norwegians seized the moment to write their own constitution, the seed of the independence finally won in 1905.`}],DK:[{fromYear:1370,toYear:null,flagUrl:`/Global/flags/dk.svg`,label:`The Dannebrog`,note:`The Dannebrog — a white Nordic cross on red — is the oldest national flag still in continuous use by an independent nation, reliably documented from at least 1370. Legend holds it fell from the sky during the Battle of Lyndanisse in 1219. Whatever its origin, the design has remained essentially unchanged for over 650 years, making it the template for every other Nordic cross flag.`}],FI:[{fromYear:1918,toYear:null,flagUrl:`/Global/flags/fi.svg`,label:`Finnish Flag (blue cross)`,note:`Adopted on May 29, 1918, shortly after Finland declared independence from Russia in December 1917. The blue Nordic cross on white was chosen through a design competition — the blue representing Finland's thousands of lakes and the clear sky, the white its snow. The exact proportions were refined several times, with the current form standardised in 1978.`},{fromYear:1809,toYear:1917,flagUrl:t(`Merchant_Flag_of_Grand_Duchy_of_Finland.png`),label:`Grand Duchy of Finland (Russian era)`,note:`After Sweden ceded Finland to Russia in 1809, Finland became an autonomous Grand Duchy of the Russian Empire. The duchy used a red flag bearing the Finnish lion coat of arms. During this period Finnish national identity grew steadily — the Kalevala epic was compiled, the Finnish language was promoted, and the eventual push for independence gathered strength.`},{fromYear:1249,toYear:1809,flagUrl:`/Global/flags/se.svg`,label:`Part of Sweden`,note:`For roughly 600 years — from the medieval Northern Crusades until 1809 — Finland was an integral eastern part of the Kingdom of Sweden, not a colony but Swedish soil, flying the blue-and-yellow Swedish flag. That long union left Finland its Lutheran faith, its legal traditions, and the Swedish-speaking minority that endures today, before Russia took it as war booty in 1809.`}],KR:[{fromYear:1984,toYear:null,flagUrl:`/Global/flags/kr.svg`,label:`Taegukgi (standardised)`,note:`Korea's Taegukgi — white field, red-and-blue yin-yang (taegeuk) at centre, four black trigrams at corners — was formally standardised in 1984, fixing proportions and exact trigram arrangement. The design has been a Korean national symbol since its first use in 1882 and remained unchanged in concept through the Japanese occupation and the establishment of the Republic of Korea in 1948.`},{fromYear:1949,toYear:1984,flagUrl:t(`Flag_of_South_Korea_(1949–1984).svg`),label:`Taegukgi (1949 specification)`,note:`When the Republic of Korea was proclaimed in 1948, the trigrams were initially placed in a slightly different orientation. The 1949 official specification corrected this, but minor inconsistencies in which trigrams appeared in which corners persisted in practice until the 1984 standardisation finally resolved the ambiguity.`},{fromYear:1910,toYear:1945,flagUrl:`/Global/flags/jp.svg`,label:`Japanese occupation`,note:`From 1910 to 1945 Korea was a colony of Imperial Japan, which flew its own flag and banned the Taegukgi, forcing Korean assimilation — Japanese names, Japanese language in schools, the suppression of Korean culture. The Taegukgi survived as the banner of the independence movement and the Korean Provisional Government in exile, raised again at liberation in 1945.`},{fromYear:1897,toYear:1910,flagUrl:t(`Flag_of_Korea_(1899).svg`),label:`Korean Empire (Taegeukgi)`,note:`When King Gojong declared the Korean Empire in 1897 to assert sovereignty against both China and Japan, the Taegeukgi continued as the national symbol. In 1910 Japan annexed Korea and suppressed the flag entirely. For 35 years under Japanese colonial rule, displaying this flag was an act of resistance — and it became a powerful symbol of the independence movement.`},{fromYear:1882,toYear:1897,flagUrl:t(`Flag_of_Korea_(1882-1910).svg`),label:`First Taegukgi (Joseon dynasty)`,note:`Korea's first national flag was created in 1882 by diplomat Pak Yeong-hyo during a diplomatic mission to Japan, based on instructions from King Gojong. The taegeuk (yin-yang) symbol and trigrams draw on Confucian cosmology. This first version had eight trigrams; later versions reduced them to four.`},{fromYear:1392,toYear:1882,flagUrl:t(`Flag_of_the_king_of_Joseon.svg`),label:`Royal standard of Joseon`,note:`Korea had no "national flag" in the modern sense before 1882 — but the kings of the Joseon dynasty (1392–1897), Korea's last and longest royal house, flew a royal standard bearing the taegeuk and trigrams. That same Confucian cosmology was carried directly into the 1882 Taegukgi, making the royal banner the conceptual ancestor of every Korean flag.`},{fromYear:1961,toYear:1963,flagUrl:t(`Flag_of_South_Korea_(1949–1984).svg`),label:`Supreme Council for National Reconstruction`,note:`The military junta that ruled South Korea after Park Chung-hee's 1961 coup, before his civilian-styled presidency.`}],VN:[{fromYear:1976,toYear:null,flagUrl:`/Global/flags/vn.svg`,label:`Socialist Republic of Vietnam`,note:`When North and South Vietnam were formally reunified in July 1976, the gold five-pointed star on red — previously the flag of North Vietnam since 1945 — became the flag of the unified country. The red represents the revolution and the blood of those who died fighting for independence; the gold star represents the five main classes of Vietnamese society.`,parallel:[{fromYear:1955,toYear:1975,flagUrl:t(`Flag_of_South_Vietnam.svg`),label:`Republic of Vietnam (South)`,note:`South Vietnam's flag featured three horizontal red stripes on a yellow field. Yellow symbolised the imperial tradition; the three stripes represented the three regions of Vietnam (North, Centre, South). The flag flew until April 30, 1975, when Saigon fell and South Vietnam ceased to exist.`}],parallelCaption:`South Vietnam (existed at the same time)`},{fromYear:1945,toYear:1976,flagUrl:t(`Flag_of_North_Vietnam_(1945–1955).svg`),label:`Democratic Republic of Vietnam`,note:`Ho Chi Minh proclaimed the Democratic Republic of Vietnam on September 2, 1945, adopting this red flag with a gold star. The same flag flew through the war with France (ending 1954), the division of Vietnam at the 17th parallel, and the long war with the United States and South Vietnam — making it one of the most recognised flags of 20th-century armed struggle.`},{fromYear:1802,toYear:1945,flagUrl:t(`Long_tinh_flag_(variant).svg`),label:`Nguyen Dynasty / French Indochina`,note:`The Nguyen emperors, who unified Vietnam in 1802, used a plain yellow flag. Under French colonial rule from the 1880s, a dragon motif was sometimes used on yellow for the protectorate of Annam. Yellow remained Vietnam's imperial colour for over a century — which is why South Vietnam's post-independence flag also used yellow as its field.`},{fromYear:1946,toYear:1949,flagUrl:t(`Flag_of_France.svg`),label:`Republic of Cochinchina`,note:`A French-engineered puppet state in southern Vietnam, meant to split the south from Ho Chi Minh's republic.`},{fromYear:1948,toYear:1954,flagUrl:t(`Flag_of_the_Tai_Dam_People.svg`),label:`Sip Song Chau Tai`,note:`A federation of Tai chiefdoms in the northwest highlands of Vietnam, set up as an autonomous zone under French protection.`}],IR:[{fromYear:1980,toYear:null,flagUrl:`/Global/flags/ir.svg`,label:`Islamic Republic of Iran`,note:`Adopted after the 1979 Islamic Revolution, this flag keeps the green-white-red tricolor (unchanged since the Qajar era) but replaces the imperial lion and sun with the emblem of the Islamic Republic — a stylised Allah in the shape of a tulip, symbolising martyrdom. Along the borders of the green and red bands, the phrase "Allahu Akbar" (God is Greatest) is repeated 22 times, commemorating the 22nd of Bahman (February 11, 1979), the day of the revolution's victory.`},{fromYear:1925,toYear:1979,flagUrl:t(`State_flag_of_Iran_(1933–1964).svg`),label:`Imperial Standard (Pahlavi era)`,note:`The Pahlavi dynasty retained the ancient lion-and-sun emblem on the green-white-red tricolor: a lion holding a sword with a radiant sun rising behind it. This symbol of Persian royalty dated back to at least the 12th century. The 1979 revolution deliberately erased it — books and buildings bearing the lion and sun were defaced, making surviving examples historically significant.`,parallelCaption:`Soviet-backed breakaway of 1946`,parallel:[{fromYear:1946,toYear:1946,flagUrl:t(`Flag_of_the_Republic_of_Mahabad.svg`),label:`Republic of Mahabad`,note:`A short-lived Kurdish state in northwestern Iran, set up with Soviet backing in January 1946 and collapsing that December once Soviet forces withdrew. It remains a foundational symbol of modern Kurdish nationalism.`}]},{fromYear:1907,toYear:1925,flagUrl:t(`State_flag_of_Persia_(1907–1933).svg`),label:`Constitutional Era`,note:`The Constitutional Revolution of 1906 forced the Qajar shahs to accept a parliament and a constitution — and updated the flag with the emblem centered on the white stripe for the first time. The lion-and-sun device in this form dated from at least the Safavid empire of the 16th century and symbolised the power of the Persian monarchy and state.`},{fromYear:1501,toYear:1907,flagUrl:t(`Flag_of_Persia_(1665).svg`),label:`Safavid / Qajar Persia`,note:`The ancient Persian lion-and-sun motif predates any standardised tricolor. Under the Safavids and Qajars, the lion and sun appeared on battle standards, seals, and eventually on a green field. The familiar green-white-red arrangement was formalised only in the 19th century under the Qajars, but the lion and sun had represented Persian sovereignty for centuries before that.`}],AR:[{fromYear:1818,toYear:null,flagUrl:`/Global/flags/ar.svg`,label:`Flag of Argentina (with Sun of May)`,note:`The Sun of May — representing Inti, the Inca sun god, and commemorating the May Revolution of 1810 — was officially added to the flag on February 25, 1818. The sun is depicted with alternating straight and wavy rays and a human face, copied from the reverse of Argentina's first coin minted in 1813. It distinguishes the "official ceremonial flag" from the plain-striped civil flag.`},{fromYear:1816,toYear:1818,flagUrl:t(`Flag_of_Argentina_(alternative).svg`),label:`Flag without the Sun`,note:`The plain horizontal tricolor of light blue-white-light blue was created by General Manuel Belgrano on February 27, 1812, using the cockade colours of the revolution. It flew at the Declaration of Independence on July 9, 1816 — before the Sun of May was incorporated. This simpler version remains in use today as the "civil flag" (without the sun) on non-official occasions.`},{fromYear:1812,toYear:1816,flagUrl:t(`Flag_of_Belgrano_(1812).svg`),label:`Belgrano's Original Flag (1812)`,note:`Manuel Belgrano improvised the first Argentine flag in 1812 to rally troops at the Battle of Rosario, using the blue and white colours of the Buenos Aires revolutionary cockade. He raised it on February 27, 1812 — a date now celebrated as Flag Day in Argentina. Belgrano had to seek permission from the revolutionary government to use it officially, permission that came only gradually.`},{fromYear:1776,toYear:1812,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Viceroyalty of the Río de la Plata`,note:`Before Belgrano's blue-and-white, the lands of Argentina were the Spanish Viceroyalty of the Río de la Plata, governed from Buenos Aires and flying the red Cross of Burgundy of the Spanish Empire. The May Revolution of 1810 began the break from Spain, replacing the saltire with the revolutionary cockade colours that became the national flag.`}],CO:[{fromYear:1861,toYear:null,flagUrl:`/Global/flags/co.svg`,label:`Republic of Colombia`,note:`Colombia's horizontal tricolor — yellow (half), blue (quarter), red (quarter) — descends directly from the flag of Gran Colombia designed by Francisco de Miranda in 1806. The wide yellow band represents sovereignty and wealth; blue the two oceans flanking Colombia; red the blood of independence fighters. The current proportions (2:1:1) have been official since 1861.`},{fromYear:1830,toYear:1861,flagUrl:t(`Flag_of_New_Granada.svg`),label:`Republic of New Granada`,note:`After Gran Colombia dissolved in 1831, the central portion (modern Colombia, Panama, and parts of Ecuador) became the Republic of New Granada. It initially retained a version of the Gran Colombia tricolor, though with varying stripe proportions across different governments and constitutions.`},{fromYear:1819,toYear:1830,flagUrl:t(`Flag_of_Gran_Colombia.svg`),label:`Gran Colombia`,note:`Simón Bolívar's Gran Colombia — uniting modern Venezuela, Colombia, Ecuador, and Panama — adopted a yellow-blue-red tricolor inspired by Francisco de Miranda's design. Miranda had chosen yellow for the gold of the Americas, blue for the ocean separating it from Spain, and red for the blood that would be shed in the fight for freedom. This shared ancestor explains why Colombia, Venezuela, and Ecuador all have nearly identical flag colours today.`}],VE:[{fromYear:2006,toYear:null,flagUrl:`/Global/flags/ve.svg`,label:`Bolivarian Republic of Venezuela`,note:`In 2006 President Hugo Chávez updated the flag by adding an eighth star (previously seven) to honour the province of Guayana, aligning the stars in an arc rather than a line, and moving the coat of arms to the hoist side. The horse in the coat of arms — which had previously been running to the right — was controversially reversed to gallop to the left, which critics read as a political statement.`},{fromYear:1954,toYear:2006,flagUrl:t(`Flag_of_Venezuela_(1954-2006).svg`),label:`Venezuela (seven stars, 1954–2006)`,note:`This version carried seven stars in a straight horizontal line representing the seven provinces that signed the Declaration of Independence in 1811. The coat of arms appeared only on the state flag (not the civil flag). This flag flew from the Marcos Pérez Jiménez dictatorship through the democratic era up until Chávez's redesign.`},{fromYear:1863,toYear:1954,flagUrl:t(`Flag_of_Venezuela_(1863-1905).svg`),label:`Venezuela (various star counts)`,note:`Throughout the 19th and early 20th centuries Venezuela's flag went through numerous versions with different numbers of stars (3, 5, 6, 7) and varying arrangements, reflecting the country's turbulent political history of civil wars, caudillo rule, and federal reorganisation. The yellow-blue-red tricolor inherited from Gran Colombia remained constant; everything else was negotiable.`},{fromYear:1819,toYear:1830,flagUrl:t(`Flag_of_Gran_Colombia.svg`),label:`Gran Colombia`,note:`Venezuela was a founding component of Simón Bolívar's Gran Colombia alongside Colombia and Ecuador. The shared tricolor of yellow, blue, and red designed by Francisco de Miranda in 1806 became the common ancestor of all three nations' flags — a visible reminder of the dream of a unified South American republic that collapsed in 1830.`},{fromYear:1811,toYear:1812,flagUrl:t(`Flag_of_the_First_Republic_of_Venezuela.svg`),label:`First Republic of Venezuela`,note:`The first independent Venezuelan state (1811–12) flew an early version of Miranda's yellow-blue-red tricolor with a canton of stars. It collapsed after an earthquake and royalist counterattack, but began the lineage that runs to today's flag.`}],BE:[{fromYear:1831,toYear:null,flagUrl:`/Global/flags/be.svg`,label:`Kingdom of Belgium`,note:`Belgium's vertical black-yellow-red tricolor was adopted at independence in 1831. The colours derive from the ducal arms of Brabant — a golden lion on black — combined with red from the arms of Hainaut. It's unusually tall and narrow compared to most flags (13:15 ratio), and the black stripe is on the hoist side — the only national flag with black in that position.`},{fromYear:1815,toYear:1830,flagUrl:t(`Flag_of_the_Netherlands.svg`),label:`Under the Kingdom of the Netherlands`,note:`After Napoleon's defeat, the Congress of Vienna merged the Austrian Netherlands (roughly modern Belgium) and the Dutch Republic into the United Kingdom of the Netherlands under King William I. The Dutch orange-white-blue flag (displayed as red-white-blue) flew over Belgian territory. The forced union proved deeply unpopular — language, religion, and economic policies all divided north from south, leading to the Belgian Revolution of 1830.`},{fromYear:1789,toYear:1790,flagUrl:t(`Banner_of_the_Duchy_of_Brabant.svg`),label:`Brabantine Revolution`,note:`The 1789 Brabantine Revolution against Austrian rule briefly created the United Belgian States. The revolutionary flag took the black, yellow, and red from the coat of arms of the Duchy of Brabant and arranged them horizontally (black on top, as in the Brabant arms). After Belgium's eventual independence in 1830, the revolutionary tradition was honoured but the stripes were turned vertical — creating today's distinctive flag.`}],CH:[{fromYear:1889,toYear:null,flagUrl:`/Global/flags/ch.svg`,label:`Swiss Federal Flag (standardised)`,note:`Switzerland officially standardised its federal flag in 1889 — a bold white cross on red, in a square format unique among sovereign nations (only Vatican City also uses a square flag). The equal-armed cross has represented the Swiss Confederation since at least the Battle of Laupen in 1339, when Swiss troops wore white crosses as field insignia. The Red Cross flag is its inverse — white field, red cross — created in 1863 by Swiss founder Henry Dunant as a deliberate tribute.`},{fromYear:1815,toYear:1889,flagUrl:t(`Flag_of_Switzerland_(Pantone).svg`),label:`Restored Confederation`,note:`After the fall of Napoleon, the 1815 Federal Treaty restored the Swiss Confederation and revived the white cross on red as its emblem. The proportions and exact shade of red still varied between cantons for decades before the square national flag was formally standardised in 1889.`},{fromYear:1798,toYear:1803,flagUrl:t(`Flag_of_the_Helvetic_Republic_(French).svg`),label:`Helvetic Republic`,note:`When France invaded in 1798 and swept away the old confederation, the short-lived Helvetic Republic adopted a completely different flag — a horizontal green-red-yellow tricolor, the first ever single national flag for all of Switzerland. It abandoned the centuries-old cross entirely. The republic collapsed by 1803, and the cross returned with the restored confederation.`},{fromYear:1339,toYear:1798,flagUrl:t(`Flag_of_Switzerland_(Pantone).svg`),label:`Medieval Origins`,note:`Swiss soldiers wore white crosses on red surcoats at the Battle of Laupen (1339) to identify themselves as a confederation. The cross appeared on cantonal battle flags long before Switzerland had a formal national banner, flying over the loose alliance of cantons until the French invasion of 1798.`}],IQ:[{fromYear:2008,toYear:null,flagUrl:`/Global/flags/iq.svg`,label:`Republic of Iraq (current)`,note:`The 2008 revision updated the Kufic script "Allahu Akbar" to a standardised typeface (removing Saddam Hussein's handwriting) and removed the three green stars that had symbolised Ba'athist pan-Arab unity. The basic red-white-black horizontal tricolor with green text remains, connecting the flag to the broader pan-Arab colour tradition shared with Egypt, Syria, and Yemen.`},{fromYear:2004,toYear:2008,flagUrl:t(`Flag_of_Iraq_(2004–2008).svg`),label:`Coalition-era interim flag`,note:`After the 2003 invasion toppled Saddam, the tricolor was kept but in 2004 his handwritten "Allahu Akbar" was replaced with the phrase in a neutral green Kufic script — an interim compromise while a permanent flag was debated (an earlier proposed blue-and-white design had been rejected for resembling Israel's flag). It flew until the 2008 standardisation produced the current flag.`},{fromYear:1991,toYear:2004,flagUrl:t(`Flag_of_Iraq_(1991-2004).svg`),label:`Saddam's "Allahu Akbar" Flag`,note:`On the eve of the Gulf War in January 1991, Saddam Hussein personally added the phrase "Allahu Akbar" (God is Greatest) to the flag — reportedly in his own handwriting — in green Kufic script between the three stars. The move was widely seen as a cynical appeal to Islamic sentiment to rally support for the invasion of Kuwait. This became the defining image of Saddam's Iraq and was immediately controversial.`},{fromYear:1963,toYear:1991,flagUrl:t(`Flag_of_Iraq_(1963-1991).svg`),label:`Ba'ath Era (three stars)`,note:`When the Ba'ath Party took power in 1963, the flag gained three green stars representing the hoped-for union of Iraq, Syria, and Egypt into a single Arab state — an ambition that was never realised. The pan-Arab red-white-black tricolor was adopted, shared with Syria and Egypt under Gamal Abdel Nasser's pan-Arab ideology. Iraq's flag was effectively a statement of political aspiration rather than current reality.`},{fromYear:1958,toYear:1963,flagUrl:t(`Flag_of_Iraq_(1959-1963).svg`),label:`First Republic (after revolution)`,note:`The Iraqi monarchy was overthrown in the bloody revolution of July 14, 1958. The new republic adopted a black-white-green horizontal tricolor with a yellow sun (the Kurdish sun symbol) and a red star, replacing the Hashemite-era flag. This flag lasted only until the Ba'ath Party's 1963 coup, which replaced it with the pan-Arab design.`},{fromYear:1921,toYear:1958,flagUrl:t(`Flag_of_Iraq_(1924–1959).svg`),label:`Kingdom of Iraq (Hashemite)`,note:`Britain installed the Hashemite prince Faisal as king of the new Kingdom of Iraq in 1921; from 1924 it flew an Arab Revolt–derived flag — black, white and green horizontal bands with a red trapezoid at the hoist bearing two white stars. Increasingly resented as a British client monarchy, it ruled until the violent revolution of 1958 swept the king and the flag away.`},{fromYear:1958,toYear:1958,flagUrl:t(`Flag_of_the_Arab_Federation.svg`),label:`Arab Federation`,note:`The brief union of Hashemite Iraq and Jordan, formed to counter Nasser's UAR and ended within months by the Iraqi revolution.`},{fromYear:1922,toYear:1924,flagUrl:t(`Flag_of_Kingdom_of_Kurdistan_(1922-1924).svg`),label:`Kingdom of Kurdistan`,note:`A short-lived Kurdish kingdom proclaimed by Sheikh Mahmud Barzanji in northern Iraq against British control.`}],SY:[{fromYear:2024,toYear:null,flagUrl:`/Global/flags/sy.svg`,label:`Syrian Arab Republic (current)`,note:`The green-white-black independence flag with three red stars returned as Syria's national flag after the fall of Bashar al-Assad in December 2024, and was confirmed by the constitutional declaration of March 2025. Opposition forces had flown it since the 2011 uprising as the flag of the pre-Ba'ath republic.`},{fromYear:1980,toYear:2024,flagUrl:t(`Flag_of_the_United_Arab_Republic_(1958–1971),_Flag_of_Syria_(1980–2024).svg`),label:`Ba'athist Syria (two stars)`,note:`In 1980, after the Federation of Arab Republics with Egypt and Libya ended, Syria readopted the red-white-black flag with two green stars first used by the United Arab Republic of 1958–1961, when the stars stood for Syria and Egypt. It flew under Hafez and Bashar al-Assad until the regime fell in December 2024.`},{fromYear:1963,toYear:1972,flagUrl:t(`Flag_of_Syria_(1963–1972).svg`),label:`Ba'ath Party Syria`,note:`After the Ba'ath coup of 1963, Syria adopted a pan-Arab tricolor with three red stars representing the hoped-for union of Syria, Egypt, and Iraq. Between 1972 and 1980, Syria joined a Federation of Arab Republics with Egypt and Libya, using a flag with the Hawk of Quraish. When that federation dissolved, Syria returned to the two-star design of the United Arab Republic.`},{fromYear:1958,toYear:1961,flagUrl:t(`Flag_of_the_United_Arab_Republic.svg`),label:`United Arab Republic (with Egypt)`,note:`In 1958, Syria and Egypt merged into the United Arab Republic under President Nasser — a bold experiment in pan-Arab unity. The UAR flag combined the red-white-black tricolor with two green stars for the two constituent nations and the Nasser-era eagle. Syria broke away in 1961 after a military coup, finding Egyptian dominance of the union intolerable, and the UAR essentially ceased to exist.`},{fromYear:1946,toYear:1958,flagUrl:t(`Flag_of_Syria_(1930–1958,_1961–1963).svg`),label:`Syrian Republic (independence era)`,note:`When France's League of Nations mandate ended and Syria gained full independence in 1946, it flew this green-white-black tricolor with three red stars, first used under the mandate in 1932; the stars originally stood for three regions of the country. This was Syria's flag at the time of independence and remained so until the union with Egypt, and it returned from 1961 to 1963 and again in 2024.`},{fromYear:1920,toYear:1920,flagUrl:t(`Flag_of_Kingdom_of_Syria_(1920-03-08_to_1920-07-24).svg`),label:`Arab Kingdom of Syria`,note:`For four months in 1920, Emir Faisal — a leader of the Arab Revolt — ruled an independent Arab Kingdom of Syria from Damascus, flying the Arab Revolt flag (black-white-green bands with a red triangle and a white star). It was the first modern Arab nation-state, but France, awarded the mandate at the San Remo conference, crushed it at the Battle of Maysalun in July 1920 and began over two decades of mandate rule.`}],LY:[{fromYear:2011,toYear:null,flagUrl:`/Global/flags/ly.svg`,label:`Restored Independence Flag`,note:`After Muammar Gaddafi's regime fell in the 2011 civil war, Libya restored the flag of the original Kingdom of Libya — a red-black-green horizontal tricolour with a white crescent and star at the centre. The black centre band comes from the banner of the Senussi order of Cyrenaica, and the three bands are often linked to the regions of Fezzan (red), Cyrenaica (black) and Tripolitania (green). Adopted originally in 1951, this flag had been suppressed for 42 years by Gaddafi's all-green design.`},{fromYear:1977,toYear:2011,flagUrl:t(`Flag_of_Libya_(1977-2011).svg`),label:`Gaddafi's All-Green Flag`,note:`In 1977 Muammar Gaddafi declared the "Great Socialist People's Libyan Arab Jamahiriya" and adopted the world's only completely monochrome national flag — a plain, unadorned field of green. Green symbolised Islam and Gaddafi's "Green Book" political philosophy. For 34 years Libya was instantly recognisable on any map or chart by its solid green rectangle. No other sovereign nation has ever had or is likely to have a flag so radically minimal.`},{fromYear:1969,toYear:1977,flagUrl:t(`Flag_of_Libya_(1969-1972).svg`),label:`Arab Republic of Libya (Gaddafi coup)`,note:`After the 27-year-old Colonel Gaddafi's bloodless coup deposed King Idris in September 1969, Libya adopted the pan-Arab red-white-black tricolor — the same colours used by Egypt, Syria, and Iraq. Between 1972 and 1977 Libya joined a short-lived Federation of Arab Republics with Egypt and Syria, using a flag with the Hawk of Quraish, before Gaddafi's dramatic switch to plain green.`},{fromYear:1951,toYear:1969,flagUrl:t(`Flag_of_Libya_(1951-1969).svg`),label:`Kingdom of Libya (independence)`,note:`When Libya achieved independence from Italian and Allied administration on December 24, 1951 — becoming the first African country to gain independence via the United Nations — it adopted this flag under King Idris. The crescent and star are traditional Islamic symbols; the three horizontal bands represent the three historical regions: Cyrenaica (black), Fezzan (green), and Tripolitania (red). This flag was suppressed under Gaddafi and triumphantly restored in 2011.`},{fromYear:1837,toYear:1969,flagUrl:t(`Flag_of_the_Senussi_Dynasty.svg`),label:`Senussi Order`,note:`The Sufi religious order that led resistance to Italian colonisation and whose leader became the first and only king of independent Libya.`}],SA:[{fromYear:1973,toYear:null,flagUrl:`/Global/flags/sa.svg`,label:`Kingdom of Saudi Arabia (current)`,note:`Saudi Arabia's flag — a green field bearing the Shahada ("There is no god but Allah, and Muhammad is his messenger") in white Thuluth script above a white sword — is one of the world's most religiously charged national flags. The sword's orientation was reversed in 1973 to always face forward (towards the hoist) regardless of which side of the flag you see. Green is the traditional colour of Islam; the sword symbolises the Kingdom's founding through military conquest.`},{fromYear:1926,toYear:1932,flagUrl:t(`Flag_of_the_Kingdom_of_Hejaz_and_Nejd.svg`),label:`Kingdom of Hejaz and Nejd`,note:`After Ibn Saud conquered the Hejaz — and the holy cities of Mecca and Medina — in 1925, he ruled a dual kingdom of Hejaz and Nejd from 1926 until merging them into the single Kingdom of Saudi Arabia in 1932. Its green flag bore the Shahada and a white sword.`},{fromYear:1938,toYear:1973,flagUrl:t(`Flag_of_Saudi_Arabia_(1938–1973).svg`),label:`Kingdom of Saudi Arabia (1938)`,note:`An earlier standardisation in 1938 established the green-Shahada-sword design but with the sword pointing in different directions on each side — a heraldic oddity that was corrected in 1973. Before 1938 the exact form of the Shahada inscription and sword varied between different royal households and governors. Saudi Arabia is one of only three countries whose flag includes text.`},{fromYear:1902,toYear:1938,flagUrl:t(`Flag_of_Nejd_(1926).svg`),label:`Sultanate/Kingdom of Nejd`,note:`Ibn Saud's early flags as he united the Arabian Peninsula were variants of a green field with the Shahada — the same core identity but without a standardised sword. When Ibn Saud captured Riyadh in 1902, beginning his 30-year campaign to unite Arabia, his banners were simpler religious standards. The sword emblem was formalised as the kingdom consolidated, symbolising both the founding wars and the Wahhabi religious authority underpinning the state.`},{fromYear:1916,toYear:1925,flagUrl:t(`Flag_of_Hejaz_(1920).svg`),label:`Kingdom of Hejaz (Hashemite)`,note:`Before the Saudis, the Hejaz — home to Mecca and Medina — was its own kingdom under Sharif Hussein bin Ali, who launched the Arab Revolt against the Ottomans in 1916 and flew its black-white-green flag with a red triangle (the ancestor of many Arab flags today). Ibn Saud conquered the Hejaz in 1925, ending Hashemite rule over the holy cities and folding it into what became Saudi Arabia.`},{fromYear:1906,toYear:1934,flagUrl:t(`Flag_of_the_Emirate_of_Asir.svg`),label:`Emirate of Asir`,note:`An idrisid emirate on the Red Sea coast, annexed by Saudi Arabia after a short war with Yemen.`},{fromYear:1727,toYear:1818,flagUrl:t(`Flag_of_the_First_and_Second_Saudi_State_(1744-1891).svg`),label:`Emirate of Diriyah`,note:`The First Saudi State, the original alliance of the House of Saud and the Wahhabi movement, destroyed by an Ottoman-Egyptian army.`},{fromYear:1906,toYear:1934,flagUrl:t(`Flag_of_Upper_Asir.svg`),label:`Sheikdom of Upper Asir`,note:`A highland sheikhdom of the Asir region, annexed by Saudi Arabia after the Saudi–Yemeni war.`}],YE:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/ye.svg`,label:`Republic of Yemen (unified)`,note:`When North and South Yemen reunified on May 22, 1990, the new republic adopted a simple red-white-black horizontal tricolor — the pan-Arab colours — shedding the communist star and triangle of the south and the complex arms of the north. The design was essentially a compromise between the two predecessor flags. Unification lasted only months before a civil war nearly split the country again; another civil war beginning in 2014 has since devastated the country.`,parallel:[{fromYear:1967,toYear:1990,flagUrl:t(`Flag_of_South_Yemen.svg`),label:`People's Democratic Republic of Yemen (South)`,note:`South Yemen — the only Marxist state in the Arab world — used a red-white-black tricolor with a sky-blue triangle at the hoist bearing a red star. It was one of the world's most radical communist regimes, nationalising land and businesses and fighting a brutal internal power struggle that killed thousands. The blue and red star disappeared entirely at unification.`}],parallelCaption:`South Yemen (existed simultaneously)`},{fromYear:1962,toYear:1990,flagUrl:t(`Flag_of_North_Yemen.svg`),label:`Yemen Arab Republic (North)`,note:`North Yemen's flag after the 1962 revolution that overthrew the Mutawakkilite Kingdom used red-white-black with a green star at the centre — the pan-Arab palette shared with Egypt, Syria, and Iraq. North Yemen was caught between the Cold War superpowers: a civil war (1962–1970) saw Egyptian-backed republicans fight Saudi-backed royalists, with the republic eventually prevailing. The green star was dropped from the unified flag in 1990.`},{fromYear:1927,toYear:1962,flagUrl:t(`Flag_of_the_Mutawakkilite_Kingdom_of_Yemen.svg`),label:`Mutawakkilite Kingdom of Yemen`,note:`After the Ottomans withdrew in 1918, the imams of the Zaydi Shia dynasty ruled North Yemen as the Mutawakkilite Kingdom — a deeply isolated theocratic monarchy that kept the country sealed off from the modern world much as medieval Yemen had been. Its flag was a plain red banner (sometimes bearing a white sword and stars), the traditional Islamic and Arab colour. The 1962 republican revolution that toppled the imamate triggered a brutal eight-year civil war.`},{fromYear:1849,toYear:1918,flagUrl:t(`Flag_of_the_Ottoman_Empire.svg`),label:`Ottoman Yemen`,note:`The Ottomans controlled the Yemeni highlands and the Red Sea coast through their Yemen Vilayet, flying the Ottoman star-and-crescent, though they never fully subdued the fiercely independent Zaydi tribes of the interior. Yemen's strategic position guarding the southern entrance to the Red Sea made it valuable to every empire — which is also why Britain seized the southern port of Aden in 1839, beginning the north–south division that would shape Yemen for the next 150 years.`},{fromYear:1740,toYear:1967,flagUrl:t(`Flag_of_the_Sultanate_of_Lahej.svg`),label:`Sultanate of Lahej`,note:`A principal South Arabian sultanate of the Aden Protectorate, Lahej flew a red-and-white flag with crossed daggers. Like the other southern states it was abolished in 1967 when the British-protected sultanates were absorbed into South Yemen.`},{fromYear:1395,toYear:1967,flagUrl:t(`Kathiri_flag.svg`),label:`Kathiri State of Seiyun`,note:`A Hadhrami sultanate in the eastern Aden Protectorate, the Kathiri State of Seiyun flew a green-yellow-red flag with three stars. It too was dissolved into South Yemen in 1967, ending centuries of dynastic rule in the Hadhramaut valley.`},{fromYear:1700,toYear:1967,flagUrl:t(`Flag_of_Dhala.svg`),label:`Emirate of Dhala`,note:`One of the many sultanates and emirates of the Aden Protectorate, absorbed into South Yemen at independence.`},{fromYear:1700,toYear:1967,flagUrl:t(`Flag_of_the_Sultanate_of_Fadhli.svg`),label:`Fadhli Sultanate`,note:`A sultanate of the Aden Protectorate in southern Arabia, dissolved into independent South Yemen.`},{fromYear:1700,toYear:1967,flagUrl:t(`Flag_of_Wahidi_Balhaf.svg`),label:`Wahidi Sultanate of Balhaf`,note:`One of the small Wahidi sultanates of the Aden Protectorate coast.`},{fromYear:1700,toYear:1967,flagUrl:t(`Flag_of_Beihan.svg`),label:`Emirate of Beihan`,note:`An emirate of the Aden Protectorate on the edge of the Empty Quarter.`},{fromYear:1500,toYear:1967,flagUrl:t(`Flag_of_the_Mahra_Sultanate.svg`),label:`Mahra State of Qishn and Socotra`,note:`A sultanate of the far east of South Arabia that included the remote island of Socotra.`},{fromYear:1700,toYear:1967,flagUrl:t(`Flag_of_Wahidi_Haban.svg`),label:`Wahidi Sultanate of Haban`,note:`One of the small Wahidi sultanates of the Aden Protectorate, dissolved into independent South Yemen.`}],JO:[{fromYear:1928,toYear:null,flagUrl:`/Global/flags/jo.svg`,label:`Hashemite Kingdom of Jordan`,note:`Jordan's flag — horizontal black-white-green stripes (pan-Arab colours) with a red triangle at the hoist bearing a white seven-pointed star — descends directly from the Arab Revolt flag of 1916. The seven points of the star represent the seven verses of the opening sura of the Quran, the seven hills of Amman, and the seven virtues of faith, justice, humility, national spirit, virtue, social welfare, and aspirations. Jordan's flag design has been essentially unchanged since 1928, though the territory has changed dramatically.`},{fromYear:1920,toYear:1928,flagUrl:t(`Flag_of_the_Emirate_of_Transjordan.svg`),label:`Emirate of Transjordan`,note:`After World War I and the collapse of the Ottoman Empire, Britain created the Emirate of Transjordan under Emir Abdullah I of the Hashemite family. The early flag was a direct variant of the Arab Revolt banner — the same black-white-green horizontal stripes with a red triangle. The white star was added in 1928 to distinguish Jordan's flag from that of Palestine, which at the time shared virtually identical colouring under the British Mandate.`},{fromYear:1916,toYear:1920,flagUrl:t(`Flag_of_the_Arab_Revolt.svg`),label:`Arab Revolt (Sharif Hussein)`,note:`The Arab Revolt of 1916 — when Sharif Hussein of Mecca rose against the Ottoman Empire with British support — produced one of the most influential flags in Middle Eastern history. Hussein's banner used black-white-green horizontal stripes (representing the Abbasid, Umayyad, and Fatimid caliphates respectively) with a red triangle for the Hashemite family. The Palestinian, Jordanian, Sudanese, Kuwaiti, and several other Arab flags all descend from this single revolutionary design.`},{fromYear:1516,toYear:1916,flagUrl:t(`Flag_of_the_Ottoman_Empire.svg`),label:`Ottoman era`,note:`The territory east of the Jordan River was an Ottoman possession for four centuries, administered from Damascus and flying the Ottoman star-and-crescent. It was a sparsely populated frontier of desert and Bedouin tribes along the route of the Hejaz Railway. When the Arab Revolt swept north in 1916–18, the Hashemites took control, and the land became Transjordan — the territory east of the Jordan that Britain assigned to Emir Abdullah after the war.`}],LB:[{fromYear:1943,toYear:null,flagUrl:`/Global/flags/lb.svg`,label:`Lebanese Republic`,note:`Lebanon's flag — red-white-red horizontal stripes with a green cedar tree at centre — was adopted in November 1943 when Lebanon declared independence from the French Mandate. The cedar of Lebanon, referenced more than 70 times in the Bible, has symbolised the country for millennia. The flag was designed by Henri Pharaon: the white represents the snow of Mount Lebanon; the red the blood shed for liberation; the cedar represents immortality and steadiness. The exact shade of green of the cedar has varied slightly between official versions.`},{fromYear:1920,toYear:1943,flagUrl:t(`Flag_of_Lebanon_during_French_Mandate_(1920-1943).svg`),label:`French Mandate of Lebanon`,note:`After the Ottoman Empire's collapse, France received the League of Nations mandate over greater Syria and carved out "Grand Liban" in 1920, incorporating the Maronite Christian heartland with surrounding Muslim territories. The mandate flag was the French Tricolore defaced with the cedar tree — a direct imposition of French colonial authority over a Lebanese identity. Lebanese nationalists chafed under the arrangement and declared independence in 1943, though French forces only withdrew in 1946.`},{fromYear:1861,toYear:1918,flagUrl:t(`Flag_of_the_Ottoman_Empire.svg`),label:`Mount Lebanon (Ottoman era)`,note:`For four centuries Lebanon was part of the Ottoman Empire, flying the Ottoman red star-and-crescent. After a wave of sectarian massacres in 1860, European powers pressured the Ottomans into creating the autonomous Mount Lebanon Mutasarrifate in 1861 — a self-governing Christian-majority province that gave the Lebanese their first taste of distinct political identity. This autonomy planted the seeds of the modern Lebanese state, though the territory still flew the Ottoman flag until the empire's collapse in 1918.`},{fromYear:1979,toYear:1984,flagUrl:t(`Flag_of_Lebanon_(1943-1990).svg`),label:`Free Lebanon State`,note:`A Christian-militia enclave in south Lebanon declared during the civil war, backed by Israel.`}],IL:[{fromYear:1948,toYear:null,flagUrl:`/Global/flags/il.svg`,label:`State of Israel`,note:`Israel's flag — a white field with two horizontal blue stripes and a blue Star of David at the centre — was adopted on October 28, 1948, five months after independence. The design, proposed by David Wolffsohn at the First Zionist Congress in 1897, was inspired by the Jewish prayer shawl (tallit), which is traditionally white with blue or black stripes. The Star of David (Magen David) had been used as a Jewish symbol for centuries but became a Zionist emblem specifically in the late 19th century. Israel is the only country whose flag is directly based on a religious garment.`},{fromYear:1920,toYear:1948,flagUrl:t(`Ensign_of_the_Palestine_Mandate_(1927–1948).svg`),label:`British Mandate of Palestine`,note:`From 1920 to 1948, the territory was governed under a British League of Nations Mandate. The Mandate flag was a British Blue Ensign defaced with a white circle bearing a green "Palestine" inscription. This flag flew over a deeply contested territory where Jewish immigration under Zionist movement auspices clashed violently with the existing Arab population and with British administration, culminating in Britain's withdrawal and Israel's declaration of independence in 1948.`},{fromYear:1517,toYear:1917,flagUrl:t(`Flag_of_the_Ottoman_Empire.svg`),label:`Ottoman Palestine`,note:`For 400 years, from 1517 until General Allenby's capture of Jerusalem in 1917, the land was governed by the Ottoman Empire and flew the Ottoman red star-and-crescent. Administered as part of the provinces (vilayets) of Beirut and the special district of Jerusalem, it was a quiet agricultural backwater for most of that period. The late-19th-century rise of Zionism and the simultaneous awakening of Arab nationalism set the stage for the conflicts that followed Ottoman rule.`}],PS:[{fromYear:1964,toYear:null,flagUrl:`/Global/flags/ps.svg`,label:`State of Palestine`,note:`The Palestinian flag — horizontal black-white-green stripes with a red triangle at the hoist — is almost identical to Jordan's flag, sharing the same Arab Revolt ancestry. The PLO adopted it in 1964; it was formally declared the flag of the State of Palestine in 1988. The design deliberately references the pan-Arab colours and the shared heritage of the Arab Revolt. As of 2012, Palestine is a UN non-member observer state; the flag flies at the UN headquarters in New York.`},{fromYear:1916,toYear:1948,flagUrl:t(`Flag_of_the_Arab_Revolt.svg`),label:`Arab Revolt heritage`,note:`Palestine's flag shares its direct ancestor with Jordan's: the Arab Revolt flag of 1916. After World War I, Palestinian Arabs flew variations of the Revolt's black-white-green-red banner in their own national movement. The similarity between the Palestinian and Jordanian flags reflects the political reality of 1920s British Mandate geography — Jordan's Emir Abdullah added a white star specifically to distinguish his flag from the Palestinian one, the two were so close.`},{fromYear:1517,toYear:1916,flagUrl:t(`Flag_of_the_Ottoman_Empire.svg`),label:`Ottoman era`,note:`Like all the Levant, the land of Palestine was an Ottoman possession for four centuries, flying the Ottoman star-and-crescent. The Arab Revolt of 1916 — launched against Ottoman rule from the Hejaz — was the moment Arab nationalism produced its own banner, the black-white-green-red flag that became the ancestor of the Palestinian, Jordanian, and several other Arab national flags. Before that, there was no distinct Palestinian flag; the territory was simply Ottoman.`}],AE:[{fromYear:1971,toYear:null,flagUrl:`/Global/flags/ae.svg`,label:`United Arab Emirates (federation)`,note:`When seven Trucial States — Abu Dhabi, Dubai, Sharjah, Ajman, Fujairah, Ras al-Khaimah, and Umm al-Quwain — federated as the UAE on December 2, 1971, they adopted the pan-Arab green-white-black horizontal stripes with a red vertical stripe at the hoist. The flag was designed by Abdulla Mohamed Al Maainah, then 19 years old, who won the national design competition. Red is the traditional colour of the Kharijite and Gulf ruling families; the other three colours are pan-Arab.`},{fromYear:1820,toYear:1971,flagUrl:t(`Flag_of_the_Trucial_States.svg`),label:`Trucial States (under British protection)`,note:`The seven emirates were known as the Trucial States under British protection from 1820, when a General Treaty with Britain ended widespread piracy in the Gulf. Each emirate flew its own red-and-white flag — red was the traditional colour of Gulf rulers, white added by treaty with Britain to identify peaceful vessels. The flags were nearly identical between emirates, distinguishable mainly by different proportions of red and white. Britain withdrew from "East of Suez" in 1971, prompting federation.`}],BH:[{fromYear:2002,toYear:null,flagUrl:`/Global/flags/bh.svg`,label:`Kingdom of Bahrain (five points)`,note:`When Bahrain upgraded from Emirate to Kingdom in 2002, the serrated white-red border — traditionally with many points — was reduced to exactly five triangular points representing the Five Pillars of Islam. The design retains Bahrain's traditional red-and-white colour scheme: white for peace; red for the blood of battles against foreign invaders. Bahrain was one of the first Gulf states to discover oil (1932) and one of the first to see reserves begin to deplete.`},{fromYear:1820,toYear:2002,flagUrl:t(`Flag_of_Bahrain_(1820–1932).svg`),label:`Emirate of Bahrain (multiple points)`,note:`For most of its modern history, Bahrain's flag was simply red, the traditional Kharijite colour of Gulf rulers. The white serrated border was added by treaty with Britain in 1820 to distinguish Bahraini ships as peaceful. The number of serrations varied over the decades — at different times the border had 28, 16, or other numbers of points — before standardisation in 1972 fixed it at 28 and the 2002 reform reduced it to five.`}],KW:[{fromYear:1961,toYear:null,flagUrl:`/Global/flags/kw.svg`,label:`State of Kuwait (independence)`,note:`Kuwait adopted its current flag on independence from Britain on June 19, 1961 — the same day independence was declared. The horizontal green-white-red stripes with a black trapezoid at the hoist are pan-Arab colours. The flag was designed to look clearly different from the simple red flags of other Gulf states. Green symbolises the fertile lands; white for peace; red for blood on enemy swords; black for the defeat of enemies — a martial reading that suits Kuwait's turbulent history, including the 1990 Iraqi invasion.`},{fromYear:1899,toYear:1961,flagUrl:t(`Flag_of_Kuwait_(1915-1961).svg`),label:`Kuwait under British protection`,note:`The Kuwaiti ruling family, the Al-Sabah, had invited British protection in 1899 to avoid Ottoman annexation. The pre-independence Kuwaiti flags were simple red designs — sometimes with a white serrated border similar to Bahrain's — typical of Gulf ruling families. The dramatic shift to green-white-red-black in 1961 was a deliberate assertion of Kuwaiti Arab national identity distinct from both British colonial association and the plain red Gulf tradition.`}],QA:[{fromYear:1971,toYear:null,flagUrl:`/Global/flags/qa.svg`,label:`State of Qatar (independence)`,note:`Qatar's distinctive maroon-and-white flag — with a serrated border like Bahrain's — was adopted on independence from Britain on September 3, 1971. The original flag was red-and-white like Bahrain's, but the red faded to maroon in the intense Gulf sun, and Qatar eventually standardised the darker maroon as the official colour. Qatar's flag has nine serrated points, the most of any Gulf state flag, though the exact significance of that number is debated. Qatar is the only country whose flag has a width-to-length ratio greater than 1:2.`},{fromYear:1860,toYear:1971,flagUrl:t(`Flag_of_Qatar_(1949–1971).svg`),label:`Qatar under Al-Thani rule / British protection`,note:`Qatar came under British protection in 1916 after the Al-Thani family's rule was formalised. The pre-independence flag was a red-and-white design typical of Gulf rulers — white added by British treaty to mark peaceful vessels, red the traditional Kharijite colour. The serrated dividing line between white and red was a distinctive Qatari feature even in early flags, and the colour faded progressively from red to the maroon Qatar now uses officially.`}],OM:[{fromYear:1970,toYear:null,flagUrl:`/Global/flags/om.svg`,label:`Sultanate of Oman (current)`,note:`Oman's horizontal red-white-green flag with the national emblem (crossed khanjar daggers over a belt, and two crossed swords) was adopted when Sultan Qaboos overthrew his father in 1970 and opened Oman to the modern world. Red is the traditional colour of Omani rulers; white represents peace; green represents the Jebel Akhdar ("Green Mountain") region. The khanjar dagger on the emblem is also depicted on Omani currency and is a potent symbol of Omani cultural identity.`},{fromYear:1856,toYear:1970,flagUrl:t(`Flag_of_Muscat.svg`),label:`Sultanate of Muscat and Oman`,note:`When the Omani Empire split in 1856, the homeland became the Sultanate of Muscat and Oman, flying the plain red banner of the Al Bu Said dynasty — red being the traditional colour of Omani and Gulf rulers. Sultan Said bin Taimur (1932–1970) kept the country in extreme isolation, banning sunglasses, radios and even bicycles, until his son Qaboos's 1970 coup transformed both the country and its flag and renamed it simply Oman.`},{fromYear:1696,toYear:1856,flagUrl:t(`Flag_of_Muscat.svg`),label:`Omani Empire`,note:`At its height the Omani Empire was a major Indian Ocean power, ruling Zanzibar and a stretch of the East African (Swahili) coast and competing with Portugal and Britain for the spice and ivory trade — all under a plain red flag. In 1856 it divided between two of the ruler's sons into the Sultanate of Zanzibar in Africa and the Sultanate of Muscat and Oman in Arabia.`},{fromYear:1913,toYear:1959,flagUrl:t(`Flag_of_the_Imamate_of_Oman_(1954–1959).svg`),label:`Imamate of Oman (interior)`,note:`For centuries Oman's mountainous interior was governed separately by an elected Imam under the Ibadi tradition, distinct from the coastal sultanate at Muscat. The 20th-century Imamate flew a red flag bearing the Islamic profession of faith in white calligraphy. After oil was found, the Sultanate — backed by Britain — crushed the Imamate in the 1950s Jebel Akhdar War, ending Oman's long internal division by 1959.`}],CL:[{fromYear:1818,toYear:null,flagUrl:`/Global/flags/cl.svg`,label:`Chilean Flag (La Estrella Solitaria)`,note:`Chile's flag — the "Lone Star" — was finalised on October 18, 1817, shortly before independence was formally declared. The white star represents a guide to progress and honour; red and blue are said to represent the blood of patriots and the sky and ocean. Superficially similar to the Texas flag (adopted 1839), the Chilean flag actually came first. The proportions were refined in 1854 but the design has been unchanged for over 200 years.`},{fromYear:1812,toYear:1817,flagUrl:t(`Flag_of_Chile_(1812-1814).svg`),label:`La Patria Vieja (Old Fatherland)`,note:`During the first period of Chilean self-government (1810–1814, before the Spanish reconquest), Chile's early revolutionary flags used horizontal blue-white-yellow stripes — very different from today's design. After the Reconquista restored Spanish rule, patriots went into exile in Argentina, trained with San Martín's Army of the Andes, and returned in 1817 to liberate Chile and adopt an entirely new flag.`},{fromYear:1542,toYear:1810,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Captaincy General of Chile (Spanish)`,note:`For nearly three centuries Chile was a Spanish colony — the Captaincy General of Chile, a frontier territory fighting a long war with the unconquered Mapuche in the south — flying the Cross of Burgundy of the Spanish Empire, until the independence movement began in 1810.`}],PE:[{fromYear:1950,toYear:null,flagUrl:`/Global/flags/pe.svg`,label:`Republic of Peru (current)`,note:`Peru's red-white-red vertical tricolor has been the national colour scheme since independence, but the coat of arms in the state flag was simplified and standardised in 1950. The arms feature a vicuña (national animal), a cinchona tree (source of quinine), and a cornucopia — three symbols of Peru's natural wealth. The civil flag (without arms) is among the oldest unchanged designs in the Americas.`},{fromYear:1825,toYear:1950,flagUrl:t(`Flag_of_Peru_(1825-1950).svg`),label:`Republic of Peru (19th century)`,note:`After independence from Spain in 1821, Peru went through several flag designs. Simón Bolívar imposed a different coat of arms on the existing red-white-red. The 1825 constitution stabilised the tricolor format, though the exact coat of arms changed multiple times over the following century. The vertical red-white-red stripes were chosen to distinguish Peru from Spain's red-yellow-red, avoiding any visual association with the former colonial power.`},{fromYear:1820,toYear:1825,flagUrl:t(`Flag_of_Peru_(1821–1822).svg`),label:`San Martín's Original Design`,note:`When General José de San Martín landed in Peru in 1820 to liberate it from Spain, he designed the first Peruvian flag with diagonal red and white stripes radiating from the centre. The story goes that San Martín was inspired by watching flamingos fly at dawn over Paracas Bay — the red of their wings against white sky suggesting Peru's colours. The diagonal design was quickly changed to vertical stripes but the red-and-white palette remained.`},{fromYear:1542,toYear:1820,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Viceroyalty of Peru (Spanish)`,note:`Peru was the jewel of Spanish South America — the Viceroyalty of Peru, ruled from Lima, the "City of Kings," which governed most of the continent and funnelled the silver of Potosí to Spain. For nearly three centuries it flew the Cross of Burgundy. It was also the last royalist stronghold, not finally liberated until the Battle of Ayacucho in 1824.`}],EC:[{fromYear:1900,toYear:null,flagUrl:`/Global/flags/ec.svg`,label:`Republic of Ecuador (with coat of arms)`,note:`Ecuador's flag is visually almost identical to Colombia's and Venezuela's — all three descend from Gran Colombia's yellow-blue-red tricolor. Ecuador distinguishes its state flag with a large coat of arms featuring Mount Chimborazo, a steamboat, and a condor. The proportions of the stripes (yellow taking half the flag) are also inherited directly from Francisco de Miranda's original Gran Colombia design.`},{fromYear:1845,toYear:1900,flagUrl:t(`Flag_of_Ecuador_(1845-1860).svg`),label:`Republic of Ecuador (early)`,note:`After Gran Colombia dissolved in 1830, Ecuador struggled to differentiate its flag from those of Colombia and Venezuela. Various designs were tried with different coat of arms configurations. The tricolor stripes were maintained throughout but arrangements and arms changed with each new constitution and government.`},{fromYear:1819,toYear:1830,flagUrl:t(`Flag_of_Gran_Colombia.svg`),label:`Gran Colombia`,note:`Ecuador (then known as the District of the South) was part of Simón Bolívar's Gran Colombia from 1819 to 1830. The yellow-blue-red tricolor designed by Francisco de Miranda was shared across what is now Venezuela, Colombia, and Ecuador — and it still unites all three visually today, more than 190 years after Gran Colombia dissolved.`}],BO:[{fromYear:1851,toYear:null,flagUrl:`/Global/flags/bo.svg`,label:`Republic of Bolivia (red-yellow-green)`,note:`Bolivia's horizontal red-yellow-green tricolor was established by law in 1851, though the colours had been in use since independence in 1825. Red represents the blood of independence heroes; yellow the country's mineral wealth (Bolivia has some of the world's largest lithium and tin deposits); green the fertile land. The Wiphala — a rainbow-chequered flag of the indigenous Aymara people — was added as a co-official state flag in the 2009 constitution.`},{fromYear:1825,toYear:1851,flagUrl:t(`Flag_of_Bolivia_(1825).svg`),label:`Early Republic of Bolivia`,note:`Bolivia declared independence on August 6, 1825, named after its liberator Simón Bolívar. The earliest flags used different colour arrangements — some sources show green-red-yellow and other combinations — as the new republic experimented before settling on the current order. Bolivia's independence came partly through the campaigns of both Bolívar (from the north) and San Martín (from the south), making it a meeting point of two great liberation movements.`},{fromYear:1559,toYear:1825,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Upper Peru (Spanish)`,note:`For nearly 300 years Bolivia was "Upper Peru" — the Audiencia de Charcas within the Spanish Empire, flying the Cross of Burgundy. Its silver mountain at Potosí was the richest mine on earth, bankrolling the Spanish crown and the global silver trade. That wealth, built on brutal forced indigenous labour, makes the green stripe's "mineral wealth" a double-edged symbol in independent Bolivia.`}],UY:[{fromYear:1830,toYear:null,flagUrl:`/Global/flags/uy.svg`,label:`Oriental Republic of Uruguay`,note:`Uruguay's flag takes its nine horizontal stripes (five white, four blue) from the United States flag — at the time of independence, the US model was enormously influential across the Americas. In the canton sits the Sun of May, identical in meaning to Argentina's: both nations recognise the same revolutionary sunrise of May 25, 1810. Uruguay was once part of the United Provinces of the Río de la Plata alongside Argentina, and the shared sun reflects that common origin.`},{fromYear:1828,toYear:1830,flagUrl:t(`Flag_of_Uruguay_(1828-1830).svg`),label:`Early Uruguayan Flag`,note:`Uruguay's independence was formally recognised in 1828 after years of fighting involving Argentina, Brazil, and Great Britain (which brokered the peace). Early versions of the flag had different numbers of stripes — an 1828 design had 17, later reduced to 9. The Sun of May was added from the start, reflecting Uruguay's political and cultural ties to the Argentine independence tradition.`}],PY:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/py.svg`,label:`Republic of Paraguay (current)`,note:`Paraguay's flag is unique in the world: its obverse and reverse show different emblems. The front bears the national coat of arms (a star surrounded by olive and palm branches under the motto "Peace and Justice"); the back shows the Treasury Seal (a lion guarding a staff of liberty). This double-sided design has been official since 1842 and was last updated in 2013. The red-white-blue tricolor is said to have been inspired by the French Tricolore, which was associated with liberty across the Atlantic world.`},{fromYear:1842,toYear:1990,flagUrl:t(`Flag_of_Paraguay_(1842-1954).svg`),label:`Republic of Paraguay (classic design)`,note:`When Paraguay declared independence from Spain in 1811 under José Gaspar Rodríguez de Francia, the flag's design evolved through several versions before the distinctive double-sided design was codified in 1842. Francia ruled as "El Supremo" in near-total isolation from the outside world — he closed Paraguay's borders and severed contact with Argentina and Brazil — giving Paraguayan national symbols an unusually homegrown character.`}],CU:[{fromYear:1902,toYear:null,flagUrl:`/Global/flags/cu.svg`,label:`Republic of Cuba`,note:`Cuba's flag — designed by exile Narciso López in 1849 — pre-dates Cuban independence by 50 years. López wanted to annex Cuba to the United States; later Cuban independence leaders adopted the same flag but stripped it of that meaning. The three blue stripes represent the three colonial provinces; the two white stripes represent peace; the red triangle stands for liberty, equality, and fraternity; the white star is the Lone Star of an independent Cuba. This design has flown without any change since 1902.`},{fromYear:1898,toYear:1902,flagUrl:`/Global/flags/us.svg`,label:`US military government`,note:`After the Spanish-American War of 1898 ended four centuries of Spanish rule, Cuba spent four years under a US military government flying the American flag, until the Republic was inaugurated in 1902. Independence came with strings attached — the Platt Amendment gave Washington the right to intervene and the lease on Guantánamo Bay — shaping a fraught US–Cuba relationship that endures.`},{fromYear:1869,toYear:1898,flagUrl:t(`Céspedes_flag.svg`),label:`Ten Years' War rebel flag`,note:`During the Ten Years' War (1868–1878) — Cuba's first major independence uprising — rebels in the Oriente region used a flag of red, white, and blue horizontal stripes. The Bayamo flag, raised when rebels captured the town of Bayamo in 1868, is considered Cuba's first revolutionary banner. These regional rebel flags were eventually unified around López's 1849 design during the final push for independence.`},{fromYear:1516,toYear:1898,flagUrl:t(`Flag_of_New_Spain.svg`),label:`Spanish Colonial Cuba`,note:`Cuba was Spain's richest and most strategically important colonial possession — the "Pearl of the Antilles" — and one of the last two Spanish colonies in the Americas (along with Puerto Rico), not achieving independence until 1898 after the Spanish-American War. For nearly four centuries the Spanish flag flew over Havana's fortresses, changed only by the particular ensigns of successive Spanish dynasties.`}],HT:[{fromYear:1986,toYear:null,flagUrl:`/Global/flags/ht.svg`,label:`Republic of Haiti (restored)`,note:`Haiti's distinctive blue-and-red bicolor was restored in 1986 after the fall of the Duvalier dictatorship. The flag is derived from the legendary act of 1803 in which Jean-Jacques Dessalines tore the white strip from a captured French Tricolore, stitching the remaining blue and red together as a symbol of the union between Black and mixed-race Haitians against the colonial power. The coat of arms — a palm tree, cannons, and the motto "L'Union Fait La Force" — sits in the white centre band of the state flag.`},{fromYear:1964,toYear:1986,flagUrl:t(`Flag_of_Haiti_(1964-1986).svg`),label:`Duvalier Flag (black and red)`,note:`In 1964, "Papa Doc" Duvalier changed the flag's horizontal blue-and-red to vertical black-and-red, claiming to revive the pre-independence flag used by some revolutionary leaders who favoured black over blue. The black stripe represented the Black population; red represented the mixed-race (mulatto) population. After Duvalier's son "Baby Doc" was overthrown in 1986, the blue-and-red was immediately restored.`},{fromYear:1849,toYear:1859,flagUrl:t(`Flag_of_Haiti_(1849–1859).svg`),label:`Second Empire of Haiti`,note:`In 1849 President Faustin Soulouque crowned himself Emperor Faustin I, ruling a decade-long Second Empire of Haiti. He kept the blue-and-red bicolor but replaced the republican arms with an elaborate imperial coat of arms beneath a crown. The empire collapsed in 1859 and Haiti returned to a republic.`},{fromYear:1806,toYear:1820,flagUrl:t(`Flag_of_Haiti_(1806-1811).svg`),label:`Early Haitian Republic`,note:`Haiti declared independence on January 1, 1804 — the only successful slave rebellion in history to found a nation. In the chaotic early decades the country split between a black northern kingdom under Henri Christophe and a southern republic, each using different flags. The early horizontal blue-red bicolor was established by Pétion's republic and eventually became the national standard, though with continuing debates over whether the blue should be cobalt or midnight.`}],DO:[{fromYear:1844,toYear:null,flagUrl:`/Global/flags/do.svg`,label:`Dominican Republic`,note:`The Dominican flag — a white cross dividing blue and red quarters, with the coat of arms at centre — was designed by Juan Pablo Duarte for independence from Haiti in 1844. The white cross was deliberately chosen to set the Dominican flag apart from Haiti's blue-and-red (which had no cross), marking the cultural, religious, and political distinction the founders wanted to emphasise. The coat of arms features a Bible and cross, six Dominican flags, and the motto "God, Fatherland, Liberty."`},{fromYear:1822,toYear:1844,flagUrl:`/Global/flags/ht.svg`,label:`Haitian Occupation`,note:`From 1822 to 1844 the eastern two-thirds of Hispaniola (the future Dominican Republic) was occupied and incorporated into Haiti by President Jean-Pierre Boyer. For 22 years the Haitian blue-and-red flew over what is now the Dominican Republic, a period known in Dominican history as the Haitian Unification — an occupation that profoundly shaped Dominican national identity and the desire for separation.`},{fromYear:1821,toYear:1822,flagUrl:t(`Flag_of_the_Republic_of_the_Spanish_Haiti.svg`),label:`Republic of Spanish Haiti`,note:`For nine weeks in late 1821, the eastern half of Hispaniola declared independence from Spain as the "Republic of Spanish Haiti," flying a Gran Colombia-style tricolor with a white hoist bar. Haiti invaded and annexed it in February 1822, beginning the 22-year occupation.`}],GT:[{fromYear:1871,toYear:null,flagUrl:`/Global/flags/gt.svg`,label:`Republic of Guatemala (blue-white-blue)`,note:`Guatemala's vertical blue-white-blue tricolor with the quetzal and coat of arms was established by the 1871 Liberal Revolution. The blue stripes represent the Pacific and Atlantic oceans that flank Central America; the white represents peace. The resplendent quetzal — one of the world's most striking birds — is the national symbol; a quetzal has never successfully been kept in captivity, making it an emblem of liberty. The currency is also called the quetzal.`},{fromYear:1823,toYear:1839,flagUrl:t(`Flag_of_the_Federal_Republic_of_Central_America.svg`),label:`Federal Republic of Central America`,note:`After independence from Spain in 1821, Guatemala was briefly part of the Mexican Empire before joining the Federal Republic of Central America (1823–1839) alongside El Salvador, Honduras, Nicaragua, and Costa Rica. The federation's flag — blue-white-blue horizontal stripes with a central emblem — is the ancestor of every Central American national flag today. The federation collapsed in civil war, but the colours survived in each successor state's flag.`,parallelCaption:`6th state of the federation (1838-40)`,parallel:[{fromYear:1838,toYear:1840,flagUrl:t(`Flag_of_the_State_of_Los_Altos.svg`),label:`State of Los Altos`,note:`Los Altos was briefly the "sixth state" of the Federal Republic of Central America, formed in 1838 from the highlands around Quetzaltenango. Its flag carried the federation's blue-white-blue with a quetzal — the free-flying bird that became Guatemala's national symbol. Guatemalan forces under Rafael Carrera reconquered it by 1840.`}]}],HN:[{fromYear:1866,toYear:null,flagUrl:`/Global/flags/hn.svg`,label:`Republic of Honduras`,note:`Honduras's flag directly inherits the Central American Federal Republic's blue-white-blue horizontal tricolor. The five blue stars added in 1866 represent the five original nations of the Federal Republic — a quiet expression of the old dream of Central American unity. Honduras has held these colours continuously since the federation's collapse, with only the star design changing.`},{fromYear:1823,toYear:1839,flagUrl:t(`Flag_of_the_Federal_Republic_of_Central_America.svg`),label:`Federal Republic of Central America`,note:`Honduras was one of five founding members of the Federal Republic of Central America (1823–1839). The federation's horizontal blue-white-blue tricolor became the visual template for every Central American country's flag. When the federation fragmented, each state kept some variant of the design — making Central American flags a uniquely coherent family among the world's national flags.`}],SV:[{fromYear:1912,toYear:null,flagUrl:`/Global/flags/sv.svg`,label:`Republic of El Salvador (current)`,note:`El Salvador's blue-white-blue horizontal tricolor and its coat of arms (five volcanoes between two oceans, a rainbow, and the motto "God, Union, Liberty") were standardised in 1912. Like all Central American nations, the design descends from the Federal Republic flag. The blue represents the Pacific and Atlantic; the white represents peace. El Salvador is the smallest and most densely populated country in Central America.`},{fromYear:1875,toYear:1912,flagUrl:t(`Flag_of_El_Salvador_(1875–1912).svg`),label:`Stars-and-stripes era`,note:`For nearly four decades El Salvador flew a flag modelled directly on the United States — alternating blue and white horizontal stripes with a red canton bearing white stars. It was a striking departure from the Central American blue-white-blue, and was abandoned in 1912 when the country returned to the federation-style tricolor it still uses today.`},{fromYear:1823,toYear:1839,flagUrl:t(`Flag_of_the_Federal_Republic_of_Central_America.svg`),label:`Federal Republic of Central America`,note:`El Salvador was part of the five-nation Federal Republic of Central America after independence from Spain. The federation's flag became the shared ancestor of all five Central American states' flags. El Salvador in particular saw intense conflict between Liberals and Conservatives throughout the 19th century, with the flag's exact form changing repeatedly before the 1912 standardisation.`}],NI:[{fromYear:1908,toYear:null,flagUrl:`/Global/flags/ni.svg`,label:`Republic of Nicaragua (current)`,note:`Nicaragua's blue-white-blue horizontal tricolor — again from the Central American Federation — was definitively standardised in 1908. The coat of arms uniquely shows a rainbow over five volcanoes between two bodies of water, with a Phrygian cap of liberty and the words "Republic of Nicaragua — Central America." Nicaragua is the largest country in Central America and its flag uniquely uses the word "Central America" in the arms, keeping alive the unification ideal.`},{fromYear:1823,toYear:1839,flagUrl:t(`Flag_of_the_Federal_Republic_of_Central_America.svg`),label:`Federal Republic of Central America`,note:`Nicaragua was one of the founding members of the Central American federation. After its dissolution, Nicaragua experienced decades of political turmoil, US military interventions, the Somoza dynasty, the Sandinista Revolution of 1979, and the Contra war — each chapter in the country's flag history shaped by these events, though the Central American tricolor endured through all of them.`}],CR:[{fromYear:1906,toYear:null,flagUrl:`/Global/flags/cr.svg`,label:`Republic of Costa Rica (current)`,note:`Costa Rica distinguished its Central American tricolor in 1848 by adding a wide red horizontal stripe at the centre — inspired, according to tradition, by First Lady Pacífica Fernández, who admired the French Tricolore's colours. The result — blue-white-red-white-blue — is immediately distinct from its neighbours. The coat of arms on the state flag was standardised in 1906 and shows three volcanoes, two oceans, and rising sun.`},{fromYear:1823,toYear:1848,flagUrl:t(`Flag_of_the_Federal_Republic_of_Central_America.svg`),label:`Federal Republic of Central America`,note:`Costa Rica was part of the Central American federation from 1823 to its dissolution in 1839. After the federation collapsed, Costa Rica spent years as part of various smaller unions before declaring itself a fully independent republic in 1848. That same year the flag was redesigned with the distinctive red stripe, marking a deliberate break from the plain blue-white-blue shared by the other former federation members.`}],PA:[{fromYear:1903,toYear:null,flagUrl:`/Global/flags/pa.svg`,label:`Republic of Panama (independence)`,note:`Panama's quartered flag — white with a blue star, white with a red star, blue, and red — was designed by Manuel Amador Guerrero's family and first flown on November 4, 1903, the day after independence from Colombia. The blue represents the Conservative Party; red represents the Liberal Party; white represents the peace between them. The design was chosen to symbolise national unity across political lines — an ambitious hope for a country whose independence was largely engineered by the United States to secure the Canal Zone.`},{fromYear:1821,toYear:1903,flagUrl:`/Global/flags/co.svg`,label:`Department of Colombia`,note:`Panama declared independence from Spain in 1821 and immediately joined Gran Colombia, later becoming a department of Colombia when Gran Colombia dissolved. Panama's attempts at independence in 1840, 1841, and later years were all unsuccessful. The 1903 independence was backed by the United States, which wanted to build a canal and found Colombia unwilling to cede the territory on American terms. Panama flew Colombia's yellow-blue-red tricolor for 82 years.`}],GY:[{fromYear:1966,toYear:null,flagUrl:`/Global/flags/gy.svg`,label:`Cooperative Republic of Guyana`,note:`Guyana's flag — nicknamed "The Golden Arrowhead" — was designed by American vexillologist Whitney Smith and adopted at independence from Britain in 1966. A gold arrowhead points from the hoist towards the fly, fringed in white; beneath it a red triangle fringed in black. Green represents the forests; gold the mineral wealth; white the rivers; black the endurance of the people; red the zeal for nation-building. It remains one of the most distinctive flag designs in the Americas.`},{fromYear:1814,toYear:1966,flagUrl:t(`Civil_Ensign_of_the_United_Kingdom.svg`),label:`British Guiana (colonial era)`,note:`The Guiana coast was colonised by the Dutch in the 17th century before Britain took control during the Napoleonic Wars. British Guiana (as it was known) was the site of one of the deadliest incidents in American religious history — the 1978 Jonestown mass death of over 900 members of the Peoples Temple cult. Independence came in 1966 under Forbes Burnham's People's Progressive Party, and Guyana has since aligned more with South America than the Caribbean.`},{fromYear:1667,toYear:1814,flagUrl:`/Global/flags/nl.svg`,label:`Dutch Guiana`,note:`Like neighbouring Suriname, the colonies of Essequibo, Demerara and Berbice that became Guyana were Dutch — plantation economies worked by enslaved Africans under the flag of the Netherlands. Britain seized them during the Napoleonic Wars and formally took them in 1814, merging them into British Guiana in 1831. The Dutch legacy survives in place names and the sea-wall engineering that holds back the Atlantic from the coast.`}],SR:[{fromYear:1975,toYear:null,flagUrl:`/Global/flags/sr.svg`,label:`Republic of Suriname (independence)`,note:`Suriname's flag — five horizontal stripes of green, white, red, white, and green, with a large yellow star at the centre — was adopted when the country gained independence from the Netherlands in 1975. Green represents the forests and agriculture; white represents justice and freedom; red represents progress and love; the yellow star represents the unity of all the ethnic groups in Suriname's famously diverse population (Hindustanis, Creoles, Maroons, Javanese, Amerindians, and others).`},{fromYear:1959,toYear:1975,flagUrl:t(`Flag_of_Suriname_(1959–1975).svg`),label:`Autonomous Suriname`,note:`When Suriname became an autonomous country within the Kingdom of the Netherlands in 1954, it adopted its own flag in 1959: a white field with five stars — black, brown, yellow, red and white — linked by an ellipse, each colour standing for one of the territory's major ethnic groups. It flew until the green-white-red star flag of full independence replaced it in 1975.`},{fromYear:1667,toYear:1959,flagUrl:t(`Flag_of_the_Netherlands.svg`),label:`Dutch Suriname (colonial era)`,note:`Suriname was a Dutch colony from 1667 (when England traded it to the Netherlands in exchange for New Amsterdam — the future New York). The Dutch plantation economy relied on enslaved Africans and later indentured labourers from Asia, creating Suriname's extraordinary ethnic diversity. Suriname was one of the last countries in the Americas to gain independence, doing so in 1975 — though a significant portion of the population emigrated to the Netherlands before and after.`}],BZ:[{fromYear:1981,toYear:null,flagUrl:`/Global/flags/bz.svg`,label:`Belize (independence)`,note:`Belize's flag is unusual: a white circle with the national coat of arms sits on a blue field with red stripes top and bottom. The red stripes were added to include both political parties — the PUP (blue) and the UDP (red) — in the national symbol. The coat of arms depicts two woodcutters (logging was the colonial economy's foundation) beneath a mahogany tree and the motto "Sub Umbra Floreo" (I flourish in the shade). Belize was the last mainland American country to gain independence, in 1981.`},{fromYear:1862,toYear:1981,flagUrl:t(`Flag_of_British_Honduras.svg`),label:`British Honduras (colonial era)`,note:`Britain established a settlement at the mouth of the Belize River in the 17th century, primarily for logwood extraction. The settlement became the Colony of British Honduras in 1862 and was renamed Belize only in 1973, eight years before independence. The colony's coat of arms — the two woodcutters — was carried into independence intact, making Belize's national emblem a direct inheritance from its British colonial history.`}],JM:[{fromYear:1962,toYear:null,flagUrl:`/Global/flags/jm.svg`,label:`Jamaica (independence)`,note:`Jamaica's flag is the only national flag in the world with neither red, white, nor blue. The gold diagonal cross (saltire) divides the flag into four triangles: green above and below, black left and right. Black represents the strength and creativity of the people; gold represents the natural wealth and the beauty of sunlight; green represents hope and the lush vegetation. The design won a national competition ahead of independence from Britain on August 6, 1962.`},{fromYear:1655,toYear:1962,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Jamaica (colonial era)`,note:`Britain captured Jamaica from Spain in 1655 and it became one of the most valuable plantation colonies in the Caribbean, dependent on enslaved African labour. Jamaica was a major centre of the transatlantic slave trade and the birthplace of maroon communities — formerly enslaved people who established autonomous settlements in the mountains. Independence in 1962 was achieved peacefully under Chief Minister Alexander Bustamante.`},{fromYear:1494,toYear:1655,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Spanish Jamaica`,note:`Columbus landed on Jamaica in 1494, and Spain held the island for over 150 years under the Cross of Burgundy, calling it Santiago. Spanish rule devastated the indigenous Taíno through disease and forced labour and introduced the first enslaved Africans. An English expedition seized the lightly-defended island in 1655 — the retreating Spanish freed their slaves, whose descendants became Jamaica's first Maroons.`}],TT:[{fromYear:1962,toYear:null,flagUrl:`/Global/flags/tt.svg`,label:`Trinidad and Tobago (independence)`,note:`Trinidad and Tobago's flag features a black stripe edged in white running diagonally from the upper hoist to the lower fly on a red field. The designer, Carlisle Chang, intended red for the fire element and the warmth of the people; black for the dedication and strength that unifies the country; white for the equality of all under the sun. The two islands gained independence together from Britain on August 31, 1962.`},{fromYear:1797,toYear:1962,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Trinidad & Tobago (colonial era)`,note:`Trinidad was a Spanish colony until captured by Britain in 1797; Tobago changed hands between European powers 22 times — more than any other territory in the world — before being ceded to Britain in 1814. The islands were merged into a single crown colony in 1889. Trinidad and Tobago became one of the wealthiest Caribbean nations through oil production, and its multicultural society (African, Indian, European, and Chinese heritage) shaped a unique culture including calypso, soca, and steelband music.`},{fromYear:1498,toYear:1797,flagUrl:t(`Flag_of_Cross_of_Burgundy.svg`),label:`Spanish Trinidad`,note:`Columbus reached Trinidad in 1498, and Spain held it for nearly three centuries under the Cross of Burgundy — though it remained a neglected backwater that Spain eventually opened to French Catholic planters, who gave the island much of its Francophone-Creole character before a British fleet took it in 1797.`}],BB:[{fromYear:1966,toYear:null,flagUrl:`/Global/flags/bb.svg`,label:`Barbados (independence)`,note:`Barbados's flag features three vertical bands of blue-gold-blue with a broken trident in the centre — the trident representing Barbados's maritime heritage (the country was known as "Little England" under colonial rule) and the "broken" lower shaft symbolising the break from colonial status. The flag was designed by Grantley Prescod and adopted at independence from Britain on November 30, 1966. In November 2021 Barbados became a republic, but kept the same flag — the trident remained.`},{fromYear:1627,toYear:1966,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Barbados (colonial era)`,note:`Barbados was an English colony from 1627, one of the earliest and most profitable British Caribbean possessions. At the height of the sugar era in the 18th century, Barbados was Britain's most valuable colonial asset per acre. The island's plantation economy was based entirely on enslaved African labour; by some estimates the island's enslaved population had a life expectancy of just seven years after arrival. Barbados achieved independence peacefully in 1966 and became a republic in 2021.`}],BS:[{fromYear:1973,toYear:null,flagUrl:`/Global/flags/bs.svg`,label:`Commonwealth of the Bahamas`,note:`The Bahamas' flag — aquamarine and gold stripes with a black triangle at the hoist — was designed by Hervis Bain and adopted at independence from Britain on July 10, 1973. The aquamarine represents the surrounding sea; gold the beaches and the sun; black the strength and unity of the Bahamian people. The archipelago of some 700 islands was the site of Christopher Columbus's first landing in the Americas in 1492, on the island of Guanahani (San Salvador).`},{fromYear:1718,toYear:1973,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Bahamas (colonial era)`,note:`The Bahamas was a base for pirates (including Blackbeard and Charles Vane) until the British Crown asserted control in 1718. During American Prohibition (1920–1933) the islands became a transshipment point for rum, giving the Bahamas unexpected economic prosperity. The islands were of strategic importance during World War II, with the Duke of Windsor serving as Governor. Independence came in 1973 after a peaceful transition.`}],AG:[{fromYear:1967,toYear:null,flagUrl:`/Global/flags/ag.svg`,label:`Antigua and Barbuda (independence)`,note:`Antigua's flag was designed by Reginald Samuel and chosen through a national competition ahead of independence from Britain in 1981 (the flag was first used in 1967 for associated statehood). The rising golden sun on a black field, flanked by red, blue, and white, represents the dawn of a new era. Black represents African heritage; blue the sea; white the sand; red the energy of the people; gold the sun. The V-shape of the triangle echoes victory.`},{fromYear:1958,toYear:1962,flagUrl:t(`Flag_of_the_West_Indies_Federation.svg`),label:`West Indies Federation`,note:`From 1958 to 1962, Antigua was part of the West Indies Federation — an ambitious attempt to unite Britain's Caribbean colonies into a single independent nation. Its flag showed four white wavy lines (the sea) and an orange sun on blue. The federation collapsed in 1962 when Jamaica and Trinidad withdrew, leaving the smaller islands to pursue independence separately over the following two decades.`},{fromYear:1632,toYear:1958,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Leeward Islands (colonial era)`,note:`England colonised Antigua in 1632 and it became one of the most profitable sugar islands in the Caribbean, worked by enslaved Africans. As part of the British Leeward Islands colony, Antigua flew the British Blue Ensign defaced with the Leeward Islands badge. The plantation economy left Antigua with an overwhelmingly African-descended population whose heritage the modern flag's black field honours.`}],DM:[{fromYear:1978,toYear:null,flagUrl:`/Global/flags/dm.svg`,label:`Commonwealth of Dominica (independence)`,note:`Dominica's flag is one of the world's most distinctive — a green field with a cross of yellow, black, and white stripes, and at the centre a red circle bearing the rare Sisserou parrot (the imperial Amazon, found only in Dominica). The flag was adopted at independence from Britain in 1978 and is one of only two national flags to prominently feature purple (in the parrot). It was modified in 1981 and 1988 before reaching its current form.`},{fromYear:1958,toYear:1962,flagUrl:t(`Flag_of_the_West_Indies_Federation.svg`),label:`West Indies Federation`,note:`Dominica was one of the ten territories in the West Indies Federation (1958–1962), the failed attempt to forge a single independent Caribbean nation from Britain's colonies. Its blue flag with white waves and an orange sun represented the unity of the islands and the sea that both joined and separated them. When the federation dissolved, Dominica remained a British associated state until full independence in 1978.`},{fromYear:1763,toYear:1958,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Windward Islands (colonial era)`,note:`France and Britain contested Dominica for over a century — the island's rugged interior allowed the indigenous Kalinago (Carib) people and escaped enslaved Africans to resist colonisation longer than almost anywhere else in the Caribbean. Britain secured it in 1763 and governed it within the British Windward Islands colony, flying the defaced Blue Ensign. Dominica still has the Caribbean's only surviving pre-Columbian Kalinago population.`}],GD:[{fromYear:1974,toYear:null,flagUrl:`/Global/flags/gd.svg`,label:`Grenada (independence)`,note:`Grenada's flag — red border surrounding four gold stars at top and bottom, with green and yellow triangles and a red circle bearing one gold star at centre, plus a nutmeg on the green triangle — was adopted at independence from Britain in 1974. The nutmeg reflects Grenada's status as one of the world's largest nutmeg producers. In 1983 the United States invaded Grenada ("Operation Urgent Fury"), temporarily replacing the government; the flag was maintained throughout.`},{fromYear:1958,toYear:1962,flagUrl:t(`Flag_of_the_West_Indies_Federation.svg`),label:`West Indies Federation`,note:`Grenada joined the West Indies Federation in 1958. Notably, Grenadian premier and later Governor-General was a strong federalist — and after the federation collapsed in 1962, Grenada briefly explored a "unitary state" union with Trinidad and Tobago before opting for its own independence in 1974. The federation's blue-and-sun flag represented a Caribbean unity that never fully materialised.`},{fromYear:1763,toYear:1958,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Windward Islands (colonial era)`,note:`Grenada passed from French to British control in 1763. Under Britain it became a major producer of nutmeg and mace after the spice was introduced in 1843 — earning the nickname "Isle of Spice" and putting the nutmeg on its eventual national flag. As part of the British Windward Islands, Grenada flew the defaced Blue Ensign until the federation era.`}],KN:[{fromYear:1983,toYear:null,flagUrl:`/Global/flags/kn.svg`,label:`Saint Kitts and Nevis (independence)`,note:`Saint Kitts and Nevis gained independence from Britain on September 19, 1983 — the last British Caribbean territory on the mainland of the Lesser Antilles to do so. The flag's diagonal black stripe with two white stars on green and red was designed by Edrice Lewis. The stars represent the two islands; the green represents fertility; the red recalls the African heritage and the struggle for freedom; black is for the African heritage; yellow for the sunshine.`},{fromYear:1958,toYear:1962,flagUrl:t(`Flag_of_the_West_Indies_Federation.svg`),label:`West Indies Federation`,note:`Saint Kitts–Nevis–Anguilla was part of the West Indies Federation from 1958 to 1962. After it collapsed, the three-island colony became an associated state in 1967 — prompting Anguilla to rebel and break away rather than be ruled from Saint Kitts. The federation's flag of waves and sun symbolised a unity that, even at this small scale, proved difficult to hold together.`},{fromYear:1623,toYear:1958,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Leeward Islands (colonial era)`,note:`Saint Kitts was Britain's first Caribbean colony, settled in 1623, and was used as the launching point for the colonisation of surrounding islands — earning it the nickname "The Mother Colony of the West Indies." French and English settlers initially shared the island before the English prevailed. As part of the British Leeward Islands, Saint Kitts flew the defaced Blue Ensign. Brimstone Hill Fortress, a UNESCO site, dates from this colonial era.`}],LC:[{fromYear:1979,toYear:null,flagUrl:`/Global/flags/lc.svg`,label:`Saint Lucia (independence)`,note:`Saint Lucia's distinctive flag — a blue field with a white-edged black isosceles triangle surmounted by a smaller gold triangle — depicts the twin Pitons, the country's iconic volcanic peaks and a UNESCO World Heritage Site. Blue represents the sky and sea; gold the sunshine; black and white the harmony of the two main ethnic groups. The flag was modified in 2002 to make the gold triangle more prominent. Saint Lucia is the only country named after a woman.`},{fromYear:1958,toYear:1962,flagUrl:t(`Flag_of_the_West_Indies_Federation.svg`),label:`West Indies Federation`,note:`Saint Lucia was part of the West Indies Federation (1958–1962). After its collapse the island became a British associated state in 1967, gaining full internal self-government before independence in 1979. The federation's flag of an orange sun on blue waves stood for the Caribbean unity ideal that fragmented when its largest members departed.`},{fromYear:1814,toYear:1958,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Windward Islands (colonial era)`,note:`Saint Lucia changed hands between France and Britain fourteen times — more than any other Caribbean island — earning it the nickname "Helen of the West Indies" after the much-fought-over Helen of Troy. Britain finally secured it in 1814. The French legacy survives in the island's Creole language and place names. As part of the British Windward Islands, Saint Lucia flew the defaced Blue Ensign.`}],VC:[{fromYear:1985,toYear:null,flagUrl:`/Global/flags/vc.svg`,label:`Saint Vincent and the Grenadines`,note:`Saint Vincent's current flag — blue-gold-green vertical stripes with three green diamonds in a V formation on the gold — was adopted in 1985, replacing a version with a breadfruit leaf. The three diamonds represent the Grenadine islands; the blue represents the sky and sea; gold the warmth of the people; green the lush vegetation. Saint Vincent is known as the "Gem of the Antilles" and the last stronghold of the indigenous Caribs (now called Garifuna) in the Caribbean.`},{fromYear:1979,toYear:1985,flagUrl:t(`Flag_of_Saint_Vincent_and_the_Grenadines_(1979-1985).svg`),label:`First independence flag (breadfruit)`,note:`At independence in 1979, Saint Vincent's first flag carried the national coat of arms — featuring a breadfruit leaf — on a blue-gold-green tricolor. Breadfruit was famously brought to Saint Vincent by Captain Bligh in 1793 (after the mutiny on the Bounty derailed his first attempt) as a cheap food for the enslaved population. The busy arms were replaced in 1985 by the cleaner three-diamond design used today.`},{fromYear:1763,toYear:1958,flagUrl:t(`Government_Ensign_of_the_United_Kingdom.svg`),label:`British Windward Islands (colonial era)`,note:`Saint Vincent was one of the last Caribbean islands colonised, because the indigenous Garifuna (Black Caribs) — descendants of Caribs and shipwrecked Africans — fiercely resisted European settlement until the Second Carib War of 1795–96. After their defeat, the British deported thousands of Garifuna to Central America, where their descendants survive today. As part of the British Windward Islands, Saint Vincent flew the defaced Blue Ensign.`}],BY:[{fromYear:2012,toYear:null,flagUrl:`/Global/flags/by.svg`,label:`Flag of Belarus`,note:`A 2012 standardization made the hoist ornament red-on-white. The red-green bicolour is one of the few national flags that still keeps a Soviet-derived design rather than reverting after independence.`},{fromYear:1995,toYear:2012,flagUrl:t(`Flag_of_Belarus_(1995–2012).svg`),label:`Red-green flag (1995)`,note:`Introduced after a 1995 referendum, this revived the Soviet-era look without the communist symbols. The hoist ornament was originally rendered white-on-red.`},{fromYear:1991,toYear:1995,flagUrl:t(`Flag_of_Belarus_(1918,_1991–1995).svg`),label:`White-red-white flag`,note:`First used by the 1918 Belarusian People's Republic and readopted at independence in 1991. Dropped after the 1995 referendum, it is now the symbol of the Belarusian democratic opposition.`},{fromYear:1951,toYear:1991,flagUrl:t(`Flag_of_the_Byelorussian_Soviet_Socialist_Republic_(1951–1991).svg`),label:`Byelorussian SSR`,note:`A red field with a green bottom stripe and a red-and-white ornamental pattern at the hoist. Adopted in 1951, it directly inspired the flag Belarus flies today.`}],EE:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/ee.svg`,label:`Flag of Estonia (restored)`,note:`The blue-black-white tricolour, first raised by Estonian students in 1884, was restored in 1990 as the USSR collapsed. Blue is the sky, black the soil and hardship, white the people's striving for freedom.`},{fromYear:1953,toYear:1990,flagUrl:t(`Flag_of_the_Estonian_Soviet_Socialist_Republic.svg`),label:`Estonian SSR`,note:`The Soviet-era flag placed a gold hammer, sickle, and star on red above blue wavy bands evoking the Baltic Sea.`},{fromYear:1940,toYear:1953,flagUrl:t(`Flag_of_the_Estonian_Soviet_Socialist_Republic_(1940–1953).svg`),label:`Estonian SSR (early)`,note:`After Soviet annexation in 1940, a plain red flag with gold "ENSV" lettering and a hammer and sickle replaced the tricolour until the 1953 redesign.`},{fromYear:1918,toYear:1940,flagUrl:t(`Flag_of_Estonia.svg`),label:`Independence era`,note:`The same blue-black-white tricolour became the national flag at independence in 1918, before it was banned under Soviet rule and later restored.`}],LV:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/lv.svg`,label:`Flag of Latvia (restored)`,note:`Among the world's oldest flag designs, traced to a 13th-century chronicle, the maroon-white-maroon flag was restored in 1990. Its deep carmine shade is officially called "Latvian red".`},{fromYear:1953,toYear:1990,flagUrl:t(`Flag_of_the_Latvian_Soviet_Socialist_Republic_(1953–1990).svg`),label:`Latvian SSR`,note:`A gold hammer, sickle, and star on red above white and blue wavy bands symbolizing the sea.`},{fromYear:1940,toYear:1953,flagUrl:t(`Flag_of_the_Latvian_Soviet_Socialist_Republic_(1940–1953).svg`),label:`Latvian SSR (early)`,note:`Imposed after the 1940 Soviet annexation, a red flag with gold "Latvijas PSR" lettering and a hammer and sickle, used until the 1953 redesign.`},{fromYear:1918,toYear:1940,flagUrl:t(`Flag_of_Latvia.svg`),label:`Independence era`,note:`The ancient carmine-and-white flag was adopted at independence in 1918 before Soviet annexation, then restored unchanged in 1990.`}],LT:[{fromYear:1988,toYear:null,flagUrl:`/Global/flags/lt.svg`,label:`Flag of Lithuania (restored)`,note:`Yellow for the sun and prosperity, green for forests and hope, red for blood shed for the nation. It was the first Baltic flag readopted during the independence movement, restored in 1988.`},{fromYear:1953,toYear:1988,flagUrl:t(`Flag_of_the_Lithuanian_Soviet_Socialist_Republic_(1953–1988).svg`),label:`Lithuanian SSR`,note:`A gold hammer, sickle, and star on a red field above white and green horizontal bands.`},{fromYear:1940,toYear:1953,flagUrl:t(`Flag_of_the_Lithuanian_Soviet_Socialist_Republic_(1940–1953).svg`),label:`Lithuanian SSR (early)`,note:`After the 1940 Soviet occupation, a plain red flag with gold "LIETUVOS TSR" lettering and a hammer and sickle, used until the 1953 redesign.`},{fromYear:1918,toYear:1940,flagUrl:t(`Flag_of_Lithuania.svg`),label:`Independence era`,note:`The yellow-green-red tricolour was adopted at independence in 1918, banned under Soviet rule, and restored identical in 1988.`},{fromYear:1253,toYear:1795,flagUrl:t(`Flag_of_Lithuania_(state).svg`),label:`Grand Duchy of Lithuania (Vytis)`,note:`For centuries Lithuania was not a small Baltic state but one of medieval Europe's largest countries — the Grand Duchy of Lithuania, stretching from the Baltic nearly to the Black Sea. Its banner was the Vytis: a white armoured knight charging on horseback against a red field. After union with Poland it shared in the Polish-Lithuanian Commonwealth until the partitions erased both in 1795. The red Vytis flag survives today as Lithuania's official historical state flag.`}],UA:[{fromYear:1991,toYear:null,flagUrl:`/Global/flags/ua.svg`,label:`Flag of Ukraine`,note:`The blue-and-yellow bicolour was restored at independence in 1991, reviving the 1917 design. It is widely read as blue sky above golden wheat fields.`},{fromYear:1949,toYear:1991,flagUrl:t(`Flag_of_the_Ukrainian_Soviet_Socialist_Republic_(1949–1991).svg`),label:`Ukrainian SSR`,note:`A red flag with a light-blue band along the bottom third and a gold hammer, sickle, and star. The blue stripe set it apart from other Soviet republic flags.`},{fromYear:1917,toYear:1921,flagUrl:t(`Flag_of_Ukraine_(1917–1921).svg`),label:`Ukrainian People's Republic`,note:`The blue-over-yellow bicolour served the short-lived Ukrainian People's Republic during the revolutionary period, drawing on Ukrainian heraldic tradition.`},{fromYear:1649,toYear:1764,flagUrl:t(`Flag_of_the_Cossack_Hetmanate.svg`),label:`Cossack Hetmanate`,note:`The Cossack Hetmanate, founded by Bohdan Khmelnytsky in 1649, was a self-governing Cossack state that is widely regarded as a forerunner of Ukrainian statehood. Its banners were typically crimson with a cross and Cossack devices. Squeezed between Poland, the Ottomans and Muscovy, it was gradually absorbed by the Russian Empire, which abolished it in 1764.`}],MD:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/md.svg`,label:`Flag of Moldova`,note:`A blue-yellow-red vertical tricolour adopted in 1990, deliberately modelled on Romania's flag to reflect shared heritage, but bearing Moldova's eagle-and-aurochs coat of arms on the central stripe.`},{fromYear:1952,toYear:1990,flagUrl:t(`Flag_of_the_Moldavian_Soviet_Socialist_Republic_(1952–1990).svg`),label:`Moldavian SSR`,note:`A red field with a central green stripe and a gold hammer, sickle, and star. Its red-green-red layout closely resembles the flag of present-day breakaway Transnistria.`},{fromYear:1918,toYear:1940,flagUrl:`/Global/flags/ro.svg`,label:`Part of Romania (Bessarabia)`,note:`Most of present-day Moldova — historic Bessarabia — united with Romania in 1918 after a century under the Russian Empire, flying the Romanian flag. The 1939 Molotov–Ribbentrop Pact handed it to the USSR in 1940, which carved out the Moldavian SSR — the root of Moldova's lasting question of identity between Romania and the post-Soviet world.`},{fromYear:1346,toYear:1859,flagUrl:t(`Flag_of_Moldavia.svg`),label:`Principality of Moldavia`,note:`The medieval Principality of Moldavia — the realm of Stephen the Great, who held off Ottoman, Hungarian and Polish armies — flew a red banner bearing the head of an aurochs (a wild ox), the enduring symbol of the Moldavian lands. In 1859 Moldavia united with Wallachia to form modern Romania; the eastern half later became Moldova.`}],BA:[{fromYear:1998,toYear:null,flagUrl:`/Global/flags/ba.svg`,label:`Flag of Bosnia and Herzegovina`,note:`Imposed by High Representative Carlos Westendorp in 1998 after local politicians deadlocked, it was deliberately neutral. The yellow triangle suggests the country's shape and its three peoples; the stars represent Europe.`},{fromYear:1992,toYear:1998,flagUrl:t(`Flag_of_Bosnia_and_Herzegovina_(1992–1998).svg`),label:`Republic of Bosnia (war-era)`,note:`A white flag with a blue shield of six golden fleurs-de-lis, echoing the medieval Kotromanić dynasty. It flew throughout the Bosnian War but was seen by Serbs and Croats as too Bosniak-centric.`},{fromYear:1946,toYear:1992,flagUrl:t(`Flag_of_Bosnia_and_Herzegovina_(1946–1992).svg`),label:`SR Bosnia and Herzegovina`,note:`As a constituent Socialist Republic of Yugoslavia, Bosnia flew the plain Yugoslav red-white-blue tricolor with a gold-bordered red star — identical to the federal Yugoslav flag.`},{fromYear:1878,toYear:1918,flagUrl:t(`Flag_of_Bosnia_(1878–1908).svg`),label:`Austro-Hungarian Bosnia`,note:`After centuries under the Ottomans, Bosnia was occupied by Austria-Hungary in 1878 and formally annexed in 1908, flying a red-and-yellow flag with the provincial arms. Vienna's rule industrialised the province but stoked the Slav nationalism that, in Sarajevo in 1914, lit the fuse of the First World War.`},{fromYear:1831,toYear:1832,flagUrl:t(`Flag_of_Bosnia_(1831–1832).svg`),label:`Bosnian uprising (Husein Gradaščević)`,note:`In 1831 the Bosnian captain Husein Gradaščević led a revolt against Ottoman centralising reforms, briefly winning autonomy for Bosnia under a green flag with a gold crescent and star. The uprising was crushed in 1832, but "the Dragon of Bosnia" became an enduring folk hero of Bosnian self-rule.`}],HR:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/hr.svg`,label:`Flag of Croatia`,note:`Adopted in December 1990 as Yugoslavia dissolved, it centers the red-and-white checkerboard (šahovnica) beneath a crown of five historical regional shields, beginning with the oldest known Croatian coat of arms.`},{fromYear:1947,toYear:1990,flagUrl:t(`Flag_of_Croatia_(1947–1990).svg`),label:`SR Croatia`,note:`The Socialist Republic placed a gold-bordered red star at the center of the tricolor, deliberately omitting the traditional checkerboard during the Yugoslav period.`},{fromYear:1941,toYear:1945,flagUrl:t(`Flag_of_Croatia_(1941–1945).svg`),label:`Independent State of Croatia (NDH)`,note:`The WWII fascist puppet state kept the tricolor and checkerboard but added the Ustaše "U" emblem. It remains a taboo symbol because of the regime's genocidal crimes.`},{fromYear:1939,toYear:1941,flagUrl:t(`Flag_of_Banate_of_Croatia_(1939-1941).svg`),label:`Banovina of Croatia`,note:`On the eve of WWII, Croatia won a measure of autonomy within the Kingdom of Yugoslavia as the Banovina (Banate) of Croatia in 1939, flying the plain red-white-blue tricolor with the checkerboard. This brief self-government was swept away in 1941 when the Axis invaded and dismembered Yugoslavia.`},{fromYear:1921,toYear:1921,flagUrl:t(`Flag_of_Albona_Republic.svg`),label:`Labin Republic (Albona)`,note:`The Labin Republic was a short-lived 1921 workers' state in Istria, when coal miners seized the mines and declared self-rule against rising Italian Fascism. Its red flag bore a miner's hammer and pick. Italian troops crushed it within five weeks — one of Europe's earliest organized anti-fascist uprisings.`},{fromYear:1868,toYear:1918,flagUrl:t(`Flag_of_the_Kingdom_of_Croatia_(Habsburg).svg`),label:`Kingdom of Croatia (Austria-Hungary)`,note:`Within Austria-Hungary, Croatia-Slavonia was an autonomous kingdom flying a red-white-blue tricolor with the historic checkerboard shield. The pan-Slavic red-white-blue arrangement, chosen in the 19th-century national revival, is the direct ancestor of the modern Croatian flag.`}],RS:[{fromYear:2010,toYear:null,flagUrl:`/Global/flags/rs.svg`,label:`Flag of Serbia`,note:`A 2010 standardization set the coat of arms in its present form — the double-headed white eagle and the cross with four firesteels (the "Serbian cross").`},{fromYear:2004,toYear:2010,flagUrl:t(`Flag_of_Serbia_(2004–2010).svg`),label:`Tricolor with arms (2004)`,note:`In 2004 Serbia restored the double-headed eagle and shield, reviving royal-era symbolism abandoned under socialism.`},{fromYear:1992,toYear:2004,flagUrl:t(`Flag_of_Serbia_(1992–2004).svg`),label:`Plain red-blue-white`,note:`After the communist era Serbia simply dropped the star, leaving a bare tricolor that carried no coat of arms throughout the Milošević years.`},{fromYear:1947,toYear:1992,flagUrl:t(`Flag_of_the_Socialist_Republic_of_Serbia.svg`),label:`SR Serbia`,note:`The Socialist Republic flew a red-blue-white tricolor with a centered gold-bordered red star — visually identical to the flag of SR Montenegro.`},{fromYear:1882,toYear:1918,flagUrl:t(`Flag_of_Serbia_(1882–1918).svg`),label:`Kingdom of Serbia`,note:`When Serbia became a kingdom in 1882, its state flag was the red-blue-white tricolor charged with the royal coat of arms — the double-headed eagle beneath a crown. This is the direct ancestor of the modern flag; the kingdom dissolved into Yugoslavia in 1918.`}],SI:[{fromYear:1991,toYear:null,flagUrl:`/Global/flags/si.svg`,label:`Flag of Slovenia`,note:`Adopted at independence in June 1991, it replaced the red star with the national arms in the upper hoist: Mount Triglav, wavy lines for sea and rivers, and three gold stars of the Counts of Celje.`},{fromYear:1945,toYear:1991,flagUrl:t(`Flag_of_Slovenia_(1945–1991).svg`),label:`SR Slovenia`,note:`The Socialist Republic used a white-blue-red tricolor with a gold-bordered red star centered on it.`},{fromYear:1836,toYear:1918,flagUrl:t(`Flag_of_Krain.svg`),label:`Carniola (Slovene lands)`,note:`The Slovene white-blue-red tricolor was born in 1848, when Slovene nationalists adopted the colours of the Duchy of Carniola (Krain) — the historic Slovene heartland within the Habsburg Empire. It was the first distinctly Slovene flag, raised in defiance of Austrian-German rule, and is the direct ancestor of every Slovenian flag since.`}],MK:[{fromYear:1995,toYear:null,flagUrl:`/Global/flags/mk.svg`,label:`Flag of North Macedonia`,note:`Adopted in 1995 to end the dispute with Greece, it shows a stylized golden sun with eight broadening rays on red. The flag was unchanged by the 2019 renaming to "North Macedonia".`},{fromYear:1992,toYear:1995,flagUrl:t(`Flag_of_Macedonia_(1992–1995).svg`),label:`Star of Vergina flag`,note:`The first independence flag bore the golden 16-rayed Star of Vergina, an ancient Macedonian symbol. Greece considered it theft of Hellenic heritage and imposed a blockade until it was changed.`},{fromYear:1946,toYear:1991,flagUrl:t(`Flag_of_the_Socialist_Republic_of_Macedonia_(1946–1991);_Flag_of_North_Macedonia_(1991-1992).svg`),label:`SR Macedonia`,note:`A plain red field with a gold-bordered red star in the canton — unusual among Yugoslav republics for being entirely red rather than a tricolor.`}],ME:[{fromYear:2004,toYear:null,flagUrl:`/Global/flags/me.svg`,label:`Flag of Montenegro`,note:`Adopted in 2004 ahead of independence: a red field with a gold border bearing the golden double-headed eagle of the historic House of Petrović-Njegoš, a deliberate break from the Serbian-style tricolor.`},{fromYear:1993,toYear:2004,flagUrl:t(`Flag_of_Montenegro_(1993–2004).svg`),label:`Plain tricolor`,note:`A red, light-blue and white tricolor in a 1:3 ratio — then the longest national flag proportions in the world — and nearly indistinguishable from Serbia's plain tricolor of the same era.`},{fromYear:1946,toYear:1993,flagUrl:t(`Flag_of_SR_Montenegro_(1946–1993).svg`),label:`SR Montenegro`,note:`The Socialist Republic's red-blue-white tricolor with a centered gold-bordered red star was visually identical to SR Serbia's flag.`},{fromYear:1905,toYear:1918,flagUrl:t(`Flag_of_Montenegro_(1905–1918).svg`),label:`Kingdom of Montenegro`,note:`Montenegro was an independent principality and then, from 1910, a kingdom under Nicholas I — the last of the warrior prince-bishops' line — flying a red-blue-white tricolor charged with the royal cypher and the double-headed eagle. Tiny but fiercely independent, the kingdom vanished in 1918 when it was absorbed into the new Yugoslavia, a loss that fuelled Montenegrin identity debates for a century.`}],XK:[{fromYear:2008,toYear:null,flagUrl:`/Global/flags/xk.svg`,label:`Flag of Kosovo`,note:`Adopted on 17 February 2008 with the declaration of independence — one of the world's newest national flags. It deliberately avoids Albanian and pan-Slavic colors, using a blue field with a gold map and six white stars for the main ethnic groups.`}],CZ:[{fromYear:1920,toYear:null,flagUrl:`/Global/flags/cz.svg`,label:`Czech flag (blue triangle)`,note:`Adopted by Czechoslovakia in 1920, adding a blue hoist triangle to distinguish it from Poland's. Czechia kept this exact flag after the peaceful 1993 split, despite a law barring successor states from using the federal flag.`},{fromYear:1939,toYear:1945,flagUrl:t(`Flag_of_the_Protectorate_of_Bohemia_and_Moravia.svg`),label:`Protectorate of Bohemia and Moravia`,note:`Under Nazi occupation (1939–1945) the Czech lands became the Protectorate of Bohemia and Moravia, flying a white-red-blue horizontal tricolor. The familiar blue-triangle national flag was suppressed for the duration and restored when Czechoslovakia was liberated in 1945.`},{fromYear:1918,toYear:1920,flagUrl:t(`Flag_of_Bohemia.svg`),label:`White-red bicolour`,note:`Newly independent Czechoslovakia first flew the historic white-over-red bicolour of Bohemia — but it was nearly identical to Poland's flag, prompting the 1920 redesign.`}],SK:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/sk.svg`,label:`Slovak flag (with arms)`,note:`Adopted in September 1992 before the split from Czechoslovakia, it shifts the national arms (a double cross on three hills) toward the hoist so the flag is not confused with other Slavic tricolors.`},{fromYear:1939,toYear:1945,flagUrl:t(`Flag_of_Slovakia_(1939–1945).svg`),label:`Plain Pan-Slavic tricolor`,note:`The WWII First Slovak Republic flew a plain white-blue-red tricolor identical to several other Slavic flags. The same plain design was briefly readopted in 1990–1992 before arms were added.`},{fromYear:1918,toYear:1992,flagUrl:`/Global/flags/cz.svg`,label:`Part of Czechoslovakia`,note:`Apart from the WWII puppet state, Slovakia spent most of the 20th century as the eastern half of Czechoslovakia (1918–1939 and 1945–1992), flying the Czechoslovak flag with its blue hoist triangle. Slovak frustration at being the junior partner drove the "Velvet Divorce" of 1993 — the peaceful split that gave Slovakia its own arms-bearing flag.`}],HU:[{fromYear:1957,toYear:null,flagUrl:`/Global/flags/hu.svg`,label:`Current tricolor`,note:`After the 1956 revolution was crushed, the Kádár government removed all heraldry, returning to the plain red-white-green tricolor. This emblem-free flag has remained Hungary's flag ever since.`},{fromYear:1956,toYear:1957,flagUrl:t(`Flag_of_Hungary_(1956_revolution).svg`),label:`1956 Revolution 'flag with the hole'`,note:`Revolutionaries cut the hated communist coat of arms out of the flag's center, leaving an iconic ragged hole. This "hole flag" became the enduring emblem of the 1956 uprising against Soviet rule.`},{fromYear:1949,toYear:1956,flagUrl:t(`Flag_of_Hungary_(1949-1956).svg`),label:`Communist (Rákosi arms)`,note:`The Stalinist Rákosi regime placed a Soviet-style emblem of wheat, hammer and red star at the flag's center — a foreign-looking symbol that Hungarians widely resented.`},{fromYear:1946,toYear:1949,flagUrl:t(`Flag_of_Hungary_(1946-1949,_1956-1957).svg`),label:`Republican (Kossuth arms)`,note:`The post-war Second Hungarian Republic restored the small Kossuth coat of arms to the tricolor. The same flag returned briefly during the 1956 revolution.`},{fromYear:1919,toYear:1946,flagUrl:t(`Flag_of_Hungary_(1915-1918,_1919-1946).svg`),label:`Pre-communist tricolor`,note:`The plain red-white-green tricolor flew over the interwar Kingdom of Hungary — a kingdom with no king, ruled by Regent Horthy.`},{fromYear:1896,toYear:1915,flagUrl:t(`Flag_of_Hungary_(1896-1915).svg`),label:`Kingdom of Hungary (Austria-Hungary)`,note:`Within the Austro-Hungarian Empire, the Kingdom of Hungary flew the red-white-green tricolor charged with the crowned middle coat of arms, often flanked by angels. It was the flag of the Hungarian half of the Dual Monarchy, at the height of Budapest's belle-époque grandeur, until the empire collapsed in 1918.`},{fromYear:1e3,toYear:1301,flagUrl:t(`Flag_of_Hungary_(11th_c._-_1301).svg`),label:`Árpád stripes (medieval kingdom)`,note:`The red-and-white horizontal stripes (the "Árpád stripes") were the banner of the House of Árpád, Hungary's founding dynasty, from around the 11th century. One of the oldest heraldic devices in Europe, they still occupy the left half of Hungary's coat of arms and remain a powerful — and politically contested — national symbol.`}],RO:[{fromYear:1989,toYear:null,flagUrl:`/Global/flags/ro.svg`,label:`Current tricolor`,note:`Post-revolution Romania restored the plain blue-yellow-red tricolor without any emblem. The official cobalt blue, chrome yellow and vermilion red shades were later fixed by law.`},{fromYear:1989,toYear:1989,flagUrl:t(`Flag_of_Romania_(1989_revolution).svg`),label:`1989 Revolution 'flag with the hole'`,note:`During the December 1989 revolution, protesters cut the socialist emblem out of the flag's center, leaving a defiant hole. It became the iconic image of the overthrow of Ceaușescu.`},{fromYear:1965,toYear:1989,flagUrl:t(`Flag_of_Romania_(1965–1989).svg`),label:`Socialist Republic emblem`,note:`Under Ceaușescu the emblem was finalized with the inscription "Republica Socialistă România". This is the flag protesters would later mutilate in 1989.`},{fromYear:1952,toYear:1965,flagUrl:t(`Flag_of_Romania_(1952–1965).svg`),label:`People's Republic (with star)`,note:`A red five-pointed star was added atop the emblem during the high-Stalinist period, the arms bordered by a ribbon in the national colors.`},{fromYear:1948,toYear:1952,flagUrl:t(`Flag_of_Romania_(1948–1952).svg`),label:`People's Republic (first emblem)`,note:`The new communist republic added a coat of arms with a rising sun, oil derrick and wheat to the tricolor's center.`},{fromYear:1867,toYear:1948,flagUrl:t(`Flag_of_Romania_(1867–1948,_1989–1995).svg`),label:`Kingdom of Romania`,note:`The plain blue-yellow-red vertical tricolor served the Romanian Old Kingdom and interwar monarchy. The colors trace back to the revolutions of 1848.`}],BG:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/bg.svg`,label:`Current tricolor`,note:`With the fall of communism the socialist emblem was removed, returning Bulgaria to the plain white-green-red tricolor. The green was originally inspired by Russia's Pan-Slavic flag.`},{fromYear:1971,toYear:1990,flagUrl:t(`Flag_of_Bulgaria_(1971–1990).svg`),label:`People's Republic (681 emblem)`,note:`The final socialist emblem added the date 681, marking the founding of the First Bulgarian Empire, alongside 1944 — the communist coup. This long-lived design ended in 1990.`},{fromYear:1967,toYear:1971,flagUrl:t(`Flag_of_Bulgaria_(1967–1971).svg`),label:`People's Republic (revised emblem)`,note:`A redesigned emblem with white wheat replaced the earlier gold version; the lion-and-star device remained in the upper hoist canton.`},{fromYear:1948,toYear:1967,flagUrl:t(`Flag_of_Bulgaria_(1948–1967).svg`),label:`People's Republic (first emblem)`,note:`The communist republic added a socialist emblem with a rampant lion, wheat ears and a red star to the canton, dated 9.IX.1944 for the communist coup.`},{fromYear:1879,toYear:1948,flagUrl:t(`Flag_of_Bulgaria.svg`),label:`Principality & Kingdom`,note:`After liberation from Ottoman rule, Bulgaria adopted the plain white-green-red tricolor, which served the principality and kingdom until the communist era — and was restored unchanged in 1990.`}],AL:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/al.svg`,label:`Current flag`,note:`After communism fell, the red star was removed on 7 April 1992, leaving the plain black double-headed eagle on red. The eagle derives from the 15th-century seal of national hero Skanderbeg.`},{fromYear:1946,toYear:1992,flagUrl:t(`Flag_of_Albania_(1946–1992).svg`),label:`Communist (red star)`,note:`Enver Hoxha's People's (later Socialist) Republic topped the eagle with a gold-edged red star, which flew through nearly five decades of hardline Stalinist isolation.`},{fromYear:1943,toYear:1944,flagUrl:t(`Flag_of_Albania_(1943–1944).svg`),label:`German occupation`,note:`After Italy capitulated in 1943, Nazi Germany occupied Albania and installed a puppet regime that flew the plain black eagle on red — stripped of the fascist fasces — while presenting itself as "independent." Communist-led partisans controlled much of the country and drove the Germans out by late 1944.`},{fromYear:1939,toYear:1943,flagUrl:t(`Flag_of_Albania_(1939–1943).svg`),label:`Italian protectorate`,note:`Under Italian occupation the eagle was flanked by two fascist fasces, replacing the Zog crown and tying Albania's symbol to Mussolini's regime.`},{fromYear:1928,toYear:1934,flagUrl:t(`Flag_of_Albania_(1928–1934).svg`),label:`Kingdom of Zog`,note:`When Ahmet Zogu proclaimed himself King Zog I, a royal crown was placed above the double-headed eagle and the monarchy styled itself the Kingdom of Albania.`},{fromYear:1925,toYear:1928,flagUrl:t(`Flag_of_the_Albanian_Republic_(1925–1928).svg`),label:`Albanian Republic`,note:`Between the principality and the monarchy, Ahmet Zogu first ruled as president of a short-lived Albanian Republic, whose flag placed the black double-headed eagle on red beneath a helmet — the helmet of Skanderbeg, the 15th-century national hero. Zogu dissolved the republic in 1928 to crown himself king.`},{fromYear:1914,toYear:1920,flagUrl:t(`Flag_of_Albania_(1914–1920).svg`),label:`Principality of Albania`,note:`The short-lived principality under Prince Wilhelm of Wied flew the black double-headed eagle on red, marking Albania's first modern statehood.`}],AD:[{fromYear:1866,toYear:null,flagUrl:`/Global/flags/ad.svg`,label:`Tricolor with arms`,note:`The vertical blue-yellow-red tricolor was introduced in 1866, its design popularly attributed to Napoleon III, one of Andorra's two co-princes. It was officially codified in 1971 and standardized in 1993.`},{fromYear:1806,toYear:1866,flagUrl:t(`Flag_of_Andorra_(1806–1866).svg`),label:`Red-yellow bicolour`,note:`Before the tricolor, Andorra used a plain two-band flag of red and yellow — the colors of the neighboring county of Foix and the Crown of Aragon — with no coat of arms.`}],LI:[{fromYear:1982,toYear:null,flagUrl:`/Global/flags/li.svg`,label:`Blue-red with crown`,note:`A restyled, more detailed gold crown was adopted in 1982. Blue represents the sky and red the evening fires lit in homes.`},{fromYear:1937,toYear:1982,flagUrl:t(`Flag_of_Liechtenstein_(1937–1982).svg`),label:`Crown added (1937)`,note:`At the 1936 Berlin Olympics, Liechtenstein discovered its flag was identical to Haiti's. To tell them apart, it added a gold princely crown in 1937 — also signifying its status as a principality.`},{fromYear:1921,toYear:1937,flagUrl:t(`Flag_of_Liechtenstein_(1921–1937).svg`),label:`Blue-red (no crown)`,note:`The plain blue-over-red bicolour was enshrined in the 1921 constitution — the very flag whose clash with Haiti's prompted the crown to be added.`}],LU:[{fromYear:1845,toYear:null,flagUrl:`/Global/flags/lu.svg`,label:`Red-white-blue tricolor`,note:`Fixed in 1845 and only legally formalized in 1993, Luxembourg's tricolor has been essentially unchanged for over 175 years. It is nearly identical to the Netherlands' flag but is longer and uses a lighter blue.`},{fromYear:1100,toYear:1845,flagUrl:t(`Civil_Ensign_of_Luxembourg.svg`),label:`Roude Léiw (the Red Lion)`,note:`Long before the tricolor, Luxembourg's emblem was the "Roude Léiw" — a red, double-tailed, crowned lion on a field of white and blue stripes, the arms of the medieval Counts (later Dukes) of Luxembourg dating to the 13th century. It still flies today as the country's civil ensign and is cherished as the older, more distinctly Luxembourgish banner.`}],MT:[{fromYear:1964,toYear:null,flagUrl:`/Global/flags/mt.svg`,label:`White-red with George Cross`,note:`At independence in 1964 the blue canton was dropped and the George Cross, edged in red, was placed directly on the white field so it would appear less prominent.`},{fromYear:1943,toYear:1964,flagUrl:t(`Flag_of_Malta_(1943–1964).svg`),label:`George Cross in a blue canton`,note:`The George Cross, awarded to the Maltese people by King George VI in 1942 for their WWII bravery during the Siege of Malta, was added to the flag in 1943 on a blue canton.`},{fromYear:1813,toYear:1943,flagUrl:`/Global/flags/gb.svg`,label:`British Malta`,note:`Malta became a British colony in 1813 and a vital naval fortress guarding the Mediterranean, flying the Union Jack (and a colonial blue ensign at sea) until the George Cross was added in 1943. Its strategic harbour made it one of the most heavily bombed places on earth during WWII's Siege of Malta.`},{fromYear:1530,toYear:1798,flagUrl:t(`Flag_of_the_Order_of_St._John_(various).svg`),label:`Order of Saint John (Knights of Malta)`,note:`For over 250 years Malta was ruled by the Knights Hospitaller — the Sovereign Military Order of Saint John — who flew a plain white cross on red. Granted the islands in 1530, the Knights famously withstood the Great Siege of 1565 by the Ottomans before Napoleon expelled them in 1798. Their eight-pointed white cross endures as the "Maltese cross."`}],MC:[{fromYear:1881,toYear:null,flagUrl:`/Global/flags/mc.svg`,label:`Red-white bicolour`,note:`Adopted in 1881 from the Grimaldi heraldic colors, this simple red-over-white bicolour is among the world's oldest continuous national flags. It is nearly identical to Indonesia's flag, differing mainly in proportion.`},{fromYear:1814,toYear:1881,flagUrl:t(`Flag_of_Monaco_(1814-1881).svg`),label:`Armorial flag (Grimaldi arms)`,note:`Before the modern bicolour, Monaco flew a white flag bearing the Grimaldi dynasty's red-and-white lozenge coat of arms with crown and supporters.`},{fromYear:1848,toYear:1861,flagUrl:t(`Flag_of_the_Free_Cities_of_Menton_and_Roquebrune_(1848-1849).svg`),label:`Free Cities of Menton and Roquebrune`,note:`Two Riviera towns that broke away from Monaco in 1848 and were eventually sold to France, shrinking the principality to its present tiny size.`}],SM:[{fromYear:2011,toYear:null,flagUrl:`/Global/flags/sm.svg`,label:`White-blue with arms`,note:`A Constitutional Law of 2011 definitively fixed the flag and slightly refined the arms. White stands for peace and blue for liberty; the arms show three towers on Monte Titano beneath the motto LIBERTAS.`},{fromYear:1862,toYear:2011,flagUrl:t(`Flag_of_San_Marino_(pre-2011).svg`),label:`White-blue with arms (1862)`,note:`The white-over-light-blue flag with the central coat of arms was standardized by decree in 1862 and flew almost unchanged for nearly 150 years.`}],VA:[{fromYear:2023,toYear:null,flagUrl:`/Global/flags/va.svg`,label:`Yellow-white with keys and tiara`,note:`The 2023 Fundamental Law accompanied a minor revision of the emblem. The flag remains one of only two square national flags in the world, alongside Switzerland.`},{fromYear:1929,toYear:2023,flagUrl:t(`Flag_of_Vatican_City_(1929–2001).svg`),label:`Original Vatican flag (1929)`,note:`Adopted with the 1929 Lateran Treaty that created Vatican City, the square yellow-and-white bicolor bears the crossed keys of St. Peter and the papal tiara, derived from the flag of the Papal States.`},{fromYear:1808,toYear:1870,flagUrl:t(`Flag_of_the_Papal_States_(1808-1870).svg`),label:`Papal States (yellow-white)`,note:`For over a thousand years the popes ruled a sovereign state across central Italy. In 1808 its flag changed from yellow-and-red to the gold-and-white that still flies over the Vatican — the gold and silver of the keys of Saint Peter. The Papal States were swallowed by a unifying Italy in 1870, leaving the popes stateless until the 1929 Lateran Treaty created tiny Vatican City.`},{fromYear:1750,toYear:1808,flagUrl:t(`Flag_of_the_Papal_States_(pre_1808).svg`),label:`Papal States (yellow-red)`,note:`Before 1808 the Papal States flew yellow-and-red — the traditional colours of the senate and people of Rome, inherited from antiquity. Napoleon's occupation prompted the switch to the gold-and-white that became the modern papal colours.`}],IS:[{fromYear:1944,toYear:null,flagUrl:`/Global/flags/is.svg`,label:`Current Icelandic flag`,note:`The red-cross-on-white-on-blue design was retained when Iceland became a fully independent republic in 1944. The colors are said to represent the island's fire (red), ice (white) and mountains (blue).`},{fromYear:1915,toYear:1944,flagUrl:t(`Flag_of_Iceland_(1918–1944).svg`),label:`Sovereign era (Danish crown)`,note:`A red cross was added inside the white cross by royal decree in 1915, and this became Iceland's flag when it gained sovereignty under the Danish crown in 1918 — the same design as today.`},{fromYear:1897,toYear:1915,flagUrl:t(`Hvítbláinn.svg`),label:`Hvítbláinn (white-blue)`,note:`Before the modern flag, Icelandic nationalists rallied behind the Hvítbláinn — a white cross on a sky-blue field, designed in 1897. Denmark refused to recognise it because it resembled the flag of Greece, and the dispute pushed Iceland to add the red cross, producing the blue-white-red design adopted in 1915.`}],CY:[{fromYear:2006,toYear:null,flagUrl:`/Global/flags/cy.svg`,label:`Copper island on white`,note:`In 2006 the shades were standardized and proportions set to 3:2. The map is rendered in copper for Cyprus's ancient copper mines, above two olive branches for peace — deliberately avoiding the colors of Greece and Turkey.`},{fromYear:1960,toYear:2006,flagUrl:t(`Flag_of_Cyprus_(1960–2006).svg`),label:`Independence flag (1960)`,note:`Adopted at independence from Britain in 1960, the flag deliberately avoided any cross or crescent and the blue/red of the two motherlands, aiming for neutrality between Greek and Turkish Cypriots.`},{fromYear:1922,toYear:1960,flagUrl:t(`Flag_of_Cyprus_(1922-1960).svg`),label:`British Crown Colony`,note:`A British protectorate from 1878 and a Crown Colony from 1925, Cyprus flew the British Blue Ensign defaced with the colonial badge — two red lions on a white shield, drawn from the arms of the Crusader Lusignan kings who once ruled the island. Cyprus had no flag of its own until independence in 1960.`}],ZM:[{fromYear:1996,toYear:null,flagUrl:`/Global/flags/zm.svg`,label:`Current flag`,note:`In 1996 the field green was brightened and the orange eagle redrawn to match the coat of arms. The eagle and red-black-orange stripes sit unusually in the fly rather than the center.`},{fromYear:1964,toYear:1996,flagUrl:t(`Flag_of_Zambia_(1964–1996).svg`),label:`Independence flag`,note:`Adopted at independence from Britain on 24 October 1964, replacing the Northern Rhodesia flag. This original version used a darker shade of green.`}],ZW:[{fromYear:1980,toYear:null,flagUrl:`/Global/flags/zw.svg`,label:`Flag of Zimbabwe`,note:`Adopted at independence in 1980, it uses the green-yellow-red-black ZANU-PF colors with a red star and the golden Zimbabwe Bird, a soapstone carving found at the ruins of Great Zimbabwe.`},{fromYear:1979,toYear:1980,flagUrl:t(`Flag_of_Zimbabwe_Rhodesia_(1979).svg`),label:`Zimbabwe Rhodesia`,note:`Used briefly by the short-lived state of Zimbabwe Rhodesia in 1979 after the internal settlement, featuring a Zimbabwe Bird on a white disc, before the country reverted to British control.`},{fromYear:1968,toYear:1979,flagUrl:t(`Flag_of_Rhodesia_(1968–1979).svg`),label:`Rhodesia (UDI era)`,note:`On the third anniversary of the Unilateral Declaration of Independence, the white-minority government adopted a green-white-green triband with the colonial arms — flying over an internationally unrecognized state.`},{fromYear:1964,toYear:1968,flagUrl:t(`Flag_of_Rhodesia_(1964–1968).svg`),label:`Rhodesia light-blue ensign`,note:`After Southern Rhodesia became simply "Rhodesia" in 1964, it flew a light-blue ensign with the colonial shield, retained through the 1965 UDI.`}],MW:[{fromYear:2012,toYear:null,flagUrl:`/Global/flags/mw.svg`,label:`Flag of Malawi (restored)`,note:`After President Mutharika's death, Parliament voted in 2012 to restore the original 1964 design — a rare "changed and changed back" flag story. The red rising sun symbolizes the dawn of freedom across Africa.`},{fromYear:2010,toYear:2012,flagUrl:t(`Flag_of_Malawi_(2010–2012).svg`),label:`'Full sun' flag`,note:`Changed in 2010 under President Mutharika to a full white sun, meant to show economic progress. The unpopular change was nicknamed the "Bingu flag" and reversed two years later.`},{fromYear:1964,toYear:2010,flagUrl:t(`Flag_of_Malawi.svg`),label:`Independence flag`,note:`Adopted at independence on 6 July 1964, the black-red-green triband with a red rising sun of 31 rays — the same design restored in 2012.`}],MZ:[{fromYear:1983,toYear:null,flagUrl:`/Global/flags/mz.svg`,label:`Flag of Mozambique`,note:`Adopted in 1983, this is the only national flag in the world to depict a modern assault rifle: a bayoneted AK-47 crossed with a hoe over an open book, atop a gold star.`},{fromYear:1975,toYear:1983,flagUrl:t(`Flag_of_Mozambique_(1975–1983).svg`),label:`Independence flag`,note:`Adopted at independence in 1975, it placed a white cogwheel emblem with a book, hoe, and rifle at the hoist where the four colored stripes converged.`},{fromYear:1974,toYear:1975,flagUrl:t(`Flag_of_Mozambique_(1974–1975).svg`),label:`Transitional FRELIMO flag`,note:`Used during the transition between the Portuguese ceasefire and full independence, based directly on the FRELIMO liberation-movement banner.`}],BW:[{fromYear:1966,toYear:null,flagUrl:`/Global/flags/bw.svg`,label:`Flag of Botswana`,note:`First hoisted at independence in 1966. The light blue stands for water and rain (the national motto "Pula" means "let there be rain"); the black band with white edges symbolizes racial harmony. It has never been changed.`},{fromYear:1885,toYear:1966,flagUrl:`/Global/flags/gb.svg`,label:`Bechuanaland Protectorate`,note:`Botswana was the British Bechuanaland Protectorate from 1885 until independence in 1966, flying the Union Jack. Unusually, Britain never settled or heavily developed the territory — it was administered from Mafeking, a town actually outside its borders in South Africa — which left Botswana to chart its own course at independence.`}],NA:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/na.svg`,label:`Flag of Namibia`,note:`Adopted at independence from South African rule in 1990, assembled from three finalist designs. Its diagonal red band, blue and green triangles, and golden sun reflect the colors of SWAPO.`},{fromYear:1915,toYear:1990,flagUrl:t(`Flag_of_South_Africa_(1928–1994).svg`),label:`South West Africa (South African rule)`,note:`After seizing it from Germany in 1915, South Africa governed the territory as South West Africa, eventually flying the orange-white-blue "Oranje-Blanje-Blou." Pretoria refused to relinquish the mandate and extended apartheid into the territory, triggering a decades-long liberation war by SWAPO until independence in 1990 — the last country in mainland Africa to be freed from colonial-style rule.`},{fromYear:1885,toYear:1887,flagUrl:t(`Flag_of_Germany_(1867–1918).svg`),label:`Republic of Upingtonia`,note:`A short-lived Boer trekker republic in northern Namibia, abandoned amid conflict with the Ovambo.`},{fromYear:1872,toYear:1885,flagUrl:t(`Flag_of_Rehoboth-Basterland.svg`),label:`Free Republic of Rehoboth`,note:`A self-governing state of the Baster people in central Namibia before German colonisation.`}],LS:[{fromYear:2006,toYear:null,flagUrl:`/Global/flags/ls.svg`,label:`Flag of Lesotho`,note:`Unveiled on the 40th anniversary of independence in 2006, it returned to a peaceful blue-white-green design with a black mokorotlo (traditional Basotho straw hat) in the center, representing the nation's people.`},{fromYear:1987,toYear:2006,flagUrl:t(`Flag_of_Lesotho_(1987–2006).svg`),label:`Military-coup flag`,note:`Following the 1986 military coup, this 1987 flag used a diagonal layout with an assegai, knobkerrie, and shield, reflecting the ruling Military Council.`},{fromYear:1966,toYear:1987,flagUrl:t(`Flag_of_Lesotho_(1966–1987).svg`),label:`Independence flag`,note:`Introduced at independence in 1966, this blue-green-red flag bore a white mokorotlo hat in the canton.`}],SZ:[{fromYear:1968,toYear:null,flagUrl:`/Global/flags/sz.svg`,label:`Flag of Eswatini`,note:`Adopted at independence in 1968, based on a military banner King Sobhuza II gave the Swazi Pioneer Corps in 1941, featuring a black-and-white Nguni shield with two spears and a fighting staff. The country renamed itself Eswatini in 2018, but the flag was unchanged.`},{fromYear:1903,toYear:1968,flagUrl:`/Global/flags/gb.svg`,label:`Swaziland Protectorate`,note:`Swaziland was a British protectorate from 1903 until independence in 1968, under the Union Jack. The Swazi monarchy survived the colonial era intact, and King Sobhuza II — who reigned for nearly 83 years, one of the longest in recorded history — led the nation to independence with its traditional kingship fully restored.`}],MU:[{fromYear:1968,toYear:null,flagUrl:`/Global/flags/mu.svg`,label:`The Four Bands`,note:`Adopted at independence in 1968 and known as "Les Quatre Bandes," it has four equal horizontal bands of red, blue, yellow, and green — one of very few national flags with four horizontal stripes.`},{fromYear:1810,toYear:1968,flagUrl:`/Global/flags/gb.svg`,label:`British Mauritius`,note:`Uninhabited until settlers arrived, Mauritius was held in turn by the Dutch (who hunted the dodo to extinction) and the French before Britain captured it in 1810. It flew the Union Jack as a British colony for over 150 years, its sugar plantations worked first by enslaved Africans and then by indentured labourers from India — the origin of the island's Indo-Mauritian majority — until independence in 1968.`}],SC:[{fromYear:1996,toYear:null,flagUrl:`/Global/flags/sc.svg`,label:`Flag of Seychelles`,note:`Adopted in 1996, the flag radiates five bands — blue, yellow, red, white and green — fanning out from the lower hoist like rays of a rising sun, symbolising a dynamic young country moving into the future. It is one of the few national flags using all the colours of its two main political parties together.`},{fromYear:1977,toYear:1996,flagUrl:t(`Flag_of_Seychelles_(1977–1996).svg`),label:`One-party era`,note:`After a 1977 coup ushered in a socialist one-party state, Seychelles flew a red-white-green design with wavy lines. It was replaced by the multi-coloured rays flag in 1996 when the country returned to multi-party democracy.`},{fromYear:1976,toYear:1977,flagUrl:t(`Flag_of_Seychelles_(1976–1977).svg`),label:`Independence flag`,note:`At independence from Britain in 1976, Seychelles adopted a flag diagonally divided into blue, red, white and green quarters — the colours of the two parties that formed the first coalition government, which lasted barely a year before the coup.`},{fromYear:1903,toYear:1976,flagUrl:t(`Flag_of_Seychelles_(1961–1976).svg`),label:`British colony`,note:`Settled by the French in the 18th century and captured by Britain in 1814, the Seychelles became a separate British Crown Colony in 1903, flying a Blue Ensign defaced with a colonial badge of a giant tortoise and palm. The islands' isolation in the Indian Ocean made them a place of exile for troublesome rulers from across the Empire.`}],SL:[{fromYear:1961,toYear:null,flagUrl:`/Global/flags/sl.svg`,label:`Flag of Sierra Leone`,note:`Adopted at independence in 1961, a green-white-blue tricolour. Green stands for agriculture and mountains, white for unity and justice, and blue for the natural harbour of Freetown.`},{fromYear:1916,toYear:1961,flagUrl:t(`Flag_of_Sierra_Leone_(1916–1961).svg`),label:`Colonial Blue Ensign (1914 arms)`,note:`A colonial Blue Ensign bearing Sierra Leone's own coat of arms, which depicted the Union Jack, a palm tree, and an African greeting an arriving ship.`},{fromYear:1889,toYear:1916,flagUrl:t(`Flag_of_Sierra_Leone_(1889–1916).svg`),label:`Colonial Blue Ensign (first badge)`,note:`The early British colonial flag: a Blue Ensign with a badge showing an elephant, oil palm, and mountains over the letters "S.L."`}],LR:[{fromYear:1847,toYear:null,flagUrl:`/Global/flags/lr.svg`,label:`Flag of Liberia`,note:`Adopted in 1847 when Liberia — founded by freed American slaves — declared independence. It mirrors the US Stars and Stripes but has 11 stripes for the signers of its Declaration and a single white star for Africa's then-only republic.`},{fromYear:1827,toYear:1847,flagUrl:t(`Flag_of_Liberia_(1827–1847).svg`),label:`Colonial flag (with cross)`,note:`Used while Liberia was a colony of the American Colonization Society, it copied the US flag but placed a white Christian cross in the canton instead of stars.`},{fromYear:1834,toYear:1857,flagUrl:t(`Flag_of_the_Republic_of_Maryland.svg`),label:`Republic of Maryland`,note:`A colony of freed African-Americans on the West African coast that governed itself before joining Liberia.`}],GM:[{fromYear:1965,toYear:null,flagUrl:`/Global/flags/gm.svg`,label:`Flag of The Gambia`,note:`Hoisted at independence in 1965 and designed by accountant Louis Thomasi. Its red, blue, and green bands separated by thin white stripes represent the sun and savanna, the Gambia River, and the land's forests.`},{fromYear:1889,toYear:1965,flagUrl:t(`Flag_of_The_Gambia_(1889–1965).svg`),label:`Colonial Blue Ensign`,note:`A British colonial Blue Ensign defaced with a badge bearing an elephant and palm tree, used throughout Gambia's period as a separate British colony.`}],CV:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/cv.svg`,label:`Flag of Cape Verde`,note:`Adopted in 1992 after multiparty democracy and a break from the union ideal with Guinea-Bissau. Its blue field, white-red-white stripes, and ring of ten yellow stars represent the ten main islands and a turn toward the Atlantic.`},{fromYear:1975,toYear:1992,flagUrl:t(`Flag_of_Cape_Verde_(1975–1992).svg`),label:`Independence flag (PAIGC)`,note:`Adopted at independence in 1975, it shared its design with Guinea-Bissau's flag (both led by the PAIGC), using pan-African colors with a black star framed by a corn cob and seashell.`}],ST:[{fromYear:1975,toYear:null,flagUrl:`/Global/flags/st.svg`,label:`Flag of São Tomé and Príncipe`,note:`Adopted at independence from Portugal in 1975, based on the flag of the MLSTP liberation movement. The two black stars on the yellow band represent the two islands, in pan-African colors.`},{fromYear:1753,toYear:1975,flagUrl:`/Global/flags/pt.svg`,label:`Portuguese São Tomé and Príncipe`,note:`These uninhabited equatorial islands were settled by Portugal in the late 1400s and became one of the world's first plantation economies — sugar, then coffee and cocoa — worked by enslaved Africans under the Portuguese flag. The islands flew Portugal's flag until the 1974 Carnation Revolution opened the door to independence in 1975.`}],GQ:[{fromYear:1979,toYear:null,flagUrl:`/Global/flags/gq.svg`,label:`Flag of Equatorial Guinea (restored)`,note:`The original 1968 design with the silk-cotton-tree coat of arms was restored in 1979 after dictator Macías Nguema was deposed, and remains in use.`},{fromYear:1973,toYear:1979,flagUrl:t(`Flag_of_Equatorial_Guinea_(1973–1979).svg`),label:`Macías-era variant`,note:`Under dictator Francisco Macías Nguema the central emblem was replaced with a coat of arms of tools, a sword, and a cockerel, with the motto "Unidad, Paz, Justicia."`},{fromYear:1968,toYear:1973,flagUrl:t(`Flag_of_Equatorial_Guinea.svg`),label:`Independence flag`,note:`Adopted at independence from Spain in 1968: green, white, and red bands with a blue hoist triangle and the silk-cotton-tree coat of arms at the center.`}],GA:[{fromYear:1960,toYear:null,flagUrl:`/Global/flags/ga.svg`,label:`Flag of Gabon`,note:`Modified days before independence in 1960 by removing the French canton and widening the central yellow band. Green stands for forests, yellow for the equator and sun, and blue for the sea.`},{fromYear:1959,toYear:1960,flagUrl:t(`Flag_of_Gabon_(1959–1960).svg`),label:`Autonomous republic flag`,note:`Used during autonomy within the French Community, with a narrow central yellow stripe and the French Tricolour in the canton — Gabon was the only French autonomous republic to display this link with France.`}],CM:[{fromYear:1975,toYear:null,flagUrl:`/Global/flags/cm.svg`,label:`Flag of Cameroon`,note:`Adopted in 1975 when Cameroon became a unitary state, merging the two earlier stars into a single central gold star symbolizing national unity.`},{fromYear:1961,toYear:1975,flagUrl:t(`Flag_of_Cameroon_(1961–1975).svg`),label:`Two-star federation flag`,note:`After the 1961 federation, two gold stars were added to the green band representing the two states — East (French) and West (British) Cameroon.`},{fromYear:1957,toYear:1961,flagUrl:t(`Flag_of_Cameroon_(1957–1961).svg`),label:`Plain green-red-yellow tricolour`,note:`Made law in 1957 and carried into independence in 1960, among the first pan-African-colored flags adopted by a sub-Saharan state.`}],CF:[{fromYear:1958,toYear:null,flagUrl:`/Global/flags/cf.svg`,label:`Flag of the Central African Republic`,note:`Designed by founding father Barthélemy Boganda in 1958, it uniquely fuses the French blue-white-red with the pan-African red-green-yellow, crossed by a vertical red "blood of unity" stripe. It was even kept unchanged during Bokassa's 1976–1979 "Central African Empire."`},{fromYear:1903,toYear:1958,flagUrl:`/Global/flags/fr.svg`,label:`French Ubangi-Shari`,note:`The territory was the French colony of Ubangi-Shari, part of French Equatorial Africa, flying the French tricolor. It was one of the most neglected and harshly exploited colonies in the French empire — run largely through brutal concession companies — until Barthélemy Boganda led it to autonomy and gave it both its name and its flag in 1958.`}],TD:[{fromYear:1959,toYear:null,flagUrl:`/Global/flags/td.svg`,label:`Flag of Chad`,note:`Adopted in 1959: a blue-yellow-red tricolour. Chad switched from pan-African green to blue to avoid clashing with Mali — coincidentally producing a flag nearly identical to Romania's, a resemblance Chad raised at the UN in 2004.`},{fromYear:1900,toYear:1959,flagUrl:`/Global/flags/fr.svg`,label:`French Chad`,note:`Conquered piecemeal around 1900 and folded into French Equatorial Africa, Chad flew the French tricolor as a colony. Remote and lightly governed, it was the last part of the federation to be brought fully under French control, and gained its own flag only on the eve of independence in 1959–60.`}],CI:[{fromYear:1959,toYear:null,flagUrl:`/Global/flags/ci.svg`,label:`Flag of Côte d'Ivoire`,note:`Adopted in 1959 on the eve of independence: vertical orange, white and green. Orange stands for the savanna and the land's fertility, white for peace, green for the forests and hope. It is a mirror image of Ireland's flag and very close to Niger's — a similarity that is pure coincidence of pan-national colour choices.`},{fromYear:1893,toYear:1959,flagUrl:`/Global/flags/fr.svg`,label:`French Côte d'Ivoire`,note:`Declared a French colony in 1893 and later part of French West Africa, Côte d'Ivoire flew the French tricolor. It became the wealthiest and most productive colony in the federation through cocoa and coffee, a prosperity that continued after Félix Houphouët-Boigny led it to independence in 1960 under its own orange-white-green flag.`}],CG:[{fromYear:1991,toYear:null,flagUrl:`/Global/flags/cg.svg`,label:`Flag of the Republic of the Congo`,note:`With the collapse of the one-party Marxist state in 1991, the country readopted its original 1959 diagonal green-yellow-red tricolour in the pan-African colors.`},{fromYear:1970,toYear:1991,flagUrl:t(`Flag_of_the_People's_Republic_of_the_Congo.svg`),label:`People's Republic flag`,note:`Under the Marxist-Leninist People's Republic of the Congo, a red field bore a crossed hoe and hammer within a star and palm wreath — one of Africa's few openly communist state flags.`},{fromYear:1959,toYear:1970,flagUrl:t(`Flag_of_the_Republic_of_the_Congo.svg`),label:`Original tricolour`,note:`Adopted in 1959 before full independence, this green-yellow-red diagonal tricolour was abolished when the Marxist regime took power — then restored unchanged in 1991.`},{fromYear:1550,toYear:1883,flagUrl:t(`Flag_of_the_Kingdom_of_Loango.svg`),label:`Kingdom of Loango`,note:`A coastal Kongo-related kingdom north of the Congo River, a major exporter of copper, ivory and enslaved people.`}],CD:[{fromYear:2006,toYear:null,flagUrl:`/Global/flags/cd.svg`,label:`Flag of the DR Congo`,note:`The 2006 constitution confirmed a sky-blue flag with a yellow star and a red, yellow-bordered diagonal stripe. Blue stands for peace, red for the blood of martyrs, and yellow for the country's wealth.`},{fromYear:1997,toYear:2006,flagUrl:t(`Flag_of_the_Democratic_Republic_of_the_Congo_(1997–2006).svg`),label:`Return to blue (Kabila)`,note:`After Laurent-Désiré Kabila overthrew Mobutu, the country reverted to a 1960s-style blue flag with a single star and red diagonal, in a deeper royal blue.`},{fromYear:1971,toYear:1997,flagUrl:t(`Flag_of_Zaire_(1971–1997).svg`),label:`Zaire`,note:`Mobutu Sese Seko renamed the country Zaire and adopted a green flag with a yellow disc bearing a hand holding a flaming torch, symbolizing revolution and "authenticité".`},{fromYear:1963,toYear:1971,flagUrl:t(`Flag_of_the_Republic_of_the_Congo_(Léopoldville)_(1963–1966).svg`),label:`Blue flag with red diagonal`,note:`A large yellow star in the upper hoist and a yellow-edged red diagonal across the blue field — the design later revived as the basis of the modern flag.`},{fromYear:1960,toYear:1963,flagUrl:t(`Flag_of_the_Republic_of_the_Congo_(Léopoldville)_(1960–1963).svg`),label:`Independence flag`,note:`At independence from Belgium in 1960, the flag was blue with one large yellow star and six small stars for the founding provinces of the new state.`,parallelCaption:`Secessionist states of the Congo Crisis`,parallel:[{fromYear:1960,toYear:1963,flagUrl:t(`Flag_of_Katanga.svg`),label:`State of Katanga`,note:`The mineral-rich Katanga province seceded under Moïse Tshombe days after Congo's 1960 independence, backed by Belgian mining interests. Its flag bore three red croisettes (copper-cross currency). UN forces ended the secession in 1963.`},{fromYear:1960,toYear:1962,flagUrl:t(`Flag_of_South_Kasai.svg`),label:`South Kasai`,note:`The diamond-rich South Kasai region also seceded in 1960 under Albert Kalonji, flying a flag with a hand holding the region's mineral wealth. It was reconquered by the central government in 1962.`}]},{fromYear:1964,toYear:1965,flagUrl:t(`Flag_of_the_Party_of_the_People's_Revolution.svg`),label:`Maquis of Fizi`,note:`A Lumumbist rebel 'people's republic' in the eastern Congo's Simba rebellion, briefly aided by Che Guevara.`}],AO:[{fromYear:1975,toYear:null,flagUrl:`/Global/flags/ao.svg`,label:`Flag of Angola`,note:`Adopted at independence from Portugal in 1975, red over black with a yellow machete, half-cogwheel, and star from the ruling MPLA's emblem. The design deliberately echoes the Soviet hammer-and-sickle.`},{fromYear:1655,toYear:1975,flagUrl:`/Global/flags/pt.svg`,label:`Portuguese Angola`,note:`Angola was a Portuguese possession for some four centuries — first a source of enslaved people for Brazil, later a settler colony — flying the flag of Portugal. Portugal's refusal to decolonise triggered a 14-year war of independence from 1961; when the 1974 Carnation Revolution toppled the regime in Lisbon, Angola finally won independence in 1975, only to fall straight into a long civil war.`},{fromYear:1390,toYear:1857,flagUrl:t(`Flag_of_the_Kingdom_of_Kongo_according_to_Giovanni_Cavazzi_da_Montecuccolo.svg`),label:`Kingdom of Kongo`,note:`Long before the Portuguese, northern Angola and the lower Congo were the heart of the Kingdom of Kongo, a sophisticated Central African state whose king converted to Christianity in 1491 and corresponded with European monarchs as an equal. The Atlantic slave trade slowly hollowed it out, and it survived as a shadow until the Portuguese abolished the monarchy in the 19th century.`},{fromYear:1975,toYear:1975,flagUrl:t(`Flag_of_Cabinda_(FLEC_propose).svg`),label:`Republic of Cabinda`,note:`The separatist republic declared in the oil-rich Cabinda enclave when Portugal withdrew, before Angola annexed it.`},{fromYear:1600,toYear:1885,flagUrl:t(`Royal_Banner_of_the_Kingdom_of_Kakongo_(c._1883).svg`),label:`Kingdom of Kakongo`,note:`A small Kongo kingdom of the Cabinda coast, north of the Congo River mouth.`},{fromYear:1600,toYear:1900,flagUrl:t(`Flag_of_Lunda_Tchokwe.svg`),label:`Chokwe Kingdom`,note:`The states of the Chokwe people of northeastern Angola, celebrated for their sophisticated art and ivory carving.`},{fromYear:1515,toYear:1671,flagUrl:t(`Flag_of_the_Kingdom_of_Ndongo.svg`),label:`Kingdom of Ndongo`,note:`An Mbundu kingdom of Angola whose Queen Njinga waged a decades-long war against Portuguese slavers.`},{fromYear:1500,toYear:1900,flagUrl:t(`Banner_of_the_Mbunda_Kingdom.svg`),label:`Mbunda Kingdom`,note:`A kingdom of the Mbunda people in southeastern Angola, known for its woodcarving and the Makishi masquerade.`}],RW:[{fromYear:2001,toYear:null,flagUrl:`/Global/flags/rw.svg`,label:`Flag of Rwanda`,note:`Completely redesigned in 2001 to break association with the old regime and the 1994 genocide: blue over yellow over green with a golden sun. Blue is peace, yellow economic development, green prosperity.`},{fromYear:1961,toYear:2001,flagUrl:t(`Flag_of_Rwanda_(1961–2001).svg`),label:`Original tricolour with 'R'`,note:`A red-yellow-green tricolour with a black capital "R" added to distinguish it from Guinea's identical flag. It flew through independence and the 1994 genocide before being replaced.`},{fromYear:1961,toYear:1962,flagUrl:t(`Flag_of_Rwanda_(January_–_September_1961).svg`),label:`Kingdom of Rwanda (transition)`,note:`In the transition to independence (1961–62), Rwanda flew a red-yellow-green vertical tricolor bearing a large black letter "R" — added to tell it apart from the near-identical flag of Guinea. The "R" flag was used until the 2001 redesign.`}],BI:[{fromYear:1982,toYear:null,flagUrl:`/Global/flags/bi.svg`,label:`Flag of Burundi`,note:`The current flag refined the proportions of the 1967 design: a white saltire dividing red and green fields, with three red stars on a central white disc for the motto "Unité, Travail, Progrès".`},{fromYear:1967,toYear:1982,flagUrl:t(`Flag_of_Burundi_(1967–1982).svg`),label:`Early republic flag`,note:`The republic replaced the monarchical symbols with three six-pointed red stars arranged in a triangle on the central disc.`},{fromYear:1966,toYear:1967,flagUrl:t(`Flag_of_Burundi_(1966–1967).svg`),label:`Transitional flag`,note:`After the monarchy was abolished in 1966, the royal drum was removed, leaving the sorghum plant on the white disc — a brief transitional design.`},{fromYear:1962,toYear:1966,flagUrl:t(`Flag_of_Burundi_(1962–1966).svg`),label:`Kingdom flag`,note:`At independence as a monarchy, the flag carried a royal drum (karyenda) and a sorghum plant on the red-and-green saltire. The drum symbolized the Tutsi monarchy.`}],UG:[{fromYear:1962,toYear:null,flagUrl:`/Global/flags/ug.svg`,label:`Flag of Uganda`,note:`Adopted at independence from Britain in 1962, with six black-yellow-red stripes and a central white disc bearing the grey crowned crane — the national bird, facing the hoist.`},{fromYear:1894,toYear:1962,flagUrl:`/Global/flags/gb.svg`,label:`Uganda Protectorate`,note:`Uganda became a British protectorate in 1894 and flew the Union Jack until independence in 1962. Because it was governed as a protectorate rather than a settler colony, the powerful kingdom of Buganda and other traditional monarchies survived the colonial period — a legacy that shaped, and complicated, the politics of the independent state.`},{fromYear:1962,toYear:1982,flagUrl:t(`Flag_of_Rwenzururu.svg`),label:`Kingdom of Rwenzururu`,note:`A secessionist mountain kingdom of the Bakonzo people in the Rwenzori range on the Uganda–Congo border.`},{fromYear:1830,toYear:1967,flagUrl:t(`Flag_of_the_Tooro_Kingdom.svg`),label:`Tooro Kingdom`,note:`A western Ugandan kingdom that broke away from Bunyoro; restored as a cultural monarchy in 1993.`},{fromYear:1600,toYear:1962,flagUrl:t(`Flag_of_Busoga_(royal_standard).png`),label:`Busoga`,note:`A confederation of chiefdoms in southeastern Uganda, between Lake Victoria and the Nile.`},{fromYear:1480,toYear:1967,flagUrl:t(`Flag_of_Ankole.svg`),label:`Ankole`,note:`A cattle-herding kingdom of southwestern Uganda, its society famed for the long-horned Ankole cattle.`},{fromYear:1300,toYear:1896,flagUrl:t(`Bunyoro-Kitara_Kingdom_Flag.png`),label:`Bunyoro`,note:`Once the most powerful of the Great Lakes kingdoms in western Uganda, gradually eclipsed by Buganda and the British.`}],KE:[{fromYear:1963,toYear:null,flagUrl:`/Global/flags/ke.svg`,label:`Flag of Kenya`,note:`Adopted at independence in 1963: black, red, and green bands separated by white fimbriations, with a central Maasai shield and crossed spears symbolizing the defence of freedom.`},{fromYear:1895,toYear:1963,flagUrl:`/Global/flags/gb.svg`,label:`British East Africa / Kenya Colony`,note:`Britain ran the territory as the East Africa Protectorate from 1895 and then Kenya Colony from 1920, flying the Union Jack. The fertile "White Highlands" were reserved for European settlers, fuelling the grievances behind the 1950s Mau Mau uprising, whose brutal suppression hastened the path to independence in 1963.`},{fromYear:1858,toYear:1923,flagUrl:t(`Flagge_Witu_1890_laut_Voeltzkow.svg`),label:`Witu Sultanate`,note:`A small Swahili sultanate on the Kenyan coast that briefly sought German protection before falling to Britain.`}],TZ:[{fromYear:1964,toYear:null,flagUrl:`/Global/flags/tz.svg`,label:`Flag of Tanzania`,note:`After Tanganyika and Zanzibar united in 1964, a new flag merged Tanganyika's green and black with Zanzibar's blue into a yellow-edged black diagonal. Green is land, blue sea, black the people, yellow mineral wealth.`},{fromYear:1961,toYear:1964,flagUrl:t(`Flag_of_Tanganyika_(1961–1964).svg`),label:`Flag of Tanganyika`,note:`Independent Tanganyika flew a green field with a central black, yellow-edged stripe — colors that carried directly into the union flag.`,parallelCaption:`Zanzibar, which united with Tanganyika to form Tanzania`,parallel:[{fromYear:1963,toYear:1964,flagUrl:t(`Flag_of_the_Sultanate_of_Zanzibar_(1963).svg`),label:`Sultanate of Zanzibar`,note:`Zanzibar gained independence from Britain as a constitutional sultanate in December 1963, flying a plain red flag (the historic colour of its Omani-descended dynasty). It lasted barely a month before being overthrown.`},{fromYear:1964,toYear:1964,flagUrl:t(`Flag_of_Zanzibar_(January-April_1964).svg`),label:`People's Republic of Zanzibar`,note:`The January 1964 revolution overthrew the sultan and raised a blue-black-green flag. In April 1964 it merged with Tanganyika to form Tanzania — the "Tan" + "Zan" of the new name.`}]},{fromYear:975,toYear:1513,flagUrl:t(`Flag_used_in_the_east_coast_of_Tanzania_according_to_a_Portuguese_1576_map.svg`),label:`Kilwa Sultanate`,note:`A fabulously wealthy Swahili-coast sultanate on an island off Tanzania, controlling the medieval gold trade from Great Zimbabwe.`}],KM:[{fromYear:2002,toYear:null,flagUrl:`/Global/flags/km.svg`,label:`Flag of the Comoros`,note:`Hoisted in 2002, with four horizontal stripes and a green hoist triangle bearing a crescent and four stars. The four stripes and four stars each represent the islands, including French-administered Mayotte.`},{fromYear:2001,toYear:2002,flagUrl:t(`Flag_of_the_Comoros_2001.svg`),label:`Transitional flag`,note:`A short-lived transitional flag during the constitutional reform that created the Union of the Comoros.`},{fromYear:1996,toYear:2001,flagUrl:t(`Flag_of_the_Comoros_(1996–2001).svg`),label:`Crescent-and-inscription flag`,note:`A green flag with a large central crescent enclosing four stars, flanked by Arabic text reading "Allah" and "Muhammad," emphasizing the islands' Islamic character.`},{fromYear:1992,toYear:1996,flagUrl:t(`Flag_of_the_Comoros_(1992–1996).svg`),label:`Bordered green flag`,note:`A green flag with the crescent and four stars in a vertical white hoist band. The four stars represent Grande Comore, Anjouan, Mohéli, and Mayotte.`},{fromYear:1978,toYear:1992,flagUrl:t(`Flag_of_the_Comoros_(1978–1992).svg`),label:`Federal Islamic Republic flag`,note:`After the 1978 mercenary-backed coup, the green flag was redesigned with the crescent, four stars, and an Arabic inscription.`},{fromYear:1975,toYear:1978,flagUrl:t(`Flag_of_the_Comoros_(1975–1978).svg`),label:`First independence flag`,note:`The first flag after the 1975 unilateral independence: a plain green field with a white crescent and four stars, reflecting the islands' Islamic identity. The Comoros went on to change its flag more often than almost any nation.`}],MG:[{fromYear:1958,toYear:null,flagUrl:`/Global/flags/mg.svg`,label:`Flag of Madagascar`,note:`Adopted in 1958 as the Malagasy Republic gained autonomy within the French Community. White and red recall the historic Merina kingdom, while green honors the Hova commoners.`},{fromYear:1897,toYear:1958,flagUrl:`/Global/flags/fr.svg`,label:`French Madagascar`,note:`France conquered the independent Kingdom of Madagascar in 1895–96, abolished the monarchy, and ruled the island as a colony under the French tricolor. A 1947 nationalist revolt was crushed with tens of thousands of deaths, but the island's own white-and-red royal colours survived to be woven into the flag adopted as autonomy returned in 1958.`},{fromYear:1787,toYear:1896,flagUrl:t(`Flag_of_the_Merina_Kingdom.svg`),label:`Kingdom of Madagascar (Merina)`,note:`Before the French, almost the whole island was unified under the Merina monarchy — the Kingdom of Madagascar — which flew a white-and-red flag often bearing the royal initials. A sophisticated state that traded with Europe and adopted Christianity and a written script, it kept its independence until France invaded and abolished the monarchy in 1896. Its white-and-red endures at the hoist of the modern flag.`},{fromYear:1690,toYear:1840,flagUrl:t(`Flag_of_the_Boina_Kingdom.svg`),label:`Kingdom of Boina`,note:`A powerful Sakalava kingdom of northwest Madagascar, rich from the slave and cattle trade, before the Merina unification.`}],DZ:[{fromYear:1962,toYear:null,flagUrl:`/Global/flags/dz.svg`,label:`Flag of Algeria`,note:`Adopted in 1962, the day before formal independence, with equal green and white vertical bands and a red crescent and star symbolizing Islam.`},{fromYear:1958,toYear:1962,flagUrl:t(`Flag_of_Algeria_(1958-1962).svg`),label:`Provisional Government flag`,note:`The green-white flag with red crescent and star, used by the National Liberation Front from 1954 and the Provisional Government in exile, became the basis of the independence flag.`},{fromYear:1830,toYear:1962,flagUrl:t(`Flag_of_France.svg`),label:`French rule`,note:`Under French rule Algeria was administered as an integral part of France rather than a colony, so the French tricolour flew with no distinct Algerian national flag.`},{fromYear:1832,toYear:1847,flagUrl:t(`Flag_of_the_Emirate_of_Mascara.svg`),label:`Emirate of Mascara`,note:`The state founded by Emir Abdelkader to wage Algeria's long resistance against the French conquest.`},{fromYear:1516,toYear:1830,flagUrl:t(`Flag_of_Regency_of_Algiers.svg`),label:`Regency of Algiers`,note:`The Ottoman-aligned corsair state that ruled Algeria for three centuries, its fleets dominating the western Mediterranean until the French invasion.`},{fromYear:1235,toYear:1556,flagUrl:t(`Flag_of_the_Kingdom_of_Tlemcen_(Book_of_All_Kingdoms).svg`),label:`Kingdom of Tlemcen`,note:`A Zayyanid Berber kingdom in western Algeria, a hub of trans-Saharan trade and scholarship before Ottoman annexation.`}],TN:[{fromYear:1999,toYear:null,flagUrl:`/Global/flags/tn.svg`,label:`Flag of Tunisia`,note:`A 1999 law formalized the flag for the first time, only slightly adjusting the crescent and proportions of a design that had flown almost unchanged since 1831 — among the oldest in the Arab world.`},{fromYear:1831,toYear:1999,flagUrl:t(`Flag_of_the_Beylik_of_Tunis_(1831–1881)_and_Tunisia_(1881–1959).svg`),label:`Husainid red flag`,note:`Hussein II created this red flag with a white disc, crescent, and star around 1831 to distinguish the Tunisian fleet. It survived the French protectorate and independence essentially unchanged.`}],MA:[{fromYear:1915,toYear:null,flagUrl:`/Global/flags/ma.svg`,label:`Flag of Morocco`,note:`In 1915 Sultan Yusef added the green interlaced pentagram (Seal of Solomon) to the red field, partly to distinguish Moroccan ships. The design survived the French and Spanish protectorate eras.`,parallelCaption:`Breakaway republic during the Rif War`,parallel:[{fromYear:1921,toYear:1926,flagUrl:t(`Flag_of_the_Republic_of_the_Rif.svg`),label:`Republic of the Rif`,note:`Berber leader Abd el-Krim founded the Republic of the Rif in 1921 after crushing a Spanish army at Annual. Its red flag bore a white rhombus and crescent. A joint Spanish-French offensive — using early chemical weapons — ended it in 1926.`}]},{fromYear:1666,toYear:1915,flagUrl:t(`Flag_of_Morocco_(1666–1915).svg`),label:`Plain red flag`,note:`When the Alaouite dynasty took power in 1666 it adopted a plain red field, used on land and by Moroccan ships for nearly 250 years.`},{fromYear:1624,toYear:1668,flagUrl:t(`Flag_of_the_Republic_of_Salé_(1624-1668).svg`),label:`Republic of Salé`,note:`A Barbary corsair pirate republic on the Atlantic coast, run by Moriscos expelled from Spain who raided shipping across the seas.`}],TW:[{fromYear:1945,toYear:null,flagUrl:`/Global/flags/tw.svg`,label:`Flag of the Republic of China`,note:`The Republic of China adopted the "Blue Sky, White Sun and a Wholly Red Earth" as its national flag in 1928. It has flown over Taiwan since the island was handed to the Republic of China at the end of the Second World War in 1945, and the government moved there in 1949 after losing the Chinese Civil War.`},{fromYear:1895,toYear:1945,flagUrl:`/Global/flags/jp.svg`,label:`Japanese rule`,note:`After its defeat in the First Sino-Japanese War, the Qing dynasty ceded Taiwan to Japan in the Treaty of Shimonoseki of 1895. The island was a Japanese colony for fifty years, until Japan's surrender in 1945.`},{fromYear:1895,toYear:1895,flagUrl:t(`Flag_of_the_Republic_of_Formosa_(1895).svg`),label:`Republic of Formosa`,note:`Local officials declared the Republic of Formosa in May 1895 to resist the handover to Japan, under a blue flag with a yellow tiger. Japanese forces took the island and the republic collapsed that October.`},{fromYear:1889,toYear:1895,flagUrl:t(`Flag_of_the_Qing_dynasty_(1889-1912).svg`),label:`Qing dynasty`,note:`Taiwan was made a province of the Qing Empire in 1887. The rectangular Yellow Dragon Flag, a blue dragon chasing a red pearl, became the Qing national flag in 1889 and flew until the island was ceded to Japan.`}],MR:[{fromYear:2017,toYear:null,flagUrl:`/Global/flags/mr.svg`,label:`Flag of Mauritania`,note:`A 2017 referendum added horizontal red bands top and bottom to honor the blood shed by Mauritanians in the struggle for independence.`},{fromYear:1959,toYear:2017,flagUrl:t(`Flag_of_Mauritania_(1959–2017).svg`),label:`Green flag with crescent and star`,note:`Adopted in 1959 ahead of independence from France: a plain green field with a gold crescent and star, both colors and symbols of Islam.`}],SD:[{fromYear:1970,toYear:null,flagUrl:`/Global/flags/sd.svg`,label:`Flag of Sudan`,note:`Adopted in 1970 after Gaafar Nimeiry's coup, using the pan-Arab red-white-black tricolour with a green hoist triangle, based on the Arab Liberation Flag of Egypt's 1952 revolution.`},{fromYear:1956,toYear:1970,flagUrl:t(`Flag_of_Sudan_(1956–1970).svg`),label:`Independence tricolour`,note:`Adopted at independence in 1956, with blue for the Nile, yellow for the Sahara, and green for farmland.`},{fromYear:1899,toYear:1956,flagUrl:`/Global/flags/gb.svg`,label:`Anglo-Egyptian Sudan`,note:`After Britain crushed the Mahdist State, Sudan was governed from 1899 to 1956 as the Anglo-Egyptian Sudan — nominally a joint British–Egyptian condominium, in practice run by Britain under the Union Jack and Egyptian flags. Its administration deliberately developed the Arab-Muslim north and the African-Christian south separately, planting the seeds of the civil wars that eventually split off South Sudan.`},{fromYear:1885,toYear:1898,flagUrl:t(`Flag_of_the_Mahdi_movement_in_Sudan.svg`),label:`Mahdist State`,note:`In 1881 a Sudanese religious leader, Muhammad Ahmad, declared himself the Mahdi and led a holy war that swept away Egyptian rule — famously killing General Gordon at the fall of Khartoum in 1885. His Mahdist State, flying banners inscribed with the shahada, was the first independent Sudanese nation, until a British–Egyptian army destroyed it at Omdurman in 1898.`},{fromYear:600,toYear:1500,flagUrl:t(`Possible_Flag_of_the_Kingdom_of_Alodia_(c._1350).svg`),label:`Alodia`,note:`Alwa, the southern of the medieval Christian Nubian kingdoms, centred at Soba near modern Khartoum.`},{fromYear:340,toYear:1518,flagUrl:t(`The_flag_of_the_'Kingdom_of_Dongola'_(Makuria)_in_the_"Book_of_all_kingdoms"_(C._1350).svg`),label:`Makuria`,note:`A Christian Nubian kingdom on the Nile whose archers held back the early Arab conquests for centuries.`}],SS:[{fromYear:2011,toYear:null,flagUrl:`/Global/flags/ss.svg`,label:`Flag of South Sudan`,note:`Based on the SPLM liberation banner and first adopted in 2005 under the peace agreement, it carried over unchanged when South Sudan became the world's newest country in 2011.`},{fromYear:1956,toYear:2011,flagUrl:`/Global/flags/sd.svg`,label:`Part of Sudan`,note:`The mostly Christian and animist south was governed as part of Arab-Muslim Sudan from its 1956 independence, flying the Sudanese flag. Two long civil wars over that domination — the second alone killing some two million people — ended in a 2005 peace deal that granted a referendum, and in 2011 the south voted almost unanimously to secede as South Sudan.`},{fromYear:1490,toYear:1865,flagUrl:t(`Flag_of_the_Shilluk.svg`),label:`Shilluk Kingdom`,note:`A Nilotic kingdom along the White Nile, ruled by a divine king (the reth) — among the historic states of what is now South Sudan.`}],ET:[{fromYear:2009,toYear:null,flagUrl:`/Global/flags/et.svg`,label:`Flag of Ethiopia`,note:`A 2009 standardization fixed the current national emblem — a gold rayed pentagram on a blue disc — whose rays symbolize the equality and unity of Ethiopia's peoples. The red-yellow-green is one of the world's oldest tricolors.`},{fromYear:1996,toYear:2009,flagUrl:t(`Flag_of_Ethiopia_(1996–2009).svg`),label:`National emblem flag (light disc)`,note:`The current design debuted in 1996, adding the gold pentagram on a blue disc; the shade and proportions were tweaked over the following years.`},{fromYear:1987,toYear:1991,flagUrl:t(`Flag_of_Ethiopia_(1987–1991).svg`),label:`PDRE socialist flag`,note:`When Mengistu's People's Democratic Republic was proclaimed in 1987, a state emblem with a red star, gear, and rising sun was added.`},{fromYear:1975,toYear:1987,flagUrl:t(`Flag_of_Ethiopia_(1975–1987).svg`),label:`Plain Derg tricolour`,note:`From 1975 the military Derg flew the bare red-yellow-green tricolour with no emblem, stripping away all imperial symbolism.`},{fromYear:1897,toYear:1974,flagUrl:t(`Flag_of_Ethiopia_(1897-1936;_1941-1974).svg`),label:`Imperial Lion of Judah`,note:`Menelik II fixed the tricolour in 1897; from 1914 it bore the crowned Lion of Judah holding a cross-tipped staff, emblem of the Solomonic dynasty — interrupted only by the Italian occupation of 1936–1941.`}],ER:[{fromYear:1995,toYear:null,flagUrl:`/Global/flags/er.svg`,label:`Flag of Eritrea`,note:`Adopted in 1995, the olive wreath was standardized to 30 leaves, symbolizing the 30 years of armed struggle that preceded independence.`},{fromYear:1993,toYear:1995,flagUrl:t(`Flag_of_Eritrea_(1993–1995).svg`),label:`Early independence flag`,note:`First hoisted at independence in 1993, combining the EPLF's red-green-blue triangular design with a gold olive wreath drawn from the 1952 flag.`},{fromYear:1952,toYear:1961,flagUrl:t(`Flag_of_Eritrea_(1952-1961).svg`),label:`Federation flag`,note:`Adopted in 1952 when Eritrea became an autonomous federated unit of Ethiopia — a light-blue field echoing the UN, with a green olive wreath. It was abolished when Ethiopia annexed Eritrea in 1962.`}],DJ:[{fromYear:1977,toYear:null,flagUrl:`/Global/flags/dj.svg`,label:`Flag of Djibouti`,note:`Adopted at independence from France in 1977: light blue and green bands with a white triangle and red star. The colors are associated with the Issa and Afar communities, the star representing unity.`},{fromYear:1888,toYear:1977,flagUrl:`/Global/flags/fr.svg`,label:`French Somaliland / Afars and Issas`,note:`Djibouti was French Somaliland from 1888, renamed the French Territory of the Afars and Issas in 1967 — a strategically vital colony guarding the Red Sea entrance to the Suez route, flying the French tricolor. France held it longer than almost any other African territory, granting independence only in 1977.`}],SO:[{fromYear:1954,toYear:null,flagUrl:`/Global/flags/so.svg`,label:`Flag of Somalia`,note:`Designed by Mohammed Awale Liban and adopted in 1954 during the UN trusteeship, with a light-blue field honoring the UN and a white Star of Unity for the five regions inhabited by ethnic Somalis.`},{fromYear:1889,toYear:1960,flagUrl:`/Global/flags/it.svg`,label:`Italian Somaliland`,note:`The south was Italian Somaliland from 1889, flying the Italian flag (and briefly part of Mussolini's Italian East Africa). After WWII it returned to Italy as a UN trust territory, where the modern star flag was born in 1954. At independence in 1960 it united with the separate British Somaliland in the north to form Somalia — the two colonial legacies the white five-pointed Star of Unity was meant to bind together.`},{fromYear:1878,toYear:1925,flagUrl:t(`Majeerteen_sultanate_flag.jpg`),label:`Sultanate of Hobyo`,note:`A central Somali sultanate carved out by Yusuf Ali Kenadid, later an Italian protectorate.`},{fromYear:1750,toYear:1910,flagUrl:t(`Geledi_Sultanante_Flag.png`),label:`Sultanate of the Geledi`,note:`A southern Somali sultanate that dominated the trade of the Jubba and Shebelle river valleys.`},{fromYear:1750,toYear:1884,flagUrl:t(`Isaaq_Flag.svg`),label:`Isaaq Sultanate`,note:`A Somali sultanate in the northwest (modern Somaliland) before the British protectorate.`},{fromYear:1600,toYear:1927,flagUrl:t(`Majeerteen_sultanate_flag.jpg`),label:`Majeerteen Sultanate`,note:`A northeastern Somali sultanate (Migiurtinia) that controlled the Horn's coast until the Italians subdued it.`},{fromYear:1415,toYear:1577,flagUrl:t(`Flag_of_Adal_Sultanate.svg`),label:`Adal Sultanate`,note:`A Muslim sultanate of the Horn that, under Ahmad ibn Ibrahim, nearly conquered Christian Ethiopia in the 16th century.`},{fromYear:1100,toYear:1500,flagUrl:t(`Flag_of_Mogadishu.png`),label:`Sultanate of Mogadishu`,note:`A medieval Somali city-sultanate, one of the wealthiest trading ports on the Indian Ocean's Swahili coast.`}],NG:[{fromYear:1960,toYear:null,flagUrl:`/Global/flags/ng.svg`,label:`Flag of Nigeria`,note:`Adopted on independence day in 1960 from a design by 23-year-old student Michael Taiwo Akinkunmi. The green bands represent agriculture and natural wealth; the white center stands for peace and unity.`},{fromYear:1914,toYear:1960,flagUrl:t(`Flag_of_Nigeria_(1952–1960).svg`),label:`Colonial Nigeria`,note:`The British Colony and Protectorate of Nigeria flew a Blue Ensign defaced with a green six-pointed "Seal of Solomon" star around a red disc and crown, used as the government ensign until independence.`},{fromYear:1804,toYear:1903,flagUrl:t(`Flag_of_the_Sokoto_Caliphate.svg`),label:`Sokoto Caliphate`,note:`Across what is now northern Nigeria, the jihad of Usman dan Fodio founded the Sokoto Caliphate in 1804 — one of the largest and most populous states in 19th-century Africa, a federation of emirates flying green Islamic banners. Britain conquered it in 1903 but ruled through its emirs, so the caliphate's structures (and the north–south divide with the Christian-animist south) shaped Nigeria to this day.`},{fromYear:1967,toYear:1970,flagUrl:t(`Flag_of_Biafra.svg`),label:`Biafra`,note:`The secessionist Igbo republic whose bid for independence triggered the Nigerian Civil War and a devastating famine.`},{fromYear:1690,toYear:1902,flagUrl:t(`Flag_of_the_Aro_Confederacy.svg`),label:`Aro Confederacy`,note:`An Igbo trading and oracle confederacy that dominated southeastern Nigeria until the British 'Aro Expedition' broke it.`}],GH:[{fromYear:1966,toYear:null,flagUrl:`/Global/flags/gh.svg`,label:`Flag of Ghana (restored)`,note:`After the 1966 coup that ousted Nkrumah, the original 1957 red-gold-green flag was immediately reinstated. Designed by Theodosia Okoh, it was the first flag to use the black star, inspiring many later African flags.`},{fromYear:1964,toYear:1966,flagUrl:t(`Flag_of_Ghana_(1964–1966).svg`),label:`Nkrumah-era flag (white stripe)`,note:`After Ghana became a one-party state in 1964, the gold middle stripe was replaced with white to reflect the colors of Nkrumah's Convention People's Party. It lasted only until his 1966 overthrow.`},{fromYear:1957,toYear:1964,flagUrl:t(`Flag_of_Ghana.svg`),label:`Independence flag`,note:`Adopted at independence in 1957 — the first national flag to use the black star and the pan-African red-gold-green, borrowed from Marcus Garvey's Black Star Line as a symbol of African emancipation.`},{fromYear:1877,toYear:1957,flagUrl:t(`Flag_of_the_Gold_Coast_(1877–1957).svg`),label:`British Gold Coast`,note:`Britain ruled the territory as the Gold Coast — named for the gold its forts had traded alongside enslaved people for centuries — flying a Blue Ensign with an elephant-and-palm badge. To win it, Britain had to fight a series of wars against the powerful Ashanti Empire of the interior, whose Golden Stool symbolised the Asante nation. The Gold Coast became, in 1957, the first sub-Saharan African colony to win independence, as Ghana.`}],SN:[{fromYear:1960,toYear:null,flagUrl:`/Global/flags/sn.svg`,label:`Flag of Senegal`,note:`On full independence in 1960 after the Mali Federation broke up, Senegal kept the vertical green-yellow-red tricolour but replaced the central figure with a green five-pointed star for unity and hope.`},{fromYear:1959,toYear:1960,flagUrl:t(`Flag_of_Mali_(1959–1961).svg`),label:`Mali Federation`,note:`When Senegal united with French Sudan in 1959, it flew a green-yellow-red tricolour bearing a black kanaga — a human figure derived from Dogon culture and the Negritude movement.`},{fromYear:1958,toYear:1959,flagUrl:t(`Flag_of_Senegal_(1958–1959).svg`),label:`Autonomous Republic`,note:`As an autonomous republic within the French Community in 1958, Senegal used a green-yellow-red tricolour with a green star, close to its modern flag, before joining the Mali Federation.`},{fromYear:1549,toYear:1879,flagUrl:t(`Flag_Of_Cayor2.png`),label:`Cayor Kingdom`,note:`A powerful Wolof kingdom on the Senegalese coast that long resisted French expansion before falling in the 19th century.`}],ML:[{fromYear:1961,toYear:null,flagUrl:`/Global/flags/ml.svg`,label:`Flag of Mali`,note:`In 1961 the black human figure (kanaga) was removed — reportedly after objections from Islamic groups to depicting the human form — leaving a plain green-gold-red pan-African tricolour.`},{fromYear:1959,toYear:1961,flagUrl:t(`Flag_of_Mali_(1959–1961).svg`),label:`Mali Federation`,note:`Mali (as French Sudan) joined the Mali Federation in 1959 under a tricolour charged with a black kanaga, a stylized human figure with arms raised to the sky, kept briefly after independence.`},{fromYear:1880,toYear:1959,flagUrl:`/Global/flags/fr.svg`,label:`French Sudan`,note:`Modern Mali was the colony of French Sudan, the largest territory in French West Africa, flying the French flag. Its name deliberately recalled the medieval empires of Ghana, Mali and Songhai that once made this stretch of the Niger — and the fabled trading city of Timbuktu — a centre of gold, salt and Islamic scholarship under rulers like Mansa Musa.`},{fromYear:2012,toYear:2012,flagUrl:t(`MNLA_flag.svg`),label:`Azawad`,note:`The northern Mali homeland declared by Tuareg separatists (the MNLA) in 2012 before Islamist militias and the French intervened.`},{fromYear:1878,toYear:1898,flagUrl:t(`Possible_Flag_of_the_Wassoulou_Empire.svg`),label:`Wassoulou Empire`,note:`The empire of Samori Ture, which mounted one of the fiercest and longest armed resistances to French conquest in West Africa.`}],BF:[{fromYear:1984,toYear:null,flagUrl:`/Global/flags/bf.svg`,label:`Flag of Burkina Faso`,note:`In 1984 revolutionary leader Thomas Sankara renamed the country Burkina Faso ("Land of Upright People") and introduced this red-and-green flag with a central yellow star for revolution and the nation's riches.`},{fromYear:1959,toYear:1984,flagUrl:t(`Flag_of_Upper_Volta.svg`),label:`Upper Volta`,note:`The Republic of Upper Volta flew black-white-red stripes representing the three tributaries of the Volta River — the Black, White, and Red Volta — until the 1984 renaming.`}],NE:[{fromYear:1959,toYear:null,flagUrl:`/Global/flags/ne.svg`,label:`Flag of Niger`,note:`Adopted in 1959 shortly before independence, with a central orange disc for the sun. Green stands for hope and the river south, white for purity, and orange for the Sahara. It has never changed.`},{fromYear:1922,toYear:1959,flagUrl:`/Global/flags/fr.svg`,label:`French Niger`,note:`A vast, mostly Saharan colony within French West Africa, Niger flew the French tricolor. Conquest met fierce resistance well into the 20th century, and France invested little in the territory — leaving one of the world's poorest nations at the independence it reached in 1960 with its own sun-disc flag.`}],BJ:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/bj.svg`,label:`Flag of Benin (restored)`,note:`With the collapse of Marxism-Leninism, Benin restored its original 1959 Dahomey flag in 1990 — a rare case of a nation returning exactly to its pre-socialist flag without any redesign.`},{fromYear:1975,toYear:1990,flagUrl:t(`Flag_of_Benin_(1975–1990).svg`),label:`People's Republic of Benin`,note:`After a Marxist-Leninist coup the country was renamed Benin in 1975 and adopted a plain green field with a red star — green for agriculture and hope, the star for revolution.`},{fromYear:1959,toYear:1975,flagUrl:t(`Flag_of_Benin.svg`),label:`Republic of Dahomey`,note:`Adopted in 1959 by the autonomous Republic of Dahomey, with a green hoist band and yellow and red bands in the pan-African colors — identical to the flag restored in 1990.`},{fromYear:1600,toYear:1894,flagUrl:t(`Flag_of_Ghezo_of_Dahomey.svg`),label:`Kingdom of Dahomey`,note:`Benin takes the modern shape of the Kingdom of Dahomey, one of West Africa's most formidable powers — famed for its all-female warrior regiment, the "Dahomey Amazons," and for selling captives into the Atlantic slave trade from its coast, the "Slave Coast." Its kings flew banners bearing royal emblems until France conquered the kingdom in 1894 and made it the colony of French Dahomey.`}],TG:[{fromYear:1960,toYear:null,flagUrl:`/Global/flags/tg.svg`,label:`Flag of Togo`,note:`Adopted at independence in 1960 and designed by artist Paul Ahyi, with five green and yellow stripes (one per region) and a single white star on a red canton, reducing the earlier two stars to one to stress unity.`},{fromYear:1958,toYear:1960,flagUrl:t(`Flag_of_Togo_(1958–1960).svg`),label:`Pre-independence`,note:`Approaching independence, Togo removed the French tricolour from the canton, keeping a green field with two yellow stars on a white panel during the transition.`},{fromYear:1957,toYear:1958,flagUrl:t(`Flag_of_Togo_(1957–1958).svg`),label:`Autonomous Republic`,note:`As an autonomous republic within the French Union, Togo used a green field with the French tricolour in the canton and two yellow stars for its northern savannas and southern coast.`}],GN:[{fromYear:1958,toYear:null,flagUrl:`/Global/flags/gn.svg`,label:`Flag of Guinea`,note:`Adopted in 1958 after Guinea alone rejected the French Community and chose immediate independence under Sékou Touré. The red-yellow-green tricolour mirrors Ghana's pan-African colors and has never changed.`},{fromYear:1891,toYear:1958,flagUrl:`/Global/flags/fr.svg`,label:`French Guinea`,note:`A colony within French West Africa, French Guinea flew the French tricolor. In the 1958 referendum it became the only territory to vote "Non" to de Gaulle's French Community and chose immediate independence — to which an enraged France responded by stripping the country of everything it could, even ripping out telephone wires as it withdrew.`}],GW:[{fromYear:1973,toYear:null,flagUrl:`/Global/flags/gw.svg`,label:`Flag of Guinea-Bissau`,note:`Adopted at the 1973 declaration of independence from Portugal, nearly identical to the PAIGC liberation party's flag, with a red hoist band bearing a black star for African unity. It has never been changed.`},{fromYear:1474,toYear:1974,flagUrl:`/Global/flags/pt.svg`,label:`Portuguese Guinea`,note:`Held by Portugal for five centuries as Portuguese Guinea — long a hub of the transatlantic slave trade — under the Portuguese flag. Amílcar Cabral's PAIGC fought one of Africa's most effective liberation wars here, controlling much of the countryside and declaring independence in 1973, which Portugal recognised in 1974 after the Carnation Revolution.`}],FJ:[{fromYear:1970,toYear:null,flagUrl:`/Global/flags/fj.svg`,label:`Flag of Fiji`,note:`Adopted at independence in 1970, the colonial dark blue was lightened to a sky blue for the Pacific Ocean, keeping the shield and the Union Jack. Fiji formally proposed removing the Union Jack in 2005 and 2015, but both efforts were abandoned.`},{fromYear:1924,toYear:1970,flagUrl:t(`Flag_of_Fiji_(1924–1970).svg`),label:`Colonial Blue Ensign (no disc)`,note:`The white disc behind the badge was dropped in 1924, leaving the colonial arms directly on the dark blue ensign — Fiji's flag right up to independence.`},{fromYear:1908,toYear:1924,flagUrl:t(`Flag_of_Fiji_(1908–1924).svg`),label:`Colonial Blue Ensign (with disc)`,note:`A British Blue Ensign defaced with Fiji's colonial coat of arms, granted in 1908, set on a white disc.`},{fromYear:1871,toYear:1874,flagUrl:t(`Flag_of_the_Kingdom_of_Fiji_(1871-1874).svg`),label:`Kingdom of Fiji`,note:`Before Britain took over, the warrior chief Seru Epenisa Cakobau united much of the islands as the Kingdom of Fiji in 1871, flying a pale blue flag with a shield, a crown and a white dove of peace. Crippled by debt and unrest, Cakobau ceded Fiji to Britain in 1874 — the dove-and-shield motif lived on in the colonial and modern arms.`}],PG:[{fromYear:1971,toYear:null,flagUrl:`/Global/flags/pg.svg`,label:`Flag of Papua New Guinea`,note:`Designed by 15-year-old schoolgirl Susan Karike and adopted in 1971, it shows a yellow Raggiana bird of paradise and the white stars of the Southern Cross on a diagonally split red-and-black field. It has never changed.`},{fromYear:1970,toYear:1971,flagUrl:t(`Flag_of_Papua_New_Guinea_(1970–1971).svg`),label:`Territory tricolour`,note:`A blue-white-green vertical design with stars and a bird of paradise, used briefly for the Territory of Papua and New Guinea before being rejected as too "colonial".`},{fromYear:1906,toYear:1949,flagUrl:t(`Flag_of_the_Territory_of_Papua.svg`),label:`Australian Territory of Papua`,note:`Australia took over the southern half — the Territory of Papua — in 1906, flying a British blue ensign defaced with a bird-of-paradise badge, while the German-then-Australian north was administered separately. The two halves were merged into a single Territory of Papua and New Guinea in 1949 (thereafter under the Australian flag) on the road to the unified independence of 1975.`}],SB:[{fromYear:1977,toYear:null,flagUrl:`/Global/flags/sb.svg`,label:`Flag of the Solomon Islands`,note:`Adopted just before independence in 1977: a yellow diagonal stripe separates a blue triangle (sea and sky) from a green one (land), with five white stars for the island groups. One flag, never changed.`},{fromYear:1966,toYear:1977,flagUrl:t(`Flag_of_the_Solomon_Islands_(1966–1977).svg`),label:`Protectorate Blue Ensign`,note:`The final colonial ensign of the British Solomon Islands Protectorate, bearing the protectorate badge.`}],VU:[{fromYear:1980,toYear:null,flagUrl:`/Global/flags/vu.svg`,label:`Flag of Vanuatu`,note:`Adopted at independence in 1980 in the colors of the Vanua'aku Pati, with a black "Y" shape, a boar's tusk, and namele fern leaves. One flag, never changed.`},{fromYear:1953,toYear:1980,flagUrl:t(`Flag_of_the_British_New_Hebrides_(1952–1980).svg`),label:`British New Hebrides`,note:`Under the unusual Anglo-French Condominium, Britain and France each flew their own emblems; this is the British New Hebrides badge flag used until independence.`}],WS:[{fromYear:1949,toYear:null,flagUrl:`/Global/flags/ws.svg`,label:`Flag of Samoa`,note:`In 1949 a fifth, smaller star was added to complete the Southern Cross on the red field. The design was kept after independence in 1962 and has remained unchanged.`},{fromYear:1948,toYear:1949,flagUrl:t(`Flag_of_Samoa_(1948-1949).svg`),label:`Four-star flag`,note:`Introduced in 1948, the first version of the red flag carried only four white stars of the Southern Cross in the blue canton.`},{fromYear:1925,toYear:1948,flagUrl:t(`Flag_of_the_Samoa_Trust_Territory.svg`),label:`NZ Trust Territory`,note:`Under New Zealand administration, a defaced British ensign with three palm trees in a white disc was used until the modern red flag was introduced.`},{fromYear:1900,toYear:1914,flagUrl:t(`Flag_of_German_Samoa.svg`),label:`German Samoa`,note:`Samoa was a German colony from 1900; German colonial ensigns were used until New Zealand forces occupied the islands in 1914.`}],TO:[{fromYear:1866,toYear:null,flagUrl:`/Global/flags/to.svg`,label:`Flag of Tonga`,note:`The red flag with a white canton bearing a red couped cross was introduced in 1866 and entrenched in the 1875 constitution, which forbids it from ever being altered — one of the world's oldest unchanged flags.`},{fromYear:1862,toYear:1866,flagUrl:t(`Flag_of_Tonga_(1862-1866).svg`),label:`First flag of Tonga`,note:`Tonga's first national flag, approved by King George Tupou I around 1862, was white bearing a red cross. It was changed because it too closely resembled the Red Cross emblem then coming into international use.`}],KI:[{fromYear:1979,toYear:null,flagUrl:`/Global/flags/ki.svg`,label:`Flag of Kiribati`,note:`Adopted at independence in 1979, the golden frigatebird flying over a rising sun and three white waves is based directly on the colonial coat of arms granted to the Gilbert and Ellice Islands in 1937.`},{fromYear:1937,toYear:1979,flagUrl:t(`Flag_of_Gilbert_and_Ellice_Islands.svg`),label:`Gilbert and Ellice Islands Colony`,note:`Before independence the Gilberts (now Kiribati) and the Ellice Islands (now Tuvalu) were one British colony, flying the Blue Ensign with the colonial badge — the frigatebird, rising sun and waves granted in 1937. That badge became the basis for Kiribati's national flag when the colony split and the Gilberts gained independence in 1979.`}],MH:[{fromYear:1979,toYear:null,flagUrl:`/Global/flags/mh.svg`,label:`Flag of the Marshall Islands`,note:`Hoisted in 1979 when the territory became self-governing: two diverging orange and white rays and a 24-point white star on deep blue, representing the nation's location near the equator.`},{fromYear:1962,toYear:1979,flagUrl:t(`Flag_of_the_Trust_Territory_of_the_Pacific_Islands.svg`),label:`Trust Territory of the Pacific Islands`,note:`A light-blue flag with six white stars in a circle, one for each district of the US-administered Trust Territory, flown until the Marshalls adopted their own flag.`},{fromYear:1914,toYear:1944,flagUrl:`/Global/flags/jp.svg`,label:`Japanese South Seas Mandate`,note:`Germany claimed the Marshalls in 1885, but in 1914 Japan seized them and governed Micronesia as the South Seas Mandate (Nan'yō) under the Japanese flag for three decades — settling colonists, building infrastructure, and fortifying the atolls. American forces took them in fierce WWII battles like Kwajalein, after which they passed to US trusteeship.`}],FM:[{fromYear:1978,toYear:null,flagUrl:`/Global/flags/fm.svg`,label:`Flag of the Federated States of Micronesia`,note:`Adopted in 1978, it keeps the light-blue field of the Trust Territory flag but reduces the stars from six to four — one for each FSM state: Yap, Chuuk, Pohnpei, and Kosrae.`},{fromYear:1962,toYear:1978,flagUrl:t(`Flag_of_the_Trust_Territory_of_the_Pacific_Islands.svg`),label:`Trust Territory of the Pacific Islands`,note:`The light-blue flag bearing six white stars for the six districts of the US-administered Trust Territory, from which the current FSM flag was directly derived.`},{fromYear:1914,toYear:1944,flagUrl:`/Global/flags/jp.svg`,label:`Japanese South Seas Mandate`,note:`After German rule (1885–1914), Japan administered these Caroline Islands as part of the South Seas Mandate under its own flag for thirty years, making them among the most heavily settled and developed parts of Japanese Micronesia. They became a US trust territory after the Pacific War.`}],NR:[{fromYear:1968,toYear:null,flagUrl:`/Global/flags/nr.svg`,label:`Flag of Nauru`,note:`Adopted on independence day in 1968: a blue field with a gold stripe for the equator and a white 12-pointed star below it, depicting Nauru's position just south of the equator. The twelve points represent the island's original tribes.`},{fromYear:1920,toYear:1968,flagUrl:`/Global/flags/au.svg`,label:`Australian-administered mandate`,note:`A German protectorate from 1888 and then briefly under Japanese wartime occupation, Nauru was for most of the 20th century a League of Nations (later UN) mandate administered by Australia, which flew its own flag while strip-mining the island's rich phosphate. Nauru never had a flag of its own until independence in 1968, won partly to gain control of that phosphate wealth.`}],PW:[{fromYear:1981,toYear:null,flagUrl:`/Global/flags/pw.svg`,label:`Flag of Palau`,note:`Adopted in 1981 when Palau became self-governing: a golden-yellow full moon slightly off-center on a sky-blue field, the moon symbolizing peace and national unity.`},{fromYear:1962,toYear:1981,flagUrl:t(`Flag_of_the_Trust_Territory_of_the_Pacific_Islands.svg`),label:`Trust Territory of the Pacific Islands`,note:`The six-star light-blue flag of the US-administered Trust Territory, which flew over Palau before it adopted its own moon flag.`},{fromYear:1914,toYear:1944,flagUrl:`/Global/flags/jp.svg`,label:`Japanese South Seas Mandate`,note:`Koror in Palau was the capital of Japan's entire South Seas Mandate, the administrative heart of Japanese Micronesia from 1914 to 1944, flying the Japanese flag. Japanese settlers came to outnumber Palauans, and the islands saw one of the Pacific War's bloodiest battles at Peleliu before passing to US trusteeship.`}],TV:[{fromYear:1997,toYear:null,flagUrl:`/Global/flags/tv.svg`,label:`Flag of Tuvalu (restored)`,note:`In 1997 Tuvalu reverted to its original 1978 design — a light-blue ensign with the Union Jack and nine yellow stars mapping the geographic positions of the nine islands.`},{fromYear:1996,toYear:1997,flagUrl:t(`Flag_of_Tuvalu_(1996–1997).svg`),label:`1996 republican variant`,note:`Following a 1995 push to end the monarchy, a new flag introduced in 1996 removed the Union Jack in favor of the national coat of arms on a red field. It proved unpopular and short-lived.`},{fromYear:1978,toYear:1995,flagUrl:t(`Flag_of_Tuvalu_(1978–1995).svg`),label:`Independence flag`,note:`Adopted at independence in 1978, the original light-blue ensign with the Union Jack and nine stars — the same design restored in 1997.`},{fromYear:1937,toYear:1976,flagUrl:t(`Flag_of_Gilbert_and_Ellice_Islands.svg`),label:`Gilbert and Ellice Islands Colony`,note:`The Ellice Islands (now Tuvalu) were governed with the Gilberts (now Kiribati) as a single British colony, flying the Blue Ensign with the 1937 colonial badge of a frigatebird over a rising sun. The Ellice Islanders voted to separate in 1975, and Tuvalu became independent in 1978.`}],ID:[{fromYear:1945,toYear:null,flagUrl:`/Global/flags/id.svg`,label:`Sang Saka Merah Putih`,note:`A simple red-over-white bicolour whose colors trace back to the 13th-century Majapahit Empire. Banned by the Dutch, it was raised on independence day in 1945. It is nearly identical to Monaco's flag but with a 2:3 ratio.`},{fromYear:1816,toYear:1945,flagUrl:`/Global/flags/nl.svg`,label:`Dutch East Indies`,note:`For over a century the islands were governed as the Dutch East Indies under the red-white-blue flag of the Netherlands — the colonial empire built on spices, sugar, coffee and rubber. The red-and-white nationalist flag was banned throughout this period; raising it was an act of defiance, which is exactly what the independence leaders did in 1945 as Dutch rule collapsed after the Japanese occupation.`},{fromYear:1605,toYear:1669,flagUrl:t(`Flag_of_the_Sultanate_of_Gowa.svg`),label:`Sultanate of Gowa`,note:`Gowa was a powerful Makassar seafaring kingdom in southern Sulawesi that dominated the eastern Indonesian spice trade. After a long war, the Dutch East India Company and allied Bugis forces defeated Gowa at the 1669 Treaty of Bongaya, breaking its commercial power.`},{fromYear:1081,toYear:1950,flagUrl:t(`Flag_of_the_Sultanate_of_Tidore.png`),label:`Sultanate of Tidore`,note:`Tidore was a Moluccan spice kingdom and the great rival of neighbouring Ternate, controlling cloves and nutmeg coveted across the world. It long resisted European domination, allying variously with the Spanish and Portuguese against the Dutch, before being absorbed into the Dutch East Indies.`},{fromYear:1948,toYear:1950,flagUrl:t(`Flag_of_Pasundan.svg`),label:`State of Pasundan`,note:`A Dutch-created federal state in West Java (Sundanese lands), folded into the Republic of Indonesia.`},{fromYear:1947,toYear:1950,flagUrl:t(`Flag_of_East_Sumatra.svg`),label:`State of East Sumatra`,note:`A Dutch-sponsored federal state created to weaken the Indonesian Republic, dissolved into the unitary republic.`},{fromYear:1777,toYear:1884,flagUrl:t(`Lanfang_Republic_Reconstructed_Flag.svg`),label:`Lanfang Republic`,note:`A remarkable self-governing republic of Chinese gold miners in West Borneo, often called one of Asia's first republics.`},{fromYear:1771,toYear:1950,flagUrl:t(`Flag_of_Pontianak_Sultanate.svg`),label:`Pontianak Sultanate`,note:`A sultanate at the mouth of the Kapuas in West Borneo, founded by an Arab sayyid dynasty.`},{fromYear:1659,toYear:1823,flagUrl:t(`Old_Flag_of_Sultanate_of_Palembang.png`),label:`Palembang Sultanate`,note:`A wealthy Sumatran sultanate, heir to the ancient Srivijaya empire, abolished by the Dutch.`},{fromYear:1587,toYear:1755,flagUrl:t(`Flag_of_the_Mataram_Sultanate.svg`),label:`Sultanate of Mataram`,note:`The last great independent Javanese kingdom, which the Dutch broke up into the courts of Yogyakarta and Surakarta.`},{fromYear:1526,toYear:1860,flagUrl:t(`Banjar_Sultanate_Flag.svg`),label:`Sultanate of Banjar`,note:`A sultanate of southern Borneo (Kalimantan), rich in pepper and diamonds, abolished by the Dutch after a long war.`},{fromYear:1460,toYear:1906,flagUrl:t(`White_flag_3_to_2.svg`),label:`Jambi Sultanate`,note:`A Sumatran sultanate on the Jambi River, a pepper-trading power before the Dutch deposed its sultan.`},{fromYear:1948,toYear:1950,flagUrl:t(`Flag_of_Various_Autonomous_Indonesian_States.svg`),label:`State of East Java`,note:`A Dutch-engineered federal state, one of several meant to dilute the Indonesian Republic before they all merged into it.`},{fromYear:1948,toYear:1950,flagUrl:t(`Flag_of_Various_Autonomous_Indonesian_States.svg`),label:`State of Madura`,note:`A short-lived Dutch-sponsored federal state on the island of Madura, absorbed into unitary Indonesia.`},{fromYear:1731,toYear:1959,flagUrl:t(`Flag_of_the_Bulungan_Sultanate.svg`),label:`Sultanate of Bulungan`,note:`A sultanate of northeastern Borneo, dissolved into the Indonesian republic.`},{fromYear:1723,toYear:1945,flagUrl:t(`Flag_of_Sultanate_of_Siak_Sri_Indrapura.svg`),label:`Sultanate of Siak Sri Indrapura`,note:`A Malay sultanate of eastern Sumatra whose sultan was among the first to back the new Indonesian Republic.`},{fromYear:1723,toYear:1946,flagUrl:t(`Sultanate_of_Serdang_Flag.jpg`),label:`Sultanate of Serdang`,note:`A Malay sultanate of Sumatra's east coast, swept away in the 1946 social revolution.`},{fromYear:1631,toYear:1950,flagUrl:t(`Royal_Malay_Banner_(Yellow).svg`),label:`Sambas Sultanate`,note:`A sultanate of West Borneo (Kalimantan), long a centre of gold mining and Malay culture.`},{fromYear:1568,toYear:1948,flagUrl:t(`Flag_of_Sultanate_of_Langkat.svg`),label:`Sultanate of Langkat`,note:`A Malay sultanate of northeast Sumatra that grew rich on tobacco and then oil, abolished in Indonesia's social revolution.`}],MY:[{fromYear:1963,toYear:null,flagUrl:`/Global/flags/my.svg`,label:`Jalur Gemilang`,note:`When Sabah, Sarawak, and Singapore joined in 1963, the stripes and star points increased from 11 to 14. The design was unchanged when Singapore left in 1965 — the 14th element was simply reinterpreted as the federal territories.`},{fromYear:1950,toYear:1963,flagUrl:t(`Flag_of_Malaya_(1950–1963).svg`),label:`Federation of Malaya`,note:`Designed by Mohamad Hamzah and approved in 1950, it had 11 red-and-white stripes and an 11-pointed star for the 11 members of the Federation of Malaya.`},{fromYear:1470,toYear:1623,flagUrl:t(`Flag_of_Pahang_(1853_-_1887).svg`),label:`Pahang Kingdom`,note:`The old Pahang Sultanate of the Malay Peninsula, a vassal of Malacca and Johor, ancestor of the modern Malaysian state of Pahang.`}],SG:[{fromYear:1959,toYear:null,flagUrl:`/Global/flags/sg.svg`,label:`Flag of Singapore`,note:`Unveiled in 1959 when Singapore became self-governing. The crescent represents a young rising nation; the five stars stand for democracy, peace, progress, justice, and equality. It was kept through merger with Malaysia and full independence.`},{fromYear:1952,toYear:1959,flagUrl:t(`Flag_of_Singapore_(1952–1959).svg`),label:`Colony of Singapore ensign`,note:`A revised colonial Blue Ensign with the Singapore badge, used in the final years before self-government.`},{fromYear:1946,toYear:1952,flagUrl:t(`Flag_of_Singapore_(1946–1952).svg`),label:`Crown Colony ensign`,note:`After the Straits Settlements were dissolved in 1946, Singapore became a separate Crown Colony and flew a Blue Ensign with a badge reduced from three crowns to one.`}],BN:[{fromYear:1959,toYear:null,flagUrl:`/Global/flags/bn.svg`,label:`Flag of Brunei`,note:`With the 1959 constitution, the red national crest — a crescent, parasol, wings, and hands with a Jawi motto — was added over the striped yellow field.`},{fromYear:1906,toYear:1959,flagUrl:t(`Flag_of_Brunei_1906-1959.svg`),label:`Yellow with diagonal stripes`,note:`The plain yellow flag (the Sultan's color) gained white and black diagonal stripes in 1906 to honor the two chief ministers, commemorating that year's treaty with Britain.`},{fromYear:1368,toYear:1888,flagUrl:t(`Old_Flag_of_Brunei.svg`),label:`Bruneian Empire`,note:`The maritime empire of the Sultanate of Brunei, which at its height controlled the coasts of Borneo and the southern Philippines, before shrinking under European pressure to a British protectorate.`}],PH:[{fromYear:1998,toYear:null,flagUrl:`/Global/flags/ph.svg`,label:`Flag of the Philippines`,note:`The 1998 Flag and Heraldic Code fixed the blue as "Royal Blue." The eight sun rays represent the first eight provinces to revolt in 1896; three stars stand for Luzon, Visayas, and Mindanao.`,parallelCaption:`Flown red-up in wartime`,parallel:[{fromYear:1899,toYear:null,flagUrl:t(`War_Flag_of_the_Philippines.svg`),label:`War flag (red stripe up)`,note:`The Philippine flag is the only national flag deliberately designed to be flown inverted — red stripe on top — to signify a state of war, first done in 1899 at the start of the Philippine-American War.`}]},{fromYear:1985,toYear:1986,flagUrl:t(`Flag_of_the_Philippines_(1985–1986).svg`),label:`Marcos light-blue flag`,note:`In 1985 President Marcos changed the blue from navy to a lighter sky blue, believing the earliest republican flags had been light blue. It was reverted after the 1986 EDSA Revolution.`},{fromYear:1943,toYear:1945,flagUrl:t(`Flag_of_the_Philippines_(1943–1945).svg`),label:`Second Republic (Japanese-sponsored)`,note:`The Japanese-backed republic under José P. Laurel adopted a flag with a faceless sun in 1943, lasting until the republic's dissolution in 1945.`},{fromYear:1936,toYear:1985,flagUrl:t(`Flag_of_the_Philippines_(1936–1985,_1986–1998).svg`),label:`Standardized flag (faceless sun)`,note:`A 1936 order under President Quezon set exact specifications and formally removed the mythical face from the sun. This long-lived design also returned from 1986 to 1998.`},{fromYear:1919,toYear:1936,flagUrl:t(`Flag_of_the_Philippines_(1919–1936).svg`),label:`Revived flag (faced sun)`,note:`Display of the flag was banned under US rule from 1907; when the ban lifted in 1919 the revived flag used a darker navy blue and still retained the mythical sun face.`},{fromYear:1898,toYear:1901,flagUrl:t(`Flag_of_the_Philippines_(1898–1901).svg`),label:`Original revolutionary flag`,note:`First unfurled in 1898, the golden sun bore a human-like mythical face echoing the Spanish-colonial "Sun of May" tradition. This was the flag of the First Philippine Republic.`},{fromYear:1902,toYear:1906,flagUrl:t(`Battle_Flag_of_Tagalog_Republic.svg`),label:`Tagalog Republic`,note:`A peasant rebel republic that fought on against American rule after the official end of the Philippine–American War.`},{fromYear:1898,toYear:1901,flagUrl:t(`Flag_of_the_Negros_Republic.svg`),label:`Republic of Negros`,note:`A short-lived republic on the sugar island of Negros that broke from Spain and was then absorbed by the United States.`},{fromYear:1520,toYear:1888,flagUrl:t(`Flag_of_Maguindanao.svg`),label:`Sultanate of Maguindanao`,note:`A powerful Muslim sultanate in Mindanao that long resisted Spanish conquest of the southern Philippines.`}],TL:[{fromYear:2002,toYear:null,flagUrl:`/Global/flags/tl.svg`,label:`Flag of Timor-Leste`,note:`Re-adopted in 2002 at the restoration of independence, identical to the 1975 design. Yellow symbolizes the colonial past, black the obscurantism to be overcome, red the liberation struggle, and the white star peace.`},{fromYear:1976,toYear:1999,flagUrl:`/Global/flags/id.svg`,label:`Indonesian occupation (Timor Timur)`,note:`Nine days after FRETILIN declared independence, Indonesia invaded and in 1976 annexed the territory as its 27th province, Timor Timur, flying the Indonesian red-and-white flag. The brutal 24-year occupation cost an estimated 100,000–180,000 lives before a 1999 UN-supervised referendum voted overwhelmingly for independence.`},{fromYear:1975,toYear:1975,flagUrl:t(`Flag_of_East_Timor.svg`),label:`FRETILIN independence flag`,note:`Raised in November 1975 when FRETILIN declared independence from Portugal, it flew only days before the Indonesian invasion. The Indonesian flag was then used until 1999, and the UN flag during the transition to restored independence.`},{fromYear:1702,toYear:1975,flagUrl:`/Global/flags/pt.svg`,label:`Portuguese Timor`,note:`The eastern half of Timor was a Portuguese colony for nearly three centuries, flying the flag of Portugal — the only part of Southeast Asia colonised by Portugal rather than the Dutch, British, French or Spanish. It was this long Lusophone heritage (and the Catholic faith) that set East Timor apart from Indonesia when Portugal abruptly withdrew in 1975.`}],AM:[{fromYear:1990,toYear:null,flagUrl:`/Global/flags/am.svg`,label:`Republic of Armenia`,note:`The red-blue-orange (apricot) tricolour of the 1918 First Republic was readopted in 1990, before formal independence. The orange band symbolizes the Armenian people's creative talent and hard work.`},{fromYear:1952,toYear:1990,flagUrl:t(`Flag_of_the_Armenian_Soviet_Socialist_Republic_(1952–1990).svg`),label:`Armenian SSR`,note:`A red flag with a horizontal pale-blue stripe across the middle, one of the more visually distinctive Soviet republic flags.`},{fromYear:1918,toYear:1920,flagUrl:t(`Flag_of_Armenia_(1918–1922).svg`),label:`First Republic of Armenia`,note:`The short-lived First Republic adopted this tricolour in 1918 — the exact design restored as the modern flag, making it the direct ancestor of today's banner.`},{fromYear:1198,toYear:1375,flagUrl:t(`Flag_of_the_Rubenid_Dynasty.svg`),label:`Armenian Kingdom of Cilicia`,note:`After the Seljuk conquest of the Armenian heartland, Armenians who had fled to the Mediterranean coast founded the Armenian Kingdom of Cilicia (1198–1375), flying the red lion banner of the ruling Rubenid dynasty. A close ally of the Crusader states, it was the last independent Armenian kingdom for six centuries — until the 1918 republic — and a cherished symbol of Armenian statehood.`}],AZ:[{fromYear:1991,toYear:null,flagUrl:`/Global/flags/az.svg`,label:`Republic of Azerbaijan`,note:`On regaining independence, Azerbaijan restored the 1918 tricolour of turquoise, red, and green with a white crescent and eight-pointed star. The blue honors Turkic heritage, red modernity, green Islam.`},{fromYear:1952,toYear:1991,flagUrl:t(`Flag_of_the_Azerbaijan_Soviet_Socialist_Republic.svg`),label:`Azerbaijan SSR`,note:`The final Soviet-era design added a blue horizontal band along the bottom of the red flag, evoking the Caspian Sea.`},{fromYear:1918,toYear:1920,flagUrl:t(`Flag_of_Azerbaijan_(1918–1920).svg`),label:`Azerbaijan Democratic Republic`,note:`The first democratic, parliamentary republic in the Muslim world adopted this turquoise-red-green tricolour in 1918 — revived almost unchanged after 1991.`}],GE:[{fromYear:2004,toYear:null,flagUrl:`/Global/flags/ge.svg`,label:`Five-Cross Flag`,note:`Adopted in 2004 after the Rose Revolution, the white flag bears a central red St. George's cross and four smaller Bolnisi crosses, reviving a banner of the medieval Kingdom of Georgia.`},{fromYear:1990,toYear:2004,flagUrl:t(`Flag_of_Georgia_(1990–2004).svg`),label:`Restored 1918 republic flag`,note:`In 1990 Georgia readopted the wine-red flag of the 1918–21 Democratic Republic — designed by painter Iakob Nikoladze — which served through the Rose Revolution.`},{fromYear:1951,toYear:1990,flagUrl:t(`Flag_of_the_Georgian_Soviet_Socialist_Republic_(1951–1990).svg`),label:`Georgian SSR`,note:`Distinctive among Soviet republic flags: a red field with a blue canton containing a hammer, sickle, and star inside a radiant blue sun.`}],KZ:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/kz.svg`,label:`Republic of Kazakhstan`,note:`Adopted in 1992, the sky-blue flag bears a golden sun with 32 rays above a soaring steppe eagle, with a national ornamental pattern down the hoist. Blue symbolizes the Turkic sky and unity.`},{fromYear:1953,toYear:1992,flagUrl:t(`Flag_of_the_Kazakh_Soviet_Socialist_Republic.svg`),label:`Kazakh SSR`,note:`A red flag with a light-blue band along the bottom, which continued in use until the new national flag was adopted after independence.`},{fromYear:1917,toYear:1920,flagUrl:t(`Flag_of_Alash_Autonomy.svg`),label:`Alash Autonomy`,note:`In the chaos of the Russian Revolution, Kazakh intellectuals proclaimed the Alash Autonomy (1917–1920) — the first modern Kazakh state — under a red flag with a yellow crescent and star. The Bolsheviks crushed it and later executed most of its leaders, but the Alash movement is now honoured as the founding moment of modern Kazakh nationhood.`}],KG:[{fromYear:2023,toYear:null,flagUrl:`/Global/flags/kg.svg`,label:`Flag of Kyrgyzstan`,note:`A 2023 redesign straightened the sun's previously wavy rays, which lawmakers argued resembled a sunflower — culturally associated with servility. The sun has 40 rays for the 40 Kyrgyz tribes.`},{fromYear:1992,toYear:2023,flagUrl:t(`Flag_of_Kyrgyzstan_(1992–2023).svg`),label:`Original sun flag`,note:`Adopted in 1992, a red field with a yellow 40-ray sun bearing a stylized "tunduk" — the crown of a traditional yurt — at its center.`},{fromYear:1952,toYear:1991,flagUrl:t(`Flag_of_the_Kirghiz_Soviet_Socialist_Republic_(1952–1991);_Flag_of_Kyrgyzstan_(1991–1992).svg`),label:`Kirghiz SSR`,note:`A red flag with a central blue-white-blue stripe set, which remained the flag of newly independent Kyrgyzstan until 1992.`}],TJ:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/tj.svg`,label:`Republic of Tajikistan`,note:`Adopted in 1992, a red-white-green tricolour with a central gold crown beneath an arc of seven stars. It has one of the widest middle stripes of any national flag.`},{fromYear:1953,toYear:1992,flagUrl:t(`Flag_of_the_Tajik_Soviet_Socialist_Republic.svg`),label:`Tajik SSR`,note:`A red flag with central white and green horizontal stripes, which remained in use after the 1991 independence declaration until the new flag of 1992.`},{fromYear:1785,toYear:1920,flagUrl:t(`Flag_of_Emirate_of_Bukhara-Buxoro_Amirligi_Bayrog'i.svg`),label:`Emirate of Bukhara`,note:`The Tajik lands were the eastern half of the Emirate of Bukhara, the last great Persian-speaking Muslim state of Central Asia. Tajiks look back further still to the Samanid Empire (9th–10th centuries), centred on Bukhara and Samarkand — the golden age of Persian-Tajik culture, honoured today in the name of Tajikistan's currency, the somoni.`}],TM:[{fromYear:2001,toYear:null,flagUrl:`/Global/flags/tm.svg`,label:`Flag of Turkmenistan`,note:`Finalized in 2001, this green flag with a vertical red carpet-stripe of five tribal "guls," a crescent, five stars, and olive branches is among the most detailed national flags in the world.`},{fromYear:1997,toYear:2001,flagUrl:t(`Flag_of_Turkmenistan_(1997-2001).svg`),label:`Olive-branch version`,note:`Amended in 1997 to add two crossed olive branches beneath the carpet guls, marking the UN's recognition of Turkmenistan's permanent neutrality.`},{fromYear:1992,toYear:1997,flagUrl:t(`Flag_of_Turkmenistan_(1992–1997).svg`),label:`First independent flag`,note:`Introduced in 1992: a green field with a vertical red-maroon carpet stripe bearing five tribal guls, plus a white crescent and five stars, but no olive branches yet.`},{fromYear:1953,toYear:1973,flagUrl:t(`Flag_of_the_Turkmen_Soviet_Socialist_Republic_(1953–1973).svg`),label:`Turkmen SSR (carpet stripe)`,note:`A red flag with two light-blue stripes and a band of Turkmen carpet ornamentation — a Soviet nod to the republic's famous carpet industry, foreshadowing the modern flag.`}],UZ:[{fromYear:1991,toYear:null,flagUrl:`/Global/flags/uz.svg`,label:`Republic of Uzbekistan`,note:`Adopted in 1991, the first ex-Soviet Central Asian republic to introduce a new national flag. It bears blue, white, and green stripes with red fimbriations, a white crescent, and twelve stars.`},{fromYear:1952,toYear:1991,flagUrl:t(`Flag_of_the_Uzbek_Soviet_Socialist_Republic_(1952–1991).svg`),label:`Uzbek SSR`,note:`The final Soviet-era design: a red flag with a central light-blue band edged by thin white stripes, plus the hammer, sickle, and star in the canton.`},{fromYear:1785,toYear:1920,flagUrl:t(`Flag_of_Emirate_of_Bukhara-Buxoro_Amirligi_Bayrog'i.svg`),label:`Emirate of Bukhara`,note:`Before the Soviets, the great oasis cities of Uzbekistan were ruled by the Emirate of Bukhara — heir to the empire of Timur (Tamerlane), whose capital Samarkand was one of the jewels of the Islamic world. The emirate flew a green flag and survived as a Russian protectorate until the Red Army stormed Bukhara in 1920, ending a line of Central Asian Muslim states stretching back centuries.`},{fromYear:1920,toYear:1925,flagUrl:t(`Flag_of_the_Bukharan_People's_Soviet_Republic.svg`),label:`Bukharan People's Soviet Republic`,note:`The Soviet client state that replaced the Emirate of Bukhara before being carved into the Central Asian SSRs.`},{fromYear:1920,toYear:1925,flagUrl:t(`Flag_of_Khiva_1920-1923.svg`),label:`Khorezm People's Soviet Republic`,note:`The Soviet successor to the Khanate of Khiva, dissolved into the new Uzbek and Turkmen republics.`},{fromYear:1917,toYear:1918,flagUrl:t(`Flag_of_the_Turkestan_(Kokand)_Autonomy.svg`),label:`Turkestan Autonomy`,note:`A short-lived Muslim autonomous government at Kokand, crushed by the Bolsheviks within months — a founding memory of Central Asian nationalism.`},{fromYear:1709,toYear:1876,flagUrl:t(`Banner_of_the_Kokand_Khans.svg`),label:`Khanate of Kokand`,note:`A khanate of the fertile Fergana Valley, the last Central Asian state conquered by the Russian Empire.`},{fromYear:1511,toYear:1920,flagUrl:t(`Flag_of_the_Khanate_of_Khiva.svg`),label:`Khanate of Khiva`,note:`A Central Asian khanate of the Khorezm oasis, a slave-trading power on the Amu Darya until the Red Army took it.`}],AF:[{fromYear:2021,toYear:null,flagUrl:`/Global/flags/af.svg`,label:`Islamic Emirate (Taliban)`,note:`Re-adopted at the Taliban's August 2021 takeover: a white field bearing the black Shahada, the Islamic declaration of faith. Afghanistan has changed its flag more often than almost any nation on Earth.`},{fromYear:2004,toYear:2021,flagUrl:t(`Flag_of_Afghanistan_(2004–2021).svg`),label:`Islamic Republic of Afghanistan`,note:`The black-red-green vertical tricolour with a white mosque emblem. It still represents Afghanistan at the UN and Olympics despite the 2021 government collapse.`},{fromYear:1992,toYear:2001,flagUrl:t(`Flag_of_Afghanistan_(1992–2001).svg`),label:`Islamic State (mujahideen)`,note:`After the mujahideen took Kabul, this green-white-black tricolour became the flag of the internationally recognized Islamic State, flown by the Northern Alliance through the Taliban years.`,parallelCaption:`Taliban-controlled areas (1996–2001)`,parallel:[{fromYear:1996,toYear:2001,flagUrl:t(`Flag_of_the_Taliban.svg`),label:`Taliban white flag`,note:`The first Taliban regime flew a plain white banner — later adding the black Shahada — controlling most of the country at the same time the recognized Islamic State flag flew over the north.`}]},{fromYear:1987,toYear:1992,flagUrl:t(`Flag_of_Afghanistan_(1987–1992).svg`),label:`Republic (Najibullah era)`,note:`Under Najibullah's "national reconciliation," the word "Democratic" was dropped and the emblem revised, softening the overt communist iconography.`},{fromYear:1980,toYear:1987,flagUrl:t(`Flag_of_Afghanistan_(1980–1987).svg`),label:`Democratic Republic (DRA)`,note:`Following the Soviet intervention, the DRA restored the black-red-green tricolour with a new socialist emblem to broaden domestic appeal.`},{fromYear:1978,toYear:1980,flagUrl:t(`Flag_of_Afghanistan_(1978–1980).svg`),label:`Communist red flag`,note:`After the 1978 Saur Revolution, the communist PDPA adopted an almost entirely red flag — widely unpopular for resembling a Soviet banner.`},{fromYear:1974,toYear:1978,flagUrl:t(`Flag_of_Afghanistan_(1974–1978).svg`),label:`Republic of Afghanistan (Daoud)`,note:`After Mohammed Daoud Khan's 1973 coup abolished the monarchy, his republic adopted a flag with an eagle emblem, marking the break from royal symbolism.`},{fromYear:1931,toYear:1973,flagUrl:t(`Flag_of_Afghanistan_(1931–1973).svg`),label:`Kingdom of Afghanistan`,note:`The black-red-green tricolour with the national emblem of a mosque and wheat sheaves flew throughout the long reign of Zahir Shah — Afghanistan's longest-lived flag.`},{fromYear:1928,toYear:1929,flagUrl:t(`Flag_of_Afghanistan_(1928–1929).svg`),label:`Amanullah tricolour`,note:`King Amanullah introduced Afghanistan's first black-red-green vertical tricolour in 1928 after a European tour — the basis for most later designs.`},{fromYear:1901,toYear:1919,flagUrl:t(`Flag_of_Afghanistan_(1901–1919).svg`),label:`Emirate of Afghanistan`,note:`A plain black field used during the reign of Habibullah Khan, characteristic of the early Emirate before national emblems were added.`},{fromYear:1818,toYear:1855,flagUrl:t(`Flag_of_Kandahar_(1818–1856).svg`),label:`Principality of Kandahar`,note:`A Barakzai principality in southern Afghanistan during the fragmentation before the Durrani lands were reunified.`},{fromYear:1747,toYear:1823,flagUrl:t(`Flag_of_the_Durrani_Kingdom.svg`),label:`Durrani Empire`,note:`The empire of Ahmad Shah Durrani, regarded as the founder of modern Afghanistan, stretching from Persia to the Punjab.`},{fromYear:1709,toYear:1738,flagUrl:t(`Black_flag.svg`),label:`Hotak dynasty`,note:`A Pashtun dynasty from Kandahar that briefly overthrew the Persian Safavids before being crushed by Nader Shah.`}],PK:[{fromYear:1947,toYear:null,flagUrl:`/Global/flags/pk.svg`,label:`Flag of Pakistan`,note:`Adopted days before independence in 1947. The white hoist stripe represents religious minorities, while the green field and white crescent-and-star represent the Muslim majority. It has been stable ever since.`},{fromYear:1858,toYear:1947,flagUrl:t(`British_Raj_Red_Ensign.svg`),label:`British India (the Raj)`,note:`Before Partition, the lands that became Pakistan were part of British India, governed under the Union Jack and the unofficial "Star of India" red ensign. The Muslim League's campaign for a separate Muslim homeland culminated in the 1947 Partition, which created Pakistan as two wings (West and East) flanking India — the basis of its green-and-white flag was the League's own banner.`},{fromYear:1666,toYear:1955,flagUrl:t(`FlagofKalat.svg`),label:`Khanate of Kalat`,note:`A Baloch khanate in what is now southwestern Pakistan, briefly independent in 1947–48 before acceding to Pakistan.`},{fromYear:1783,toYear:1843,flagUrl:t(`Flag_of_Sindh_(1783–1843).svg`),label:`Talpur Dynasty`,note:`The Baloch dynasty that ruled Sindh (in modern Pakistan), flying the flag of Sindh, until the British conquered it at the Battle of Miani.`}],BD:[{fromYear:1972,toYear:null,flagUrl:`/Global/flags/bd.svg`,label:`Flag of Bangladesh`,note:`In 1972 the gold map was removed, leaving a red disc on green. The disc is set slightly toward the hoist so it appears centered when the flag flies.`},{fromYear:1971,toYear:1972,flagUrl:t(`Flag_of_Bangladesh_(1971).svg`),label:`Liberation War flag (with map)`,note:`Used during the 1971 Liberation War: a red disc on green bearing a gold silhouette map of the country, dropped partly because it was hard to render correctly on both sides.`},{fromYear:1947,toYear:1971,flagUrl:`/Global/flags/pk.svg`,label:`East Pakistan`,note:`At the 1947 Partition of British India, the Bengali-speaking east became East Pakistan — one wing of a country split by 1,600 km of Indian territory — and flew the green-and-white flag of Pakistan. Resentment over political and economic domination by West Pakistan, and the suppression of the Bengali language, fuelled the independence movement that erupted into the 1971 Liberation War.`}],NP:[{fromYear:1962,toYear:null,flagUrl:`/Global/flags/np.svg`,label:`Flag of Nepal`,note:`Standardized in 1962, when the faces were removed from the sun and moon. It is the world's only non-rectangular national flag — two stacked pennants.`},{fromYear:1743,toYear:1962,flagUrl:t(`Flag_of_Nepal_(1743–1962).svg`),label:`Pre-standardization double-pennon`,note:`The traditional double-pennon flag whose sun and crescent-moon emblems bore human faces, used for centuries before modernization.`}],BT:[{fromYear:1969,toYear:null,flagUrl:`/Global/flags/bt.svg`,label:`Flag of Bhutan`,note:`Finalized around 1969: the white Thunder Dragon clutches jewels, the yellow half denotes the secular monarchy and the orange-red half the Buddhist spiritual tradition.`},{fromYear:1956,toYear:1969,flagUrl:t(`Flag_of_Bhutan_(1956–1969).svg`),label:`White dragon (revised)`,note:`Revised so the Thunder Dragon was rendered in white and positioned horizontally across the center.`},{fromYear:1949,toYear:1956,flagUrl:t(`Flag_of_Bhutan_(1949–1956).svg`),label:`Early Bhutan flag`,note:`An early version with the dragon oriented along the diagonal, the field divided yellow over red.`}],MV:[{fromYear:1965,toYear:null,flagUrl:`/Global/flags/mv.svg`,label:`Flag of the Maldives`,note:`Adopted at independence in 1965; the black-and-white hoist stripes were removed, leaving the red field, green panel, and white crescent opening toward the fly.`},{fromYear:1953,toYear:1965,flagUrl:t(`Flag_of_the_Maldives_1953.svg`),label:`Republic flag (striped hoist)`,note:`On becoming a republic in 1953, a green rectangle with a white crescent was set on the red field, with black-and-white "Dhandimathi" stripes still at the hoist.`},{fromYear:1926,toYear:1953,flagUrl:t(`Old_National_Flag_of_the_Maldives.svg`),label:`Red flag with crescent`,note:`The white crescent was added to the historic plain red flag around 1926, with the black-and-white striped hoist band.`}],LK:[{fromYear:1972,toYear:null,flagUrl:`/Global/flags/lk.svg`,label:`Flag of Sri Lanka`,note:`When the country became the Republic of Sri Lanka in 1972, the corner pinnacles were replaced with four bo (pipal) tree leaves, a Buddhist symbol of compassion.`},{fromYear:1951,toYear:1972,flagUrl:t(`Flag_of_Ceylon_(1951–1972).svg`),label:`Lion flag with stripes`,note:`In 1951 two vertical stripes — green and orange — were added at the hoist to represent the Muslim and Tamil communities, broadening the flag's symbolism.`},{fromYear:1948,toYear:1951,flagUrl:t(`Flag_of_Ceylon_(1948–1951).svg`),label:`Dominion of Ceylon lion flag`,note:`Hoisted at independence in 1948 — a yellow lion with sword on dark crimson, reviving the Kandyan royal standard.`},{fromYear:1798,toYear:1815,flagUrl:t(`King_of_Kandy.svg`),label:`Lion Flag of the Kingdom of Kandy`,note:`The royal standard of Sri Vikrama Rajasinha, captured by the British at the 1815 Kandyan Convention and rediscovered in London in 1908 — it became the model for independent Ceylon's flag.`},{fromYear:1521,toYear:1594,flagUrl:t(`Flag_of_Sitawaka_Kingdom_(1521_-_1594).png`),label:`Kingdom of Sitawaka`,note:`A kingdom of the Sri Lankan interior that mounted the fiercest resistance to Portuguese conquest of the island.`}],KH:[{fromYear:1993,toYear:null,flagUrl:`/Global/flags/kh.svg`,label:`Kingdom of Cambodia`,note:`The 1948 Angkor Wat design was readopted in 1993 when the monarchy was restored. Cambodia is one of only a few countries whose flag depicts a building — and it has done so under nearly every regime since 1948.`},{fromYear:1989,toYear:1993,flagUrl:t(`Flag_of_the_State_of_Cambodia_1989-1993.svg`),label:`State of Cambodia`,note:`A horizontally divided red-over-blue flag, each band charged with a yellow Angkor Wat, used after the country renamed itself the State of Cambodia.`},{fromYear:1979,toYear:1989,flagUrl:t(`Flag_of_the_People's_Republic_of_Kampuchea.svg`),label:`People's Republic of Kampuchea`,note:`The Vietnamese-backed government's red flag with a yellow five-towered Angkor Wat — two more towers than the Khmer Rouge version it replaced.`},{fromYear:1975,toYear:1979,flagUrl:t(`Flag_of_Democratic_Kampuchea.svg`),label:`Democratic Kampuchea (Khmer Rouge)`,note:`A plain red field with a stylized yellow three-towered Angkor Wat, flown during the genocidal Pol Pot regime.`},{fromYear:1970,toYear:1975,flagUrl:t(`Flag_of_the_Khmer_Republic.svg`),label:`Khmer Republic`,note:`Lon Nol's republic kept Angkor Wat but moved it to a red canton with three white stars for the legislative, executive, and judicial branches.`},{fromYear:1948,toYear:1970,flagUrl:t(`Flag_of_Cambodia_(1948-1970).svg`),label:`Kingdom of Cambodia (independence)`,note:`A blue-red-blue tricolour with a white Angkor Wat on the central band, adopted on independence from France — the original of the design used today.`},{fromYear:1863,toYear:1948,flagUrl:`/Global/flags/fr.svg`,label:`French Cambodia (Indochina)`,note:`Heir to the mighty Khmer Empire that built Angkor, Cambodia had shrunk and was being squeezed between Siam and Vietnam when it accepted a French protectorate in 1863 — flying the French flag as part of French Indochina until independence in 1953. French rule almost certainly saved Cambodia from being partitioned out of existence by its neighbours.`}],MM:[{fromYear:2010,toYear:null,flagUrl:`/Global/flags/mm.svg`,label:`Republic of the Union of Myanmar`,note:`A yellow-green-red horizontal tricolour with a large white five-pointed star in the center, adopted in 2010.`},{fromYear:1974,toYear:2010,flagUrl:t(`Flag_of_Myanmar_(1974–2010).svg`),label:`Socialist Republic of Burma`,note:`A red field with a blue canton bearing a white cogwheel and rice-stalk ringed by 14 stars for the states and divisions, adopted under Ne Win's socialist state.`},{fromYear:1948,toYear:1974,flagUrl:t(`Flag_of_Burma_(1948–1974).svg`),label:`Union of Burma (independence)`,note:`A red field with a blue canton containing one large white star surrounded by five smaller stars, adopted at independence in 1948.`},{fromYear:1939,toYear:1948,flagUrl:t(`Flag_of_the_British_Burma_(1939-1948).svg`),label:`British Burma`,note:`A British Blue Ensign with a yellow disc bearing a green-and-blue peacock, the emblem of the Konbaung dynasty, used after Burma was separated from British India.`},{fromYear:1287,toYear:1552,flagUrl:t(`Golden_Hintar_flag_of_Burma.svg`),label:`Hanthawaddy kingdom`,note:`A Mon kingdom of lower Burma, a great centre of Theravada Buddhism and maritime trade.`}],TH:[{fromYear:1917,toYear:null,flagUrl:`/Global/flags/th.svg`,label:`Thong Trairong`,note:`The central stripe was changed to dark blue in 1917 — honoring Rama VI's birthday color and the WWI Allies — giving the red-white-blue-white-red flag with its double-width blue band.`},{fromYear:1916,toYear:1917,flagUrl:t(`Flag_of_Siam_(1916).svg`),label:`Five-stripe flag`,note:`A transitional flag of five red-and-white stripes. By legend, Rama VI had seen an elephant flag flown upside-down during a flood and wanted a symmetrical design that could not be inverted.`},{fromYear:1855,toYear:1916,flagUrl:t(`Flag_of_Siam_(1855).svg`),label:`White elephant on red`,note:`King Mongkut (Rama IV) added a white elephant — a royal symbol of good fortune — to the red field in 1855 so foreign ships could distinguish Siam.`},{fromYear:1782,toYear:1855,flagUrl:t(`Flag_of_Thailand_(1782).svg`),label:`Plain red flag`,note:`A plain red field was Siam's earliest national and merchant flag, its origins tracing back to the 17th century under King Narai.`},{fromYear:1350,toYear:1767,flagUrl:t(`Flag_of_Thailand_(Ayutthaya_period).svg`),label:`Ayutthaya Kingdom`,note:`Before Bangkok, the Siamese capital was Ayutthaya — for four centuries one of the world's great cities, a cosmopolitan trading hub that astonished European visitors — which flew a plain red flag. Its destruction by a Burmese army in 1767 ended the kingdom, but the survivors regrouped and founded the Bangkok (Rattanakosin) state that became modern Thailand.`},{fromYear:1767,toYear:1782,flagUrl:t(`Flag_of_Thailand_(Ayutthaya_period).svg`),label:`Thonburi Kingdom`,note:`The brief kingdom of King Taksin, who reunited Siam after the fall of Ayutthaya before Bangkok became the capital.`},{fromYear:1516,toYear:1902,flagUrl:t(`Flag_of_Patani_Kingdom_(until_1816).svg`),label:`Pattani kingdom`,note:`A Malay-Muslim sultanate in what is now southern Thailand, annexed by Siam — the root of a still-simmering insurgency.`},{fromYear:1808,toYear:1916,flagUrl:t(`Flag_of_Kedah_(18th_century_-_1821).svg`),label:`Kingdom of Setul Mambang Segara`,note:`A Malay state on the peninsula, ceded by Siam's vassal Kedah and absorbed into Thailand as Satun province.`}],MN:[{fromYear:1992,toYear:null,flagUrl:`/Global/flags/mn.svg`,label:`Flag of Mongolia`,note:`In 1992 the socialist star above the Soyombo was removed, leaving the red-blue-red triband with the golden Soyombo national symbol at the hoist.`},{fromYear:1945,toYear:1992,flagUrl:t(`Flag_of_the_Mongolian_People's_Republic_(1945–1992).svg`),label:`Mongolian People's Republic`,note:`The classic socialist-era flag: a red-blue-red triband with the golden Soyombo on the hoist, topped by a gold communist five-pointed star.`},{fromYear:1924,toYear:1940,flagUrl:t(`Flag_of_Mongolia_(1924–1940).svg`),label:`Mongolian People's Republic (early)`,note:`Adopted after the founding of the MPR in 1924, with a centered Soyombo emblem.`},{fromYear:1911,toYear:1921,flagUrl:t(`Flag_of_Bogd_Khaanate_Mongolia.svg`),label:`Bogd Khanate of Mongolia`,note:`A yellow flag bearing the Soyombo symbol, used by the Buddhist theocratic monarchy after Mongolia declared independence from Qing China in 1911.`}],LA:[{fromYear:1975,toYear:null,flagUrl:`/Global/flags/la.svg`,label:`Lao PDR (Pathet Lao flag)`,note:`A red-blue-red triband with a white disc, adopted nationally in 1975. The disc symbolizes a full moon over the Mekong and national unity.`},{fromYear:1952,toYear:1975,flagUrl:t(`Flag_of_Laos_(1952–1975).svg`),label:`Kingdom of Laos`,note:`A red field with a white three-headed elephant on a pedestal beneath a parasol — the three heads for the former kingdoms of the "Land of a Million Elephants."`},{fromYear:1893,toYear:1953,flagUrl:`/Global/flags/fr.svg`,label:`French Laos (Indochina)`,note:`France absorbed the Lao kingdoms into French Indochina in 1893, reuniting the fragments of the old Lan Xang ("Land of a Million Elephants") under a protectorate flying the French flag. Apart from a Japanese-occupied interlude in WWII, French rule lasted until full independence in 1953 — and the three-headed elephant of the restored kingdom recalled the unity Lan Xang once had.`},{fromYear:1945,toYear:1946,flagUrl:t(`Flag_of_Laos.svg`),label:`Lao Issara`,note:`The 'Free Lao' provisional government that briefly declared independence before the French returned.`},{fromYear:1713,toYear:1904,flagUrl:t(`Flag_of_the_Kingdom_of_Champasak.svg`),label:`Kingdom of Champasak`,note:`The southernmost of the successor kingdoms of Lan Xang, later a principality under French Laos.`},{fromYear:1707,toYear:1828,flagUrl:t(`Flag_of_the_Kingdom_of_Vientiane_(1707–1828).svg`),label:`Kingdom of Vientiane`,note:`One of the three Lao kingdoms that emerged from the breakup of Lan Xang, destroyed by Siam.`}],KP:[{fromYear:1948,toYear:null,flagUrl:`/Global/flags/kp.svg`,label:`DPRK red-star flag`,note:`Adopted in 1948, replacing the Taegukgi: a broad red band edged with white and blue stripes, with a red star in a white disc near the hoist.`},{fromYear:1945,toYear:1948,flagUrl:t(`Flag_of_Korea_(1882–1910).svg`),label:`Taegukgi (shared Korean flag)`,note:`Before partition, the whole peninsula used the Taegukgi — white field, red-and-blue taegeuk, four black trigrams. The North flew it again after liberation in 1945 until 1948, when it broke from the South's design and adopted the red-star flag.`},{fromYear:1910,toYear:1945,flagUrl:`/Global/flags/jp.svg`,label:`Japanese occupation`,note:`Japan annexed Korea in 1910 and ruled the whole peninsula for 35 years under its own flag, banning the Taegukgi and suppressing Korean language and identity in a harsh colonial regime. Liberation came in 1945 with Japan's WWII defeat — immediately followed by the Soviet-American division of the peninsula that hardened into North and South.`}]},r={AL:`Albania is a small Balkan nation on the Adriatic and Ionian coasts of southeastern Europe, bordered by Montenegro, Kosovo, North Macedonia, and Greece. Once one of the most isolated countries in the world under communist rule until 1991, it has since opened significantly to the wider world. The country is known for its ancient Illyrian heritage, its distinctive double-headed eagle national symbol, and its well-preserved Ottoman-era cities such as UNESCO-listed Gjirokastër.`,AD:`Andorra is a tiny microstate nestled in the Pyrenean mountains between France and Spain, one of Europe's smallest countries. It has been jointly governed as a co-principality by the French head of state and the Bishop of Urgell since 1278, an arrangement unique in the modern world. Despite its small size, Andorra is a popular destination known for duty-free shopping, skiing, and spectacular mountain scenery.`,AT:`Austria is a landlocked country in Central Europe known for its alpine scenery, imperial architecture, and extraordinary musical heritage. For centuries it was the centre of the Habsburg Empire, one of Europe's most powerful dynasties, which shaped the culture of the entire continent. Vienna, the capital, was home to Mozart, Beethoven, Schubert, Brahms, and Mahler, and remains one of the world's preeminent cultural cities.`,BY:`Belarus is a landlocked country in Eastern Europe bordered by Russia, Ukraine, Poland, Lithuania, and Latvia, maintaining close political and economic ties with Russia. Minsk, the capital, was almost entirely destroyed during World War II and was meticulously rebuilt in an imposing Soviet architectural style with wide boulevards and grand public squares. The country has a rich tradition of folk art, weaving, and woodcraft.`,BE:`Belgium is a small but densely populated country in Western Europe that serves as the de facto capital of the European Union, hosting the EU's major institutions in Brussels. The country is divided into three linguistic communities — Dutch-speaking Flanders, French-speaking Wallonia, and a small German-speaking area — giving it a complex federal structure. Belgium is celebrated globally for its chocolate, beer, waffles, and its rich tradition of comic art.`,BA:`Bosnia and Herzegovina is a country in the western Balkans with a complex administrative structure established by the 1995 Dayton Agreement following the Bosnian War. The country is home to a mix of Bosniak, Serb, and Croat communities sharing a mountainous, landlocked landscape threaded with rivers. Sarajevo, the capital, famously hosted the 1984 Winter Olympics and is known for its blend of Ottoman, Austro-Hungarian, and socialist architectural heritage.`,BG:`Bulgaria is a country in southeastern Europe on the Black Sea coast with one of the longest recorded national histories in Europe, having been established as a kingdom in 681 AD. The Cyrillic alphabet, now used by hundreds of millions of people, was developed by Bulgarian monks Saints Cyril and Methodius in the 9th century. Bulgaria is known for its rose oil production, ancient Thracian treasures, Black Sea resorts, and UNESCO-listed Rila Monastery.`,HR:`Croatia stretches along the eastern Adriatic Sea and is known for its dramatic coastline, more than a thousand islands, and well-preserved medieval cities. Dubrovnik, encircled by massive limestone walls, is one of Europe's most iconic historic cities and has been a UNESCO World Heritage Site since 1979. Croatia joined the European Union in 2013 and is famous worldwide for the crystalline waterfalls of Plitvice Lakes National Park.`,CY:`Cyprus is an island nation in the Eastern Mediterranean — the third-largest island in the sea — known as the mythological birthplace of the goddess Aphrodite. The island has been divided since 1974, with the northern portion under Turkish administration and the internationally recognised Republic of Cyprus governing the south. It is famous for its warm climate, ancient ruins, Venetian walls, and the unique copper-coloured map depicted on its national flag.`,CZ:`The Czech Republic, also called Czechia, is a landlocked Central European country celebrated for its medieval architecture, rich brewing tradition, and wealth of historic towns. Prague, the capital, served as an imperial seat of the Holy Roman Empire and remains one of the best-preserved Gothic and Baroque cities in Europe. Czechoslovakia peacefully dissolved into the Czech Republic and Slovakia in 1993, an event known as the Velvet Divorce.`,DK:`Denmark is a Nordic nation comprising the Jutland Peninsula and numerous islands, consistently ranking among the world's happiest and most prosperous countries. The Danish flag, the Dannebrog, is the oldest national flag still in use by an independent nation, dating to at least 1370. Denmark is a constitutional monarchy with a long maritime trading tradition, and its territories include Greenland, the world's largest island.`,EE:`Estonia is one of the three Baltic states on the eastern shore of the Baltic Sea, having re-declared independence from the Soviet Union in 1991 as one of its first republics to do so. It rapidly transformed into one of the world's most digitally advanced societies, pioneering e-government, digital voting, and the concept of e-residency. Tallinn, the capital, has one of the best-preserved medieval old towns in all of Northern Europe.`,FI:`Finland is a Nordic country bordering Sweden, Norway, and Russia, known for its vast forests, tens of thousands of lakes, and the spectacular aurora borealis. It was part of Sweden for nearly 700 years before becoming a Russian Grand Duchy in 1809 and declaring independence in 1917. Finland consistently ranks at the very top of global happiness, education, and quality-of-life indices.`,FR:`France is one of the world's most visited countries, attracting around 90 million tourists annually, and a founding member of the European Union and a permanent member of the UN Security Council. It has been a major cultural, philosophical, and political force in Western civilisation for centuries. Paris, the capital, is globally associated with art, fashion, gastronomy, the Eiffel Tower, and some of the world's greatest museums.`,DE:`Germany is the most populous country in the European Union and the largest economy in Europe, known worldwide for its engineering, automotive industry, and precision manufacturing. Reunified in 1990 after four decades of division, Germany became a leading force in European politics and global trade. Berlin, the capital, is one of Europe's most culturally vibrant cities with a history that spans Prussian grandeur, division, and remarkable reunification.`,GR:`Greece is widely regarded as the cradle of Western civilisation, birthplace of democracy, Western philosophy, the Olympic Games, and significant foundations of modern literature and science. The country consists of a mountainous mainland peninsula and more than 6,000 islands, of which about 230 are permanently inhabited. Athens, one of the world's oldest cities, has been continuously inhabited for at least 7,000 years and is home to the ancient Acropolis.`,HU:`Hungary is a landlocked Central European country with a language unrelated to its Slavic and Germanic neighbours, belonging to the Finno-Ugric language family. Budapest, formed by the union of Buda and Pest in 1873, is often called the 'Paris of the East' for its grand boulevards, thermal baths, and ornate parliament building on the Danube. Hungary was a major power within the Austro-Hungarian Empire and joined the European Union in 2004.`,IS:`Iceland is a Nordic island nation in the North Atlantic, the most sparsely populated country in Europe and one of the most geologically active places on Earth, home to active volcanoes, geysers, hot springs, and vast lava fields. Despite its position near the Arctic Circle, the Gulf Stream keeps its coastal areas relatively mild. Iceland's parliament, the Althing, founded in 930 AD, is the world's oldest parliament still in operation.`,IE:`Ireland is an island nation in northwestern Europe known for its lush green landscapes, rich literary heritage from writers like Oscar Wilde and James Joyce, and vibrant Celtic culture. The island is divided between the Republic of Ireland and Northern Ireland, which is part of the United Kingdom. Ireland joined the European Economic Community in 1973 and has since become one of Europe's most prosperous economies, home to the European headquarters of many global technology companies.`,IT:`Italy is a southern European country occupying the boot-shaped peninsula that reaches into the Mediterranean, together with the islands of Sicily and Sardinia. The heart of the ancient Roman Empire and the birthplace of the Renaissance, Italy has shaped Western art, architecture, music, and cuisine more than almost any other nation. It holds more UNESCO World Heritage Sites than any country on Earth, and Rome, the capital, completely surrounds the independent Vatican City. Italy unified into a single kingdom only in 1861.`,XK:`Kosovo is one of the world's newest countries, having declared independence from Serbia in 2008 following a period of international administration after the 1998-99 conflict. It is recognised by over 100 UN member states and is a predominantly Albanian-populated territory with significant Serbian Orthodox cultural heritage, including medieval monasteries that are UNESCO World Heritage Sites. Pristina is its rapidly developing capital and largest city.`,LV:`Latvia is one of the three Baltic states, situated between Estonia and Lithuania on the eastern shore of the Baltic Sea. It regained independence from the Soviet Union in 1991 and joined both NATO and the European Union in 2004. Riga, the capital, is the largest city in the Baltic states and is renowned for its outstanding collection of Art Nouveau architecture — the largest concentration of such buildings in the world.`,LI:`Liechtenstein is a tiny doubly landlocked microstate in Central Europe nestled between Switzerland and Austria, and is one of only two countries in the world entirely surrounded by landlocked countries. Despite covering just 160 square kilometres, it has one of the world's highest per-capita incomes and is a significant international financial centre. Liechtenstein is a constitutional monarchy ruled by the Prince of Liechtenstein and has no airport.`,LT:`Lithuania is the southernmost and largest of the three Baltic states and was historically the centre of the Grand Duchy of Lithuania, one of the largest states in medieval Europe. It was the first Soviet republic to declare independence in 1990 and joined both NATO and the EU in 2004. Vilnius, the capital, is known for its remarkably well-preserved Baroque old town, a UNESCO World Heritage Site.`,LU:`Luxembourg is a small landlocked grand duchy in Western Europe, bordered by Belgium, France, and Germany, and is one of the wealthiest countries in the world per capita. It hosts key European Union institutions and is a major centre for European banking and finance. Despite its tiny size, Luxembourg has three official languages — Luxembourgish, French, and German — reflecting its position at the crossroads of European cultures.`,MT:`Malta is a small Mediterranean archipelago south of Sicily and one of the world's smallest and most densely populated countries. Its strategic location has made it a crossroads of civilisations for millennia, ruled by the Phoenicians, Romans, Arabs, Normans, Knights of St John, French, and British. The island has an extraordinary concentration of prehistoric temples, Baroque architecture, and ancient fortifications, and joined the EU in 2004.`,MD:`Moldova is a small landlocked country in Eastern Europe bordered by Romania and Ukraine, one of Europe's least visited yet historically fascinating nations. Gaining independence from the Soviet Union in 1991, it navigates the challenge of the breakaway region of Transnistria, which has functioned as a de facto separate state since 1990. Moldova has a long winemaking tradition stretching back thousands of years and is known for producing excellent wines.`,MC:`Monaco is a tiny city-state on the French Riviera, the world's second-smallest country by area after Vatican City, and the most densely populated sovereign state in the world. Synonymous with luxury, it is home to the famous Monte Carlo Casino, the Formula One Monaco Grand Prix, and a high concentration of the world's wealthiest individuals. The Grimaldi family has ruled Monaco since 1297, making it one of the world's oldest ruling dynasties.`,ME:`Montenegro is a small Balkan nation on the Adriatic Sea that declared independence from the State Union of Serbia and Montenegro in 2006. Its name means 'Black Mountain' in Italian, referring to the imposing dark peak of Mount Lovćen. The country is known for its dramatic mountain landscape, medieval walled towns, and the stunning Bay of Kotor, sometimes described as Europe's southernmost fjord.`,NL:`The Netherlands is a densely populated country in Western Europe famous for its flat landscape, extensive canal systems, windmills, tulip fields, and masters of Dutch Golden Age painting such as Rembrandt and Vermeer. A historically significant maritime and trading nation, the Netherlands built a major colonial empire during its 17th-century Golden Age. Amsterdam is the constitutional capital while The Hague is the seat of government and home to the International Court of Justice.`,MK:`North Macedonia is a small landlocked country in the southern Balkans that was part of Yugoslavia until 1991. A prolonged dispute with Greece over the use of the name 'Macedonia' was resolved in 2019 when it officially became the Republic of North Macedonia. Skopje, the capital, was largely destroyed by a devastating earthquake in 1963 and was rebuilt over subsequent decades, and is home to one of the largest and oldest bazaars in the Balkans.`,NO:`Norway is a Nordic country occupying the western part of the Scandinavian Peninsula, famous for its dramatic fjords, the aurora borealis, the midnight sun, and a remarkably high standard of living. The country manages one of the world's largest sovereign wealth funds, generated from its offshore oil and gas revenues. Norway has a strong tradition of international peacekeeping and humanitarian aid and consistently ranks among the best countries in the world for human development.`,PL:`Poland is the largest country in Central Europe by area and population, with a turbulent history shaped by centuries of partition and occupation by neighbouring empires. Warsaw, the capital, was almost entirely destroyed during World War II and was painstakingly rebuilt by its citizens, with the historic centre now a UNESCO World Heritage Site. Poland joined NATO in 1999 and the European Union in 2004 and has become one of Europe's fastest-growing economies.`,PT:`Portugal occupies the southwestern tip of continental Europe and was once the centre of one of history's most far-reaching maritime empires. Portuguese navigators in the 15th and 16th centuries opened sea routes to Africa, Asia, and the Americas, fundamentally reshaping global trade. Today Portugal is known for its fado music, azulejo tilework, pastel de nata custard tarts, port wine, and is one of the oldest nation-states in Europe.`,RO:`Romania is a country at the intersection of Central, Eastern, and Southeastern Europe, home to the legendary Transylvania region, the Carpathian Mountains, and the biodiverse Danube Delta. The country emerged dramatically from communist rule in December 1989, when Nicolae Ceaușescu's government was overthrown in the only violent revolution of the Eastern Bloc's 1989 wave. Romania joined the EU in 2007 and is known for its medieval citadels, painted monasteries of Bucovina, and unique folk traditions.`,RU:`Russia is the world's largest country by land area, spanning eleven time zones and stretching from Eastern Europe across northern Asia to the Pacific Ocean. Moscow, the capital, is one of Europe's largest cities and a major global political, economic, and cultural centre. Russia has an extraordinarily rich literary and artistic heritage, with writers like Tolstoy and Dostoevsky, composers like Tchaikovsky and Stravinsky, and a deep tradition of classical ballet.`,SM:`San Marino is a landlocked microstate entirely surrounded by Italy, and according to tradition was founded in 301 AD, making it the world's oldest republic still in existence. Its territory consists of the slopes of Mount Titano, topped by three medieval fortified towers that have overlooked the surrounding Italian plain for centuries. Despite being completely surrounded by Italian territory, San Marino maintains its own government, passport, and distinct national identity.`,RS:`Serbia is a landlocked Balkan country that was historically the dominant republic within the former Yugoslavia. Belgrade, the capital, sits at the confluence of the Sava and Danube rivers and has been an important regional hub for thousands of years — it has been destroyed and rebuilt more than 40 times in its history. Serbia is known for its vibrant music scene, including the Exit Festival, and a rich Eastern Orthodox Christian heritage with important medieval monasteries.`,SK:`Slovakia is a landlocked Central European country sharing borders with Austria, Czech Republic, Hungary, Poland, and Ukraine. It was joined with the Czech Republic in Czechoslovakia until the two nations amicably separated in 1993 in the Velvet Divorce. Bratislava, the capital, is uniquely positioned so that residents can reach three different countries — Slovakia, Austria, and Hungary — within an hour's drive, making it one of Europe's most internationally connected capitals.`,SI:`Slovenia is one of the smallest and most prosperous countries in Central Europe, known for its alpine terrain, pristine lakes, medieval old towns, and remarkable biodiversity packed into a small area. It was the first former Yugoslav republic to join the European Union in 2004. Lake Bled, with its island church and clifftop castle reflected in turquoise glacial waters, is one of Europe's most photographed and widely recognised landscapes.`,ES:`Spain is the second-largest country in the European Union by area, situated on the Iberian Peninsula with additional territory in the Canary Islands, Balearic Islands, and two cities on the North African coast. It has a rich cultural heritage blending Roman, Moorish, and Christian traditions, visible in its architecture, art, cuisine, and festivals. Spain has more UNESCO World Heritage Sites than almost any other country and is one of the world's most visited nations.`,SE:`Sweden is the largest country in Northern Europe and is known for its progressive social model, high standard of living, and a long tradition of neutrality in international conflicts. It is home to the Nobel Prize, awarded annually in Stockholm, and has produced globally influential exports including IKEA, Spotify, Volvo, ABBA, and a remarkable tradition of children's literature. Sweden joined the European Union in 1995 and has one of the world's highest rates of gender equality.`,CH:`Switzerland is a landlocked country in Central Europe famous for its stunning alpine scenery, precision watchmaking, chocolate, cheese, and centuries of political neutrality. The Swiss Confederation, founded in 1291, is one of the world's oldest federations and has maintained armed neutrality in European conflicts since 1815. Switzerland is home to the International Red Cross (founded there in 1863), numerous United Nations agencies, and has four official national languages: German, French, Italian, and Romansh.`,UA:`Ukraine is the largest country situated entirely within Europe, a vast nation with a rich agricultural tradition — it was once called the 'breadbasket of Europe' — and significant mineral and industrial resources. Kyiv, one of Eastern Europe's oldest and most historic cities, was the capital of the medieval Kyivan Rus state, a major cultural and political centre of early medieval Europe. Ukraine declared independence from the Soviet Union in 1991 and has a population of around 40 million people.`,GB:`The United Kingdom consists of four constituent nations — England, Scotland, Wales, and Northern Ireland — and was historically the centre of the world's largest empire, covering approximately a quarter of Earth's land surface at its peak. London, the capital, is one of the world's leading financial, cultural, and political cities, home to institutions from the British Museum to the Houses of Parliament. The UK is a founding member of NATO and a permanent member of the UN Security Council.`,VA:`Vatican City is the world's smallest internationally recognised country, an independent city-state entirely within Rome covering just 44 hectares. It serves as the headquarters of the Roman Catholic Church and the residence of the Pope, giving this tiny territory immense religious significance for over 1.3 billion Catholics worldwide. Vatican City is home to St Peter's Basilica, the Sistine Chapel with Michelangelo's famous ceiling fresco, and some of the world's most important art and historical collections.`,DZ:`Algeria is the largest country in Africa and in the Arab world by area, located in North Africa with a Mediterranean coastline in the north and the Sahara Desert covering about 90% of its territory. The country gained independence from France in 1962 after a long and costly eight-year independence war. Algeria has significant oil and natural gas reserves, and its capital Algiers — known as 'Alger la Blanche' (Algiers the White) — is one of North Africa's most striking cities.`,AO:`Angola is a large country on the southwestern coast of Africa, rich in oil, diamonds, and other natural resources. It was a Portuguese colony for nearly 500 years before gaining independence in 1975, which was immediately followed by a devastating civil war that lasted until 2002. Luanda, the capital, grew rapidly into one of Africa's most expensive cities due to the oil boom, though the country's wealth remains very unevenly distributed.`,BJ:`Benin is a small West African nation historically home to the powerful Kingdom of Dahomey, known for its sophisticated military, its all-female royal regiment called the Agojie, and its significant role in the Atlantic slave trade. The country is considered the birthplace of Vodun (Voodoo) religion, which spread to Haiti and other parts of the Americas through the slave trade. Benin was renamed from the Republic of Dahomey in 1975.`,BW:`Botswana is a landlocked country in Southern Africa that has undergone one of history's most remarkable development transformations, going from one of Africa's poorest nations at independence in 1966 to a middle-income country driven by diamond mining and stable governance. It is home to the Okavango Delta, one of the world's largest inland deltas, which floods seasonally to create an extraordinary wildlife-rich oasis in the Kalahari Desert. Botswana has maintained democratic governance since independence.`,BF:`Burkina Faso is a landlocked West African country with a rich tradition of art, music, and film despite being one of the world's least economically developed nations. It was formerly known as Upper Volta before being renamed in 1984 to mean 'Land of Incorruptible People' in two local languages. The country hosts FESPACO, one of Africa's most prestigious film and television festivals, held every two years in the capital Ouagadougou.`,BI:`Burundi is one of the world's smallest and most densely populated countries, a landlocked nation in the Great Rift Valley of Central Africa. It shares significant ethnic, linguistic, and cultural ties with Rwanda to the north. Despite having fertile agricultural land and a beautiful landscape of hills and lakes overlooking Lake Tanganyika, Burundi is consistently ranked among the world's least developed nations.`,CM:`Cameroon is located at the junction of West and Central Africa and is often called 'Africa in miniature' for its extraordinary geographical and cultural diversity, encompassing Atlantic beaches, volcanic mountains, savanna grasslands, tropical rainforests, and the Saharan fringes. The country has over 250 ethnic groups and was formerly divided between British and French colonial administration. Yaoundé is the political capital while Douala is the main port city and economic hub.`,CV:`Cape Verde is an archipelago of ten volcanic islands in the central Atlantic Ocean, located about 570 kilometres off the coast of West Africa. The islands had no indigenous population and were uninhabited until Portuguese colonisation in the 15th century. Cape Verde is known internationally for its distinctive morna music, associated with the legendary singer Cesária Évora, and has developed a stable democratic government and relatively strong economy for a small island nation.`,CF:`The Central African Republic is a landlocked country in Central Africa, one of the world's least developed and most sparsely populated nations despite having significant timber, diamond, gold, and uranium resources. Bangui, the capital, sits on the Ubangi River which forms the border with the Democratic Republic of the Congo. The country has experienced persistent political instability and armed conflict since independence from France in 1960.`,TD:`Chad is the fifth-largest country in Africa, a vast landlocked nation spanning from the Sahara Desert in the north — where the Tibesti Mountains contain dramatic desert landscapes — to tropical savannas and wetlands in the south. Lake Chad, which gives the country its name, was once one of Africa's largest lakes but has shrunk dramatically in recent decades due to climate change and agricultural water use. Chad is among the world's most remote and least developed countries.`,KM:`Comoros is a small archipelago nation in the Indian Ocean between northern Madagascar and the coast of Mozambique, consisting of three main volcanic islands. It is one of the world's smallest and least developed nations and has experienced remarkable political instability since gaining independence from France in 1975. The Comoros islands are a major global producer of ylang-ylang, an essential oil widely used in the fragrance and cosmetics industry.`,CG:`The Republic of the Congo, sometimes called Congo-Brazzaville, is a Central African country along the Congo River, distinct from the much larger Democratic Republic of the Congo across the water. It gained independence from France in 1960 and has significant offshore oil reserves. Its capital Brazzaville sits directly across the Congo River from Kinshasa, making them the world's closest pair of capital cities, visible to each other across the water.`,CD:`The Democratic Republic of the Congo is the second-largest country in Africa and home to the Congo Rainforest, the world's second-largest tropical rainforest, sometimes called the 'lungs of Africa.' The country has extraordinary mineral wealth, including the majority of the world's cobalt reserves along with significant coltan, diamonds, and gold, though this has been a persistent source of conflict. Kinshasa is one of the most populous cities in Africa.`,CI:`Côte d'Ivoire (Ivory Coast) is the world's largest producer of cocoa beans, supplying roughly a third of the global supply, and is a major economic hub in West Africa. It has two capitals: Yamoussoukro, the official political capital home to the enormous Basilica of Our Lady of Peace, and Abidjan, the economic and commercial centre. The country has a diverse cultural heritage and significant mineral resources.`,DJ:`Djibouti is a tiny nation at the Horn of Africa where the Red Sea meets the Gulf of Aden, occupying one of the world's most strategically important maritime chokepoints. This location has made it home to multiple foreign military bases — American, French, Chinese, Japanese, and Italian — a unique concentration for such a small country. Despite limited natural resources, Djibouti generates significant revenue from port services and serves as the main trade gateway for landlocked Ethiopia.`,EG:`Egypt is a transcontinental country spanning northeastern Africa and the Sinai Peninsula of Asia, home to one of the world's oldest and most influential civilisations, which flourished for over 3,000 years along the Nile River. The country is home to iconic ancient monuments including the Pyramids of Giza, the only surviving wonder of the ancient world, and the Sphinx. Egypt controls the Suez Canal, one of the world's most strategically vital shipping routes, connecting the Mediterranean and Red Seas.`,GQ:`Equatorial Guinea is the only Spanish-speaking country in Africa, a distinction reflecting its colonial history as a Spanish territory. It consists of a mainland region called Río Muni and several islands including Bioko, where the capital Malabo is located. The discovery of significant offshore oil deposits in the 1990s dramatically increased national income, though wealth distribution remains highly unequal among the population.`,ER:`Eritrea is a small nation on the Horn of Africa with a long Red Sea coastline, bordering Sudan, Ethiopia, and Djibouti. It gained independence from Ethiopia in 1993 following a 30-year independence war. The country has nine officially recognised ethnic groups and maintains a mandatory national service programme. Its port city of Massawa and capital Asmara feature distinctive Italian colonial architecture, and Asmara's modernist buildings are a UNESCO World Heritage Site.`,SZ:`Eswatini (formerly Swaziland, renamed in 2018) is a small landlocked kingdom in Southern Africa almost entirely surrounded by South Africa. It is one of the world's last remaining absolute monarchies, ruled by King Mswati III. The country is known for its colourful cultural traditions, including the annual Umhlanga (Reed Dance) ceremony and the Incwala first fruits festival.`,ET:`Ethiopia is the oldest independent country in Africa and one of the world's oldest nations, having successfully resisted European colonisation by defeating Italy at the Battle of Adwa in 1896. It is the second most populous country in Africa and the most populous landlocked country in the world. Ethiopia is widely considered the birthplace of coffee and is home to some of humanity's earliest known fossil remains, including the famous 'Lucy' skeleton discovered in 1974.`,GA:`Gabon is a Central African country on the Atlantic coast known for its exceptional tropical rainforest, which covers more than 85% of its territory and is home to forest elephants, gorillas, chimpanzees, and the world's largest population of mandrills. The country has significant offshore oil reserves and manganese deposits, making it one of the more prosperous nations in sub-Saharan Africa. Gabon has committed to protecting large portions of its territory in national parks.`,GM:`Gambia is the smallest country on mainland Africa, a narrow strip of land averaging just 50 kilometres wide that runs 300 kilometres along the Gambia River, almost entirely surrounded by Senegal. The Gambia River region was a significant area for the Atlantic slave trade. Today the country is known for its abundant birdlife, attracting birdwatchers from across Europe, and the Kunta Kinteh Island, a UNESCO World Heritage Site connected to the history of slavery.`,GH:`Ghana was the first sub-Saharan African country to gain independence from colonial rule, achieving it in 1957 under Kwame Nkrumah, inspiring independence movements across the continent. Known during the colonial era as the Gold Coast, the country chose the name Ghana after the ancient Ghana Empire. Ghana has developed into one of West Africa's most stable democracies and is a significant producer of gold, cocoa, and increasingly, oil.`,GN:`Guinea is a West African nation on the Atlantic coast, sometimes called Guinea-Conakry to distinguish it from Guinea-Bissau and Equatorial Guinea. It is one of the world's largest producers of bauxite, the ore from which aluminium is refined, and has significant iron ore, gold, and diamond deposits. Despite this mineral wealth, Guinea is one of the world's least developed countries, with most of its population depending on agriculture.`,GW:`Guinea-Bissau is a small West African nation bordering Senegal and Guinea and is one of the world's least developed countries. The country includes the Bijagós Archipelago, a UNESCO biosphere reserve of extraordinary ecological richness, home to saltwater hippopotamuses and rare marine turtles. Guinea-Bissau gained independence from Portugal in 1974 and has experienced significant political instability since.`,KE:`Kenya is a country in East Africa straddling the equator, renowned worldwide for the Maasai Mara ecosystem and the spectacular annual Great Migration of wildebeest and zebra. Nairobi, the capital, is East Africa's largest city and a major hub for international organisations and multinational companies. Kenya has long dominated international long-distance running, producing world record-holders and Olympic champions across distances from the 800 metres to the marathon.`,LS:`Lesotho is a completely landlocked country entirely surrounded by South Africa, one of only three countries in the world with this geography. Known as the 'Kingdom in the Sky,' it is the only country in the world whose entire territory lies above 1,000 metres in elevation, giving it cool temperatures and spectacular mountain scenery. The Basotho people are known for their distinctive woven blankets and conical grass hats called mokorotlo.`,LR:`Liberia is Africa's oldest republic, founded in 1847 by free Black Americans and formerly enslaved people who returned from the United States with the support of the American Colonization Society. This unusual history means Liberia's capital Monrovia is named after US President James Monroe, and the country's flag closely resembles the American flag. Liberia experienced devastating civil wars from 1989 to 2003 but has since made significant progress in rebuilding its institutions.`,LY:`Libya is the fourth-largest country in Africa, situated in North Africa on the Mediterranean coast between Egypt and Tunisia. It has the continent's largest proven oil reserves, discovered in 1959, which transformed the country's economy. Libya was an Italian colonial territory from 1911 and gained independence in 1951. The ancient Roman cities of Leptis Magna and Sabratha on its Mediterranean coast are UNESCO World Heritage Sites of extraordinary grandeur.`,MG:`Madagascar is the world's fourth-largest island, located in the Indian Ocean off the southeastern coast of Africa. It is one of the world's most important biodiversity hotspots, with over 90% of its wildlife found nowhere else on Earth — including all of its lemur species, most of the world's chameleon species, and iconic baobab trees. Madagascar separated from the Indian subcontinent approximately 88 million years ago and was first settled by seafarers from Borneo around 2,000 years ago.`,MW:`Malawi is a small landlocked country in southeastern Africa known as the 'Warm Heart of Africa' for the warmth and friendliness of its people. Lake Malawi, one of Africa's Great Rift Valley lakes, occupies roughly a third of the country's area and contains more species of fish than any other lake on Earth. Despite this ecological richness, Malawi is one of the world's least developed nations with most of the population living in rural areas.`,ML:`Mali is a large landlocked country in West Africa, much of which is covered by the Sahara Desert. It was home to three successive powerful empires — the Ghana, Mali, and Songhai Empires — which were major centres of trans-Saharan trade and Islamic scholarship from the 8th to the 16th centuries. Timbuktu, once one of the world's great centres of Islamic learning, is a UNESCO World Heritage Site in northern Mali.`,MR:`Mauritania is a large country in northwestern Africa, serving as a cultural and geographical bridge between the Arab Maghreb of North Africa and sub-Saharan West Africa. The Sahara Desert covers most of its territory, with most of the population concentrated in the south. Mauritania was the last country in the world to officially abolish slavery, doing so in 1981, though enforcement continues to be a challenge.`,MU:`Mauritius is a small island nation in the Indian Ocean, lying about 2,000 kilometres off the southeastern coast of Africa, with no indigenous human population before Portuguese sailors arrived in 1507. Mauritius was the only known habitat of the dodo, the large flightless bird that became extinct in the late 17th century after human arrival. Today it is known for its diverse culture, pristine beaches, and has developed into one of Africa's higher-income economies through tourism and financial services.`,MA:`Morocco is a country in northwestern Africa at the crossroads of the Arab, Berber, and Mediterranean worlds, separated from Spain by only 14 kilometres at the Strait of Gibraltar. It is home to four UNESCO-listed imperial cities — Fes, Marrakech, Meknès, and Rabat — each with a historic old city of extraordinary character. Morocco's Atlas Mountains, Sahara Desert, Atlantic and Mediterranean coasts make it one of Africa's most geographically and culturally diverse countries.`,MZ:`Mozambique is a country in southeastern Africa with a long Indian Ocean coastline of 2,470 kilometres. It gained independence from Portugal in 1975 after a decade-long independence war, followed by a civil war lasting until 1992. Mozambique has significant natural gas reserves off its northern coast, attracting major international energy investment, and is known for its vibrant music, cuisine, and the historic island of Mozambique, a UNESCO World Heritage Site.`,NA:`Namibia is a southern African country known for the Namib Desert — one of the world's oldest deserts, having been arid for at least 55 million years — from which the country takes its name. It is one of Africa's most sparsely populated countries despite being larger than France. Namibia has spectacular wildlife experiences including the desert-adapted elephants and lions of Damaraland and the vast seal colonies of Cape Cross.`,NE:`Niger is the largest country in West Africa by area, though the vast majority of its territory is covered by the Sahara Desert, with most of the population concentrated in a narrow fertile zone along its southern border. Named after the Niger River that passes through its southwestern corner, the country has significant uranium deposits making it one of the world's top uranium producers. Niger consistently ranks near the very bottom of global human development indices.`,NG:`Nigeria is Africa's most populous country, home to over 200 million people and more than 500 distinct languages and ethnic groups, making it one of the world's most diverse nations. It is Africa's largest economy and a significant oil exporter, with a vibrant creative culture including Nollywood (the world's second-largest film industry by volume) and Afrobeats music that has gained enormous global influence. Nigeria's celebrated writers include Chinua Achebe and Nobel Prize laureate Wole Soyinka.`,RW:`Rwanda is a small, densely populated landlocked country in Central Africa that has undergone an extraordinary transformation following the 1994 genocide, in which approximately 800,000 people were killed in 100 days — one of history's swiftest mass atrocities. In the decades since, Rwanda has achieved remarkable political stability, rapid economic growth, and progressive environmental policies. Kigali, the capital, is consistently rated one of Africa's cleanest, safest, and most organised cities.`,ST:`São Tomé and Príncipe is a small island nation in the Gulf of Guinea and was uninhabited until Portuguese settlement in the 15th century made it one of Africa's first colonial outposts. The islands became a major sugar-producing centre using enslaved labour and were a crucial node in the Atlantic slave trade. Today São Tomé and Príncipe is known for its rich biodiversity, its peaceful transition to multiparty democracy in 1990, and the production of high-quality fine-flavour cacao.`,SN:`Senegal is located on the westernmost tip of the African mainland and is one of West Africa's most stable and long-standing democracies. Known as the 'Gateway to Africa,' its capital Dakar was historically the administrative capital of French West Africa. Senegal's culture is celebrated for its traditional wrestling, its rich griot oral historian tradition, and internationally renowned artists like Youssou N'Dour.`,SC:`Seychelles is an archipelago of 115 islands in the Indian Ocean off East Africa, and is Africa's smallest sovereign country by both area and population. Long uninhabited, it was settled under French rule and later held by Britain before independence in 1976. Today it has the highest GDP per capita in Africa, driven by upmarket tourism and tuna fishing, and is celebrated for its biodiversity — including the giant Aldabra tortoise and the coco de mer palm, which produces the largest seed in the plant kingdom.`,SL:`Sierra Leone is a West African country with a history deeply intertwined with the transatlantic slave trade. Freetown, the capital, was founded in 1787 as a settlement for freed slaves from Britain, the Americas, and Nova Scotia, and its name reflects that founding purpose. The country has extraordinary natural resources including diamonds, titanium, and bauxite, and was severely affected by a civil war from 1991 to 2002.`,SO:`Somalia occupies the Horn of Africa and has the longest coastline in mainland Africa, stretching nearly 3,300 kilometres. Despite having a common language, culture, and religion shared across its population — unusual in a region of great ethnic diversity — Somalia has lacked a functioning central government since 1991 and has experienced prolonged clan-based conflict. Somali culture has a rich tradition of poetry, and the country is sometimes called a 'nation of poets.'`,ZA:`South Africa is the southernmost country in Africa and one of the continent's most economically developed and culturally diverse nations. The country peacefully ended its apartheid system of racial segregation in 1994, holding its first fully democratic elections that year and electing Nelson Mandela as president. South Africa has extraordinary natural diversity spanning the Cape Floristic Region, Kruger National Park, and the Drakensberg Mountains, and is the only country to have voluntarily dismantled its nuclear weapons programme.`,SS:`South Sudan is the world's newest internationally recognised country, gaining independence from Sudan in July 2011 following a 2005 peace agreement and a referendum in which 98.83% voted for independence. Despite significant oil reserves, it is one of the world's least developed nations and was quickly embroiled in a devastating civil war starting in 2013. Juba, the capital, sits on the Nile River and is a rapidly growing frontier city.`,SD:`Sudan is the third-largest country in Africa and was the continent's largest until South Sudan seceded in 2011. Located in northeastern Africa, Sudan is home to more ancient pyramids than Egypt — the Nubian kingdoms at Meroe, Nuri, and El-Kurru have hundreds of smaller, steeper pyramids scattered across the desert. Sudan gained independence from British-Egyptian rule in 1956 and the Nile flows through the country from south to north.`,TZ:`Tanzania is East Africa's largest country and home to some of the continent's most iconic landscapes and wildlife. Mount Kilimanjaro, Africa's highest peak, the Serengeti's annual wildebeest migration, and the Ngorongoro Crater are all within its borders. The semi-autonomous archipelago of Zanzibar, once a powerful independent sultanate and centre of the Indian Ocean spice trade, merged with mainland Tanganyika to form Tanzania in 1964.`,TG:`Togo is one of Africa's narrowest nations, stretching from the Gulf of Guinea in the south to Burkina Faso in the north. It was a German protectorate before being divided between France and Britain after World War I, with the French portion becoming independent Togo in 1960. Lomé, the capital, sits on the Atlantic coast and is known as one of West Africa's more pleasant and accessible cities.`,TN:`Tunisia is the northernmost country in Africa, where the continent reaches closest to Europe with just 140 kilometres separating it from the Italian island of Sicily. The ancient Carthaginian civilisation, a rival of Rome, was centred near modern-day Tunis. Tunisia was the birthplace of the Arab Spring in late 2010, when protests sparked a wave of revolutionary movements that spread across the Arab world.`,UG:`Uganda is a landlocked East African country known as the 'Pearl of Africa' for its extraordinary natural beauty and biodiversity. The country is home to approximately half of the world's remaining mountain gorillas, and the source of the Nile River is at the northern end of Lake Victoria within Uganda. Kampala, the capital, is a rapidly growing city built across multiple hills and is one of East Africa's most dynamic urban centres.`,ZM:`Zambia is a landlocked country in southern Africa, formerly known as Northern Rhodesia, which gained independence from Britain in 1964. It is named after the Zambezi River, one of Africa's great rivers and the site of Victoria Falls on the Zambia-Zimbabwe border — one of the world's most spectacular waterfalls. Zambia is a significant copper producer, and the Copperbelt region in the north was historically one of the world's richest copper deposits.`,ZW:`Zimbabwe is a landlocked country in southern Africa home to the ruins of Great Zimbabwe, a medieval stone city that at its peak housed up to 18,000 people and gave the country its name. Victoria Falls, shared with Zambia and one of the Seven Natural Wonders of the World, lies on its northwestern border. Once the 'breadbasket of Africa' for its agricultural productivity, Zimbabwe experienced severe economic difficulties in the 2000s and has been in a period of recovery since.`,AF:`Afghanistan is a landlocked country at the crossroads of Central and South Asia, bordered by Pakistan, Iran, Turkmenistan, Uzbekistan, Tajikistan, and China. It has been at the centre of geopolitical competition for centuries, often described as the 'Graveyard of Empires' for the many foreign powers who have attempted to subdue it. Afghanistan has extraordinary untapped mineral deposits including the world's largest known lithium reserves along with significant iron, copper, gold, and rare earth minerals.`,AM:`Armenia is a small landlocked country in the South Caucasus with one of the world's oldest continuous civilisations, and was the first country in the world to adopt Christianity as its state religion, in 301 AD. The country is home to some of the world's earliest Christian churches and monasteries, including Etchmiadzin Cathedral, and has a 6,000-year winemaking tradition evidenced by archaeological finds. Armenia has a deep cultural identity shaped significantly by the Armenian Genocide of 1915.`,AZ:`Azerbaijan is a South Caucasian country bordering the Caspian Sea, Georgia, Russia, Iran, and Armenia, and is one of the oldest oil-producing regions in the world, with records of oil collection dating to the 10th century. Baku, the capital, is known for its striking contrast of medieval walls and winding old city lanes alongside futuristic modern architecture including the flame-shaped Flame Towers. The country is also home to Yanar Dag ('Burning Mountain'), a natural gas seep that has burned continuously for centuries.`,BD:`Bangladesh is a South Asian country almost entirely surrounded by India, with a small border with Myanmar, and is one of the world's most densely populated countries, with around 170 million people in an area smaller than Greece. It achieved independence from Pakistan in 1971 following a liberation war. Bangladesh is the world's second-largest garment exporter and has made remarkable progress in poverty reduction, women's education, and reducing child mortality.`,BT:`Bhutan is a small Himalayan Buddhist kingdom between India and China, known for its unique philosophy of measuring national progress through 'Gross National Happiness' rather than purely economic indicators. It was the last country in the world to introduce television and the internet, doing so in 1999 and 2000 respectively. Bhutan is entirely carbon negative, absorbing far more carbon dioxide than it produces due to its vast protected forests, and conservation is central to national policy.`,BN:`Brunei is a small, wealthy sultanate on the island of Borneo in Southeast Asia, entirely surrounded by Malaysia except for its South China Sea coastline. It has one of the highest per-capita incomes in the world due to its substantial oil and natural gas reserves, and is governed by Sultan Hassanal Bolkiah, one of the world's longest-reigning monarchs. Brunei maintains Islamic law alongside civil law and is one of the few remaining absolute monarchies.`,KH:`Cambodia is a Southeast Asian country home to Angkor Wat, the world's largest religious monument, a 12th-century Hindu temple complex later converted to Buddhism. The country suffered the devastating Khmer Rouge genocide from 1975 to 1979, during which an estimated 1.7 to 2.5 million people — roughly a quarter of the population — died from execution, starvation, disease, and forced labour. Cambodia has since rebuilt significantly and attracts millions of tourists to the magnificent temples of Angkor.`,CN:`China is the world's most populous country and has the world's second-largest economy, home to one of history's longest continuous civilisations spanning over 5,000 years. The Great Wall, the Terracotta Army, the Forbidden City, and the Li River karst landscape are among its most iconic landmarks. China's 'Four Great Inventions' — paper, printing, gunpowder, and the compass — transformed human civilisation worldwide, and the country has been a centre of philosophical, scientific, and artistic achievement throughout recorded history.`,GE:`Georgia is a country at the crossroads of Eastern Europe and Western Asia in the South Caucasus, bordered by Russia, Turkey, Armenia, and Azerbaijan. It is one of the world's oldest winemaking regions, with an 8,000-year tradition of fermenting wine in clay vessels called qvevri buried underground. Georgia adopted Christianity as its state religion in the 4th century AD and has one of the world's oldest and most distinctive alphabets, the Georgian script, dating to at least the 5th century.`,IN:`India is the world's most populous country, home to one of history's oldest civilisations and extraordinary diversity in language, religion, culture, and geography — it has 22 officially recognised languages and hundreds more spoken across the subcontinent. It is the birthplace of four major world religions: Hinduism, Buddhism, Jainism, and Sikhism. India has the world's largest film industry by number of productions and has made fundamental contributions to mathematics, astronomy, medicine, and philosophy throughout history.`,ID:`Indonesia is the world's largest archipelago nation, consisting of more than 17,000 islands and home to the world's fourth-largest population. It spans a vast area straddling the equator in Southeast Asia and has extraordinary biodiversity including orangutans, Komodo dragons, Sumatran tigers, and pygmy elephants. Indonesia has the world's largest Muslim population while maintaining a pluralistic, secular constitution, and is home to a remarkable diversity of more than 700 languages.`,JP:`Japan is an island nation in the Pacific Ocean comprising four main islands plus more than 6,800 smaller ones, home to a society that uniquely blends ancient traditions with cutting-edge modernity. The Japanese imperial dynasty traces an unbroken lineage for over 2,600 years, making it the world's oldest hereditary monarchy. Japan is famous for its cherry blossom festivals, tea ceremony, manga and anime, sushi, precision engineering, and has made profound contributions to global culture, design, and technology.`,KZ:`Kazakhstan is the world's largest landlocked country, a vast Central Asian nation spanning parts of both Europe and Asia, larger than Western Europe combined. It was the last Soviet republic to declare independence in 1991 and has significant oil, natural gas, and mineral deposits that have driven rapid economic development. Astana, the purpose-built capital relocated in 1997, features striking futuristic architecture rising from the Kazakh steppe.`,KG:`Kyrgyzstan is a small, mountainous Central Asian country where more than 90% of the territory lies above 1,500 metres in elevation. It is known for its spectacular alpine scenery, nomadic heritage, and one of the world's longest epic poems — the Manas — which runs to approximately 500,000 lines and is still recited by professional storytellers. Kyrgyzstan hosts the World Nomad Games, a biennial celebration of traditional nomadic sports and culture from across Central Asia.`,LA:`Laos is the only landlocked country in Southeast Asia and one of the world's few remaining single-party communist states. During the Vietnam War era, Laos was the most heavily bombed country per capita in history, with over 2 million tonnes of ordnance dropped between 1964 and 1973. Despite this history, modern Laos is known for its Buddhist temple culture, the Mekong River, and the charming UNESCO-listed ancient capital Luang Prabang.`,MY:`Malaysia is a Southeast Asian country consisting of two distinct regions separated by the South China Sea — Peninsular Malaysia (bordering Thailand) and Malaysian Borneo. It is a multicultural melting pot of Malay, Chinese, Indian, and indigenous cultures, reflected in its extraordinarily diverse food, festivals, and languages. The Petronas Twin Towers in Kuala Lumpur were the world's tallest buildings from 1998 to 2004 and remain iconic symbols of Malaysia's rapid development.`,MV:`The Maldives is an archipelago nation in the Indian Ocean south of India, consisting of 26 coral atolls and more than 1,000 individual coral islands. It is the world's lowest-lying country, with an average ground elevation of just 1.5 metres above sea level, making it acutely vulnerable to rising sea levels caused by climate change. The Maldives has developed a successful tourism economy centred on its legendary overwater bungalows, crystal-clear lagoons, and exceptional marine biodiversity.`,MN:`Mongolia is a vast landlocked country in East Asia between Russia and China, and is the world's most sparsely populated sovereign state, with only about 3.3 million people spread across an area nearly four times the size of France. It was the centre of the Mongol Empire under Genghis Khan in the 13th century, the largest contiguous land empire in history. A significant portion of Mongolia's population still maintains a semi-nomadic lifestyle, living seasonally in traditional portable dwellings called gers.`,MM:`Myanmar (also known as Burma) is a Southeast Asian country with remarkable ethnic and cultural diversity, home to more than 135 distinct ethnic groups. Its ancient city of Bagan contains over 2,000 Buddhist temples, pagodas, and monasteries spread across 40 square kilometres, one of Asia's most extraordinary archaeological landscapes. Myanmar has a deeply complex modern political history and is navigating significant internal challenges.`,NP:`Nepal is a small Himalayan country between India and China, home to eight of the world's ten highest mountain peaks, including Mount Everest at 8,849 metres. It is the birthplace of Siddhartha Gautama, the historical Buddha, born in Lumbini around 563 BCE. Despite being one of Asia's poorest nations, Nepal attracts hundreds of thousands of trekkers and mountaineers every year drawn by its extraordinary Himalayan landscapes and spiritual heritage.`,KP:`North Korea (the Democratic People's Republic of Korea) occupies the northern half of the Korean Peninsula and operates as one of the world's most isolated and secretive states, governed by a single family dynasty — the Kim family — since its founding. The country declared itself a nuclear weapons state in 2005 and maintains one of the world's largest standing armies. Despite its isolation, North Korea has ancient Buddhist temples, the Paektu Mountain crater lake, and a highly developed domestic cultural tradition.`,PK:`Pakistan is a South Asian country created from British India in 1947 as a homeland for South Asian Muslims during Partition. It is the world's second-most populous Muslim-majority country and has a complex ethnic tapestry including Punjabis, Pashtuns, Sindhis, and Baloch peoples. Pakistan is home to K2 (the world's second-highest mountain), the ancient Indus Valley city of Mohenjo-daro, and some of the most spectacular mountain scenery on Earth in the Karakoram and Hindu Kush ranges.`,PH:`The Philippines is a Southeast Asian archipelago of more than 7,100 islands, named after King Philip II of Spain, reflecting more than 300 years of Spanish colonial rule that ended in 1898. It is the world's third-largest English-speaking country and has a culture uniquely blending indigenous, Malay, Spanish, and American influences. The Philippines has extraordinary marine biodiversity, with Palawan and the Tubbataha Reef sitting within the Coral Triangle, the global centre of marine biodiversity.`,SG:`Singapore is a city-state and island nation at the southern tip of the Malay Peninsula, one of the world's most prosperous countries and a major global hub for finance, trade, aviation, and logistics. Despite having no natural resources, Singapore has built a remarkable economy through strategic port management, manufacturing, and financial services. It is the world's most densely populated country after Monaco, with a population of around 5.8 million in just 733 square kilometres.`,LK:`Sri Lanka is a teardrop-shaped island nation in the Indian Ocean off the southern tip of India, known as the 'Pearl of the Indian Ocean.' It has one of the oldest documented histories in Asia, with a continuous chronicle of rulers dating to the 6th century BCE. Sri Lanka is the world's leading exporter of Ceylon tea and has a rich Buddhist heritage with ancient cities such as Anuradhapura and Polonnaruwa, both UNESCO World Heritage Sites.`,KR:`South Korea occupies the southern portion of the Korean Peninsula and has achieved one of the most dramatic economic transformations in history, going from one of the world's poorest nations after the 1950-53 Korean War to a high-income, technologically advanced society in a single generation. It is home to globally recognised companies including Samsung, LG, Hyundai, and Kia. South Korean pop culture — K-pop, K-drama, and films such as the Oscar-winning Parasite — has achieved extraordinary global reach.`,TJ:`Tajikistan is the smallest country in Central Asia by area yet has the highest proportion of mountainous territory, with more than 93% covered by mountains including the Pamir range — often called the 'Roof of the World.' It is the poorest of the former Soviet Central Asian republics. Tajikistan is the only Persian-speaking country in Central Asia and has heritage closely tied to ancient Persian civilisation; the Sogdian people, ancestors of modern Tajiks, played a major role on the Silk Road.`,TH:`Thailand is a Southeast Asian country known as the 'Land of Smiles' and is the only country in mainland Southeast Asia never to have been colonised by a European power. Bangkok, the capital, is one of the world's most visited cities, known for its ornate temples, vibrant street food culture, and famous floating markets. Thailand is a constitutional monarchy where the king holds deep cultural reverence, and has a strong Theravada Buddhist tradition.`,TW:`Taiwan, officially the Republic of China, is an island state off the southeast coast of mainland China. The ROC government relocated to Taiwan in 1949 after losing the Chinese Civil War, and the island has since grown into a prosperous, high-tech democracy. Its political status is disputed — the People's Republic of China claims it as a province — but it functions as a self-governing state with its own military, currency and elections. Taiwan is the world's leading producer of advanced semiconductors and is known for its night markets, dramatic mountain scenery and vibrant civil society.`,TL:`Timor-Leste (East Timor) is one of the world's newest countries, gaining independence in 2002 after 24 years of Indonesian occupation following Portugal's withdrawal from its former colony. Located on the eastern half of the island of Timor in Southeast Asia, it is one of only two predominantly Roman Catholic nations in Asia. Timor-Leste has significant offshore oil and gas reserves and is home to remarkable coral reef systems in the Coral Triangle.`,TM:`Turkmenistan is a Central Asian country bordered by Kazakhstan, Uzbekistan, Afghanistan, Iran, and the Caspian Sea, and is one of the world's most isolated and authoritarian states. It holds the world's fourth-largest natural gas reserves and uses this wealth to provide heavily subsidised utilities and fuel to citizens. The country is home to the Darvaza gas crater — a natural gas field that was set alight in 1971 and continues to burn today, nicknamed the 'Door to Hell.'`,UZ:`Uzbekistan is a double-landlocked Central Asian country that was the heartland of the ancient Silk Road, the trade network connecting China to the Mediterranean world. Cities like Samarkand and Bukhara were among the medieval world's greatest centres of Islamic scholarship, architecture, and commerce, with breathtaking tilework that rivals anything on Earth. Uzbekistan is also the birthplace of medieval mathematician al-Khwarizmi, from whose name the word 'algorithm' is ultimately derived.`,VN:`Vietnam is a Southeast Asian country stretching 1,650 kilometres along the eastern Indochinese Peninsula with an extraordinarily long and varied coastline. Despite centuries of Chinese rule, French colonisation, and a devastating war with American involvement that ended in 1975, Vietnam has maintained a strong and distinct cultural identity. Since the Doi Moi economic reforms of 1986, Vietnam has become one of Asia's fastest-growing economies, transforming from an agricultural society to a major manufacturing and export hub.`,BH:`Bahrain is a small island nation in the Persian Gulf and was the first country in the Gulf to discover and export oil, in 1932. It was the site of the ancient Dilmun civilisation, one of the ancient world's great trading centres, and has been a regional hub for commerce and pearl diving for thousands of years. Bahrain is considered the most socially liberal of the Gulf monarchies and has a cosmopolitan, diverse population.`,IR:`Iran, historically known as Persia, is home to one of the world's oldest continuous civilisations with a history spanning more than 5,000 years, including some of antiquity's greatest empires such as the Achaemenid Empire under Cyrus the Great. It is the world's largest Shia Muslim-majority country and has 27 UNESCO World Heritage Sites including Persepolis, the ceremonial capital of the ancient Persian Empire. Iran holds the world's second-largest natural gas reserves and fourth-largest oil reserves.`,IQ:`Iraq is located in the Fertile Crescent of western Asia, in the region of ancient Mesopotamia — the 'land between the rivers' of the Tigris and Euphrates — widely regarded as the birthplace of civilisation, where writing, codified law, agriculture, and the world's first cities all emerged. The ancient city of Babylon was one of the ancient world's most magnificent metropolises. Iraq holds the world's fifth-largest proven oil reserves and has extraordinary archaeological heritage including the ancient Sumerian city of Ur.`,IL:`Israel is a small Middle Eastern country on the eastern shore of the Mediterranean Sea, established in 1948 as the world's only Jewish-majority state and the historical homeland of the Jewish people. Jerusalem, its proclaimed capital, is one of the world's oldest continuously inhabited cities and is sacred to Judaism, Christianity, and Islam. Israel has developed one of the world's most innovative technology sectors, often called 'Silicon Wadi,' with more startup companies per capita than almost any other nation.`,JO:`Jordan is a small Arab kingdom in the heart of the Middle East, home to Petra — the ancient Nabataean city carved into rose-red sandstone cliffs — one of the world's most spectacular archaeological sites and one of the New Seven Wonders of the World. The Dead Sea on Jordan's western border is the lowest point on Earth's surface at 430 metres below sea level, and its hypersaline waters allow bathers to float effortlessly. Jordan has been a relatively stable centre in a volatile region and hosts millions of refugees.`,KW:`Kuwait is a small emirate in the northwestern Persian Gulf with the world's sixth-largest proven oil reserves. It was occupied by Iraq in 1990 and liberated by a US-led coalition in the 1991 Gulf War, an event that shaped modern Middle Eastern geopolitics. Kuwait has used its oil wealth to develop generous social services for its citizens, including free healthcare, education, and no personal income tax.`,LB:`Lebanon is a small country on the eastern Mediterranean coast with an extraordinarily diverse cultural heritage shaped by Phoenician, Greek, Roman, Arab, Crusader, Ottoman, and French influences. Once called the 'Switzerland of the Middle East' for its banking sector and cosmopolitan lifestyle, Beirut was a major regional cultural and commercial centre. Lebanon is home to the ancient cedars of Lebanon, celebrated in the Bible and depicted prominently on the national flag and coat of arms.`,OM:`Oman is located on the southeastern corner of the Arabian Peninsula with coastlines on the Arabian Sea and Gulf of Oman, and is one of the oldest independent states in the Arab world with a seafaring and trading tradition stretching back 5,000 years. The Sultan of Oman has historically pursued a carefully balanced foreign policy, maintaining good relations across regional political divides. Oman is known for its beautiful wadis, ancient forts, and frankincense production from the southern Dhofar region.`,PS:`Palestine refers to the Palestinian territories of the West Bank and the Gaza Strip, home to a population of around 5 million Palestinians. The region has deep historical and religious significance to Judaism, Christianity, and Islam — Jerusalem contains some of the most sacred sites for all three faiths. The Palestinian Authority, established following the 1993 Oslo Accords, exercises limited self-governance in parts of the West Bank.`,QA:`Qatar is a small peninsula in the Persian Gulf with the world's highest per-capita income, driven by its enormous natural gas reserves — the world's third-largest. It is home to Al Jazeera, one of the world's most widely watched international news networks, launched in 1996. Qatar hosted the 2022 FIFA World Cup, becoming the first Arab and Muslim-majority country to host the tournament, a milestone of major cultural significance.`,SA:`Saudi Arabia is the largest country in the Middle East and the birthplace of Islam, home to its two holiest cities — Mecca and Medina — which together receive around 15 million Muslim pilgrims annually for the Hajj and Umrah. The country holds the world's second-largest proven oil reserves and is the world's largest oil exporter, making it a central player in global energy markets. Saudi Arabia is governed as an absolute monarchy by the Al Saud royal family and is undergoing significant social and economic reform.`,SY:`Syria is one of the oldest inhabited regions in the world, home to some of humanity's earliest permanent settlements, and Damascus is often cited as the world's oldest continuously inhabited city. The country has extraordinary historical heritage, including the ancient cities of Aleppo, Palmyra, and Bosra, all UNESCO World Heritage Sites. Syria experienced a devastating civil war beginning in 2011 that caused immense destruction to its people and to irreplaceable archaeological sites.`,TR:`Turkey is a transcontinental country bridging Europe and Asia, with most of its territory on the Anatolian Peninsula. Istanbul, its largest city, was historically known as Constantinople and served as the imperial capital of both the Byzantine and Ottoman Empires for over a millennium. Turkey is home to extraordinary natural and archaeological wonders including Cappadocia's surreal rock formations, the ancient Greek city of Ephesus, and the Hagia Sophia.`,AE:`The United Arab Emirates is a federation of seven emirates on the southeastern Arabian Peninsula that has transformed from a collection of small fishing and pearl-diving communities into one of the world's wealthiest nations in barely five decades, driven by oil revenues and economic diversification. Dubai is home to the Burj Khalifa, the world's tallest building, and has become a global hub for aviation, finance, tourism, and international business. Abu Dhabi, the capital emirate, holds the majority of the federation's oil wealth.`,YE:`Yemen is located at the southern tip of the Arabian Peninsula where the Red Sea meets the Gulf of Aden, and is home to some of the Arabian Peninsula's oldest human settlements. The ancient city of Sana'a, the capital, features distinctive tower houses decorated with geometric plasterwork and is a UNESCO World Heritage Site. Yemen is one of the Arab world's poorest nations and the island of Socotra — part of Yemen — is sometimes called the 'Galápagos of the Indian Ocean' for its extraordinary endemic biodiversity.`,AG:`Antigua and Barbuda is a twin-island Caribbean nation known for its 365 beaches — one for each day of the year — and for hosting Antigua Sailing Week, one of the world's most celebrated regattas. The island of Antigua was a major British Royal Navy base in the 18th century, with English Harbour preserving the historic dockyard where Admiral Horatio Nelson was stationed. The country gained independence from Britain in 1981.`,AR:`Argentina is the second-largest country in South America, stretching from the subtropical north down to sub-Antarctic Patagonia and Cape Horn. Buenos Aires, the capital, is a cosmopolitan city strongly influenced by European immigration and known for its tango music and dance, vibrant cultural scene, and world-class restaurants. Argentina has won the FIFA World Cup three times and produced celebrated writers including Jorge Luis Borges.`,BS:`The Bahamas is an archipelago of about 700 islands and 2,400 cays in the Atlantic Ocean north of Cuba, and is the site of Christopher Columbus's first landfall in the Americas on October 12, 1492. Today the Bahamas is one of the Caribbean's most prosperous nations, with tourism and offshore financial services as its main economic pillars. Its turquoise waters, coral reefs, and marine life make it a world-class scuba diving and sailing destination.`,BB:`Barbados is the easternmost island in the Caribbean and is widely credited as the birthplace of rum — production from molasses began on Barbadian sugar plantations in the 17th century. The island was continuously under British rule from 1625 until independence in 1966, making it one of the most stable British colonial territories. In 2021, Barbados transitioned from a constitutional monarchy to a republic, with Rihanna — its most famous daughter — named a National Hero.`,BZ:`Belize is the only English-speaking country in Central America and has extraordinary natural and cultural heritage. The Mesoamerican Barrier Reef, the second-longest coral reef in the world, runs along its entire Caribbean coastline. Belize also contains a remarkable concentration of ancient Maya sites scattered throughout its jungles, including the great city of Caracol, and gained independence from Britain (as British Honduras) in 1981.`,BO:`Bolivia is a landlocked South American country with one of the world's highest and most isolated seats of government — La Paz, the administrative capital, sits at over 3,600 metres above sea level. The country has the world's largest salt flat, Salar de Uyuni (10,582 sq km), which becomes the world's largest natural mirror when flooded with a thin film of water. Bolivia also holds the world's largest known lithium reserves, a resource critical for electric vehicle batteries.`,BR:`Brazil is the largest country in South America and the fifth-largest in the world, home to the Amazon Rainforest — the world's largest tropical rainforest — which contains roughly 10% of all species on Earth. Brazil has one of the world's most diverse populations, shaped by Indigenous, African, Portuguese, and subsequent immigrant heritage from around the world. It is renowned for its Carnival festival, passionate football culture, and the music genres of samba and bossa nova.`,CA:`Canada is the second-largest country in the world by total area, spanning six time zones from the Atlantic to the Pacific to the Arctic Ocean. It is a bilingual nation with English and French as official languages, reflecting its complex colonial history and the distinct heritage of its Francophone population, particularly in Quebec. Canada is known for its vast and diverse natural landscapes, multicultural cities, and a universal healthcare system.`,CL:`Chile is a long, narrow country stretching approximately 4,300 kilometres along South America's western coast, from the world's driest non-polar desert in the north to Patagonian glaciers and Cape Horn in the south. The Atacama Desert in northern Chile is so dry that in some areas no rainfall has ever been recorded. Easter Island (Rapa Nui), famous for its mysterious moai statues carved by the Rapa Nui people, is a Chilean Pacific territory.`,CO:`Colombia is the only South American country with coastlines on both the Caribbean Sea and the Pacific Ocean, situated in the continent's northwestern corner. It is the world's top producer of emeralds, supplying around 90% of the global supply, and also produces significant coal, oil, and the world-famous Colombian coffee. Colombia has more bird species (over 1,900) than any other country on Earth, making it a premier destination for birdwatchers.`,CR:`Costa Rica is a Central American country celebrated for its pioneering environmental policies and extraordinary biodiversity, protecting more than 25% of its territory in national parks, wildlife refuges, and biological reserves. It abolished its military in 1948 and has since channelled resources into education and healthcare. Costa Rica generates the vast majority of its electricity from renewable sources, primarily hydropower, wind, and geothermal energy from its chain of active volcanoes.`,CU:`Cuba is the largest island in the Caribbean Sea, known internationally for its preserved classic American cars from the 1950s, hand-rolled cigars, rum, and vibrant music and dance traditions including salsa, son cubano, and mambo. The country has been governed by a communist government since the Cuban Revolution of 1959. Despite economic challenges, Cuba has an unusually high number of doctors per capita and has developed a significant pharmaceutical and medical biotechnology sector.`,DM:`Dominica is known as the 'Nature Isle of the Caribbean' for its lush, volcanic landscape, hot springs, and some of the last well-preserved primary rainforest in the Eastern Caribbean. Not to be confused with the Dominican Republic, Dominica is home to the Kalinago people — the last pre-Columbian indigenous community in the Eastern Caribbean — who maintain their own territory on the island's eastern coast. The island has a growing eco-tourism industry.`,DO:`The Dominican Republic shares the island of Hispaniola with Haiti and was the site of the first permanent European settlement in the Americas, established by Bartholomew Columbus in 1496. It is the most visited country in the Caribbean, with large resort areas along its northern and eastern coasts. Santo Domingo is home to the Cathedral of Santa María la Menor (1512), the oldest cathedral in the Americas.`,EC:`Ecuador is a small country on South America's northwestern coast named after the equator that runs through its territory. It is considered one of the world's most biodiverse countries by land area, and the Galápagos Islands — an Ecuadorian archipelago 1,000 kilometres offshore — are where Charles Darwin developed key insights that led to his theory of natural selection. Ecuador was the first country to enshrine the legal rights of nature in its national constitution, in 2008.`,SV:`El Salvador is the smallest and most densely populated country in Central America and the only one without a Caribbean coastline. It is known for its surf culture along the Pacific coast, the ancient Maya city of Joya de Cerén (preserved by volcanic ash and called the 'Pompeii of the Americas'), and its chain of active volcanoes. El Salvador became the first country in the world to adopt Bitcoin as legal tender in 2021.`,GD:`Grenada, the 'Spice Isle,' is the world's second-largest producer of nutmeg and mace after Indonesia, along with cinnamon, cloves, and ginger. This small Caribbean island gained independence from Britain in 1974. St George's, the capital, with its horseshoe-shaped harbour ringed by colourful colonial buildings and overlooked by a French fort, is widely considered one of the most beautiful harbour towns in the Caribbean.`,GT:`Guatemala is the most populous country in Central America and was the heartland of the ancient Maya civilisation, which built cities with sophisticated astronomical observatories and developed one of the few fully developed writing systems in the pre-Columbian Americas. The ancient Maya calendar, developed in Guatemala, attracted global attention in 2012. The colonial capital Antigua Guatemala is a UNESCO World Heritage Site.`,GY:`Guyana is the only English-speaking country in South America, sharing borders with Venezuela, Brazil, and Suriname, and was formerly British Guiana before independence in 1966. More than 80% of its territory is covered by tropical rainforest, among the most intact in South America. The discovery of major offshore oil reserves in 2015 has made Guyana one of the world's fastest-growing economies.`,HT:`Haiti occupies the western third of Hispaniola in the Caribbean and in 1804 became the first Black republic in the world and the first nation established through a successful slave revolt — the Haitian Revolution inspired abolitionists worldwide. Haiti has a rich culture deeply connected to West African traditions, with Haitian Creole spoken nationwide and Vodou practised alongside Roman Catholicism. Despite significant challenges, it has a vibrant artistic tradition including internationally recognised painting and sculpture.`,HN:`Honduras is a Central American country with coastlines on the Caribbean Sea and the Pacific, home to Copán — one of the most important archaeological sites of the ancient Maya, known for its elaborately carved stelae and hieroglyphic stairway. The Bay Islands off the Caribbean coast are renowned for scuba diving due to their position on the Mesoamerican Barrier Reef. Honduras is one of Central America's most biodiverse countries.`,JM:`Jamaica is a small Caribbean island that has had a cultural influence on the world far exceeding its size. It is the birthplace of reggae music, popularised globally by Bob Marley, and of Rastafarianism. Jamaica has produced some of history's greatest sprinters, including Usain Bolt who set world records at the 2009 World Championships, and gained independence from Britain in 1962. The island is known for its Blue Mountains, vibrant markets, and jerk cuisine.`,MX:`Mexico is one of the world's largest countries by area, located in southern North America, and Mexico City — built on the ancient Aztec capital Tenochtitlan — is one of the Western Hemisphere's largest and most historic cities. Mexico was the centre of major pre-Columbian civilisations including the Aztec and Maya empires, and today is the world's largest silver producer. Its culinary tradition has been recognised by UNESCO as Intangible Cultural Heritage of Humanity.`,NI:`Nicaragua is the largest country in Central America by area, known as the 'Land of Lakes and Volcanoes' for its dramatic landscape. Lake Nicaragua contains freshwater sharks, which adapted from the ocean over thousands of years as the lake's ancient Pacific connection closed. Nicaragua gained independence from Spain in 1821 and was the site of significant revolutionary conflict in the late 1970s and 1980s.`,PA:`Panama is located at the narrow isthmus connecting North and South America and is home to the Panama Canal, one of the world's most important engineering achievements, connecting the Pacific and Atlantic Oceans and handling around 5% of global trade. The canal was completed in 1914 and transferred to Panamanian sovereignty in 1999. Panama has extraordinary biodiversity, with more bird species than the continental United States and Canada combined.`,PY:`Paraguay is a landlocked South American country bordered by Argentina, Brazil, and Bolivia, and is one of only two landlocked countries on the continent. Despite its landlocked status, it is a major electricity exporter from the Itaipú Dam, one of the world's largest hydroelectric power plants. Paraguay is notable for being the only country in the Americas where an indigenous language, Guaraní, is an official language alongside Spanish and is widely spoken by the majority of the population.`,PE:`Peru is located in western South America and was the centre of the Inca Empire, the largest empire in pre-Columbian America, which at its peak stretched from present-day Colombia to Chile. Machu Picchu, the 15th-century Inca citadel perched at 2,430 metres in the Andes, is one of the world's most visited and photographed archaeological sites. Peru has extraordinary ecological diversity spanning the Andes mountains, the Amazon jungle (covering over 60% of the country), and a coastal desert.`,KN:`Saint Kitts and Nevis is the smallest sovereign state in the Western Hemisphere by both area and population, a twin-island Caribbean nation in the Lesser Antilles. Saint Kitts was Britain's first Caribbean colony, established in 1623, and served as the base for subsequent colonisation of other islands. The island gained independence in 1983 and Brimstone Hill Fortress — a UNESCO World Heritage Site — stands as an impressive reminder of the colonial era.`,LC:`Saint Lucia is a Caribbean island nation sometimes called 'Helen of the West Indies' because it was fought over so intensely that it changed hands between Britain and France fourteen times. The Pitons — two dramatic volcanic spires rising from the sea on the island's southwestern coast — are a UNESCO World Heritage Site. Saint Lucia is known for its rum production, jazz festival, and one of the highest densities of Nobel Prize winners per capita of any country in the world.`,VC:`Saint Vincent and the Grenadines is a Caribbean island nation consisting of the main island of Saint Vincent and 32 smaller Grenadine islands and cays. The Grenadines — including Bequia and the Tobago Cays — are among the Caribbean's most sought-after sailing destinations. Saint Vincent is home to La Soufrière, an active volcano that erupted dramatically in 2021, and is one of the Caribbean's leading producers of arrowroot.`,SR:`Suriname is the smallest sovereign country in South America by area and the only South American country where Dutch is the official language, a legacy of its colonial history as Dutch Guiana. More than 90% of its territory is covered by tropical rainforest, one of the most intact such ecosystems in the world. Paramaribo, the capital, has a historic inner city of Dutch colonial wooden architecture that is a UNESCO World Heritage Site.`,TT:`Trinidad and Tobago is a twin-island Caribbean nation just off the northeastern coast of Venezuela and is the birthplace of two distinctive cultural contributions. Trinidad is the origin of the steelpan, the national instrument developed in the early 20th century from oil drums. It is also the birthplace of Caribbean Carnival as it developed, with Trinidad's annual Carnival renowned worldwide for its elaborate masquerade bands and calypso and soca music.`,US:`The United States of America is the world's third-largest country by area and third-most-populous, a federal republic of 50 states that declared independence from Britain in 1776. It has been the world's largest economy for over a century and has dominated global political, military, and cultural influence in the modern era. The United States has made profound contributions to global science, technology, literature, music, and film, and hosts the world's most prestigious universities and research institutions.`,UY:`Uruguay is the second-smallest country in South America and is consistently ranked as Latin America's most democratic, transparent, and socially progressive nation. It was the first country in Latin America to legalise same-sex marriage (2013) and the first in the world to fully legalise recreational cannabis (2013). Uruguay has a strong tradition of public education dating to the 19th century and a high level of human development relative to its regional neighbours.`,VE:`Venezuela is located on the northern coast of South America and has the world's largest proven oil reserves, though managing this wealth has been a central challenge throughout its modern history. The country is home to Angel Falls (Salto Ángel), the world's highest uninterrupted waterfall at 979 metres, located in the Canaima National Park in the tepui highlands. Venezuela has an extraordinary ecological range encompassing the Andes, the Orinoco River delta, Caribbean beaches, and the unique table-top tepui mountains.`,AU:`Australia is the world's sixth-largest country by area and the only nation that governs an entire continent, a vast land with ecological diversity from tropical rainforests to scorching deserts to temperate forests. It is home to unique wildlife found nowhere else, including kangaroos, koalas, platypuses, wombats, and the world's two egg-laying mammals. The Great Barrier Reef, stretching 2,300 kilometres along the Queensland coast, is the world's largest coral reef system.`,FJ:`Fiji is a South Pacific archipelago of more than 330 islands, of which about 110 are permanently inhabited, located northeast of New Zealand. The country is known for its crystal-clear lagoons, vibrant coral reefs, and a culture of warm hospitality centred around the greeting 'bula' (life, health, and happiness). Fiji has a diverse population of indigenous Fijians and Indo-Fijians descended from labourers brought by British colonial authorities, and has been independent since 1970.`,KI:`Kiribati (pronounced 'Kiribas') is a Pacific island nation spanning three island groups across the central Pacific and is the world's only country to straddle all four hemispheres — north, south, east, and west. Its 33 atolls and one raised coral island are spread across an ocean area larger than India. Kiribati faces an existential threat from rising sea levels, with most of its land just one to two metres above sea level.`,MH:`The Marshall Islands is an archipelago of 1,156 islands and islets in the central Pacific and was the site of multiple US nuclear weapons tests from 1946 to 1958, including the Castle Bravo test in 1954 — the largest US nuclear test ever conducted, more than 1,000 times the power of the Hiroshima bomb. The nation gained independence from US administration in 1986. Like Kiribati, the Marshall Islands faces a severe existential threat from rising sea levels.`,FM:`The Federated States of Micronesia is an island group of 607 islands in the western Pacific, organised into four states: Yap, Chuuk, Pohnpei, and Kosrae. The islands were administered by the United States under a UN Trusteeship until independence in 1986. Micronesia is celebrated for its extraordinary marine biodiversity, particularly the Japanese WWII wrecks in Chuuk Lagoon, which attract scuba divers from around the world.`,NR:`Nauru is the world's smallest island nation, a single oval-shaped island of just 21 square kilometres in the central Pacific, roughly halfway between Hawaii and Australia. In the 1970s, Nauru briefly had one of the world's highest per-capita incomes from phosphate mining, before deposits were exhausted and the island's interior left as a barren, strip-mined landscape. Today Nauru faces significant economic and environmental challenges and has the world's highest rates of obesity.`,NZ:`New Zealand is an island country in the southwestern Pacific known for its dramatic and diverse landscapes of fjords, mountains, volcanoes, beaches, and geothermal areas — landscapes that served as the filming location for the Lord of the Rings trilogy. New Zealand was the first country in the world to grant women the right to vote, in 1893. The indigenous Māori culture, with its haka, whakairo (carving), and te reo Māori language, has a deep and growing influence on national identity.`,PW:`Palau is an archipelago of more than 500 islands in the western Pacific, home to some of the world's most pristine marine ecosystems. Jellyfish Lake, where millions of jellyfish evolved without stingers due to the absence of predators, is one of Palau's most famous attractions. Palau gained independence from US administration in 1994 and has established some of the Pacific's strictest marine protection zones.`,PG:`Papua New Guinea occupies the eastern half of the island of New Guinea and is one of the world's most linguistically diverse countries, with over 800 languages spoken by a population of around 9 million — more languages than any other country on Earth. The country has extraordinary biodiversity with large areas of intact tropical rainforest and species found nowhere else. Papua New Guinea achieved independence from Australian administration in 1975.`,WS:`Samoa is a Polynesian island nation in the South Pacific consisting of two main islands and several smaller ones. It was the first Pacific Island country to gain independence, in 1962. Samoan culture is deeply centred on fa'a Samoa (the Samoan way), which emphasises community, family, and respect for elders. In 2011, Samoa shifted its position relative to the International Date Line to better align its trading week with Australia and New Zealand.`,SB:`The Solomon Islands is an archipelago of nearly 1,000 islands in the southwestern Pacific and was the site of some of the Pacific War's most strategically significant battles during World War II, particularly the Guadalcanal campaign of 1942-43. The islands have extraordinary marine biodiversity with some of the healthiest coral reefs in the Pacific. The Solomon Islands gained independence from Britain in 1978.`,TO:`Tonga is an archipelago kingdom of 169 islands in the South Pacific and is the last remaining Polynesian monarchy. It is the only Pacific nation never to have been fully colonised by a European power, maintaining sovereignty throughout the 19th century under the Tupou dynasty. Tongan culture has a passionate sporting tradition, particularly in rugby union, with the national team competing regularly in Rugby World Cups despite a population of just over 100,000.`,TV:`Tuvalu is one of the world's smallest, most remote, and most threatened nations — a Polynesian island group in the central Pacific with a highest point of just 4.6 metres above sea level. The country faces an existential threat from rising sea levels caused by climate change, with much of its land at risk of flooding and saltwater intrusion. Tuvalu licences its highly sought-after '.tv' internet domain extension for significant revenue, providing crucial income for this tiny nation.`,VU:`Vanuatu is an archipelago of 80 islands in the southwestern Pacific, gained independence from joint British-French colonial administration in 1980. It is notable for its extraordinary linguistic diversity — over 100 distinct local languages are spoken by a population of fewer than 300,000, giving it the world's highest concentration of languages per capita. Vanuatu is home to some of the world's most accessible active volcanoes, including Mount Yasur on Tanna island, where visitors can walk to the crater rim.`},i=Object.fromEntries(Object.entries(r).map(([e,t])=>[e,{code:e,summary:t,flagHistory:n[e]??[]}]));export{r as n,t as r,i as t};